window.__D("text/likkutei-sichot/c018",{"p":[[1301670077,"<h3>שיחה א</h3>\nא. על הפסוק \"נח איש צדיק תמים הי' בדורותיו\"<sup data-n=\"155\">1</sup>, איתא בזוהר<sup data-n=\"156\">2</sup>: \"אבל בדרין אחרנין אינו נחשב לכלום כגון דרא דאברהם ודרא דמשה ודרא דדוד\".\nוהנה פירוש בדיוק כזה (ש\"בדורותיו\" הכוונה לאפוקי בדורות אחרים — \"ל­גנאי\"), הובא בכמה מקומות ברז\"ל — בשינויים בנוגע להמכוון של הדורות האחרים: בגמ'<sup data-n=\"157\">3</sup> — \"בדורותיו ולא בדו­רות אחרים\" סתם; בתנחומא<sup data-n=\"158\">4</sup> — ש\"אילו הי' בדורו של אברהם אבינו לא מצא ידיו ורגליו\" (ועד\"ז הוא בפרש\"י עה\"ת \"אילו הי' בדורו של אברהם לא הי' נחשב לכלום\"); ובב\"ר<sup data-n=\"159\">5</sup> — \"אילו הי' בדורו של משה או בדורו של שמואל לא הי' צדיק\".\nוהנה, פירושו של התנחומא שהכוונה היא למעט \"בדורו של אברהם\" מובן בפשטות<sup data-n=\"160\">6</sup>, כי אברהם הי' הצדיק שבא בסמיכות<sup data-n=\"161\">7</sup> לאחר דורותיו של נח, ולכן מסתבר לפרש כוונת הכתוב \"צדיק תמים הי' בדורותיו\", שדוקא \"בדורותיו\" של נח<sup data-n=\"162\">8</sup> הי' צדיק תמים, אבל אילו הי' בדורו של אברהם שלאחרי \"דורותיו\" לא הי' נחשב לכלום;\nוגם הפירוש בב\"ר \"אילו הי' בדורו של משה או בדורו של שמואל\" י\"ל בפשטות<sup data-n=\"163\">9</sup>, שכוונתו למעט בה\"גנאי\", ד­דוקא בדורו של משה ודורו של שמואל לא הי' (נחשב ל)צדיק<sup data-n=\"164\">10</sup>, כי משה הי' מב­חר מין האנושי אביהן של כל הנביאים<sup data-n=\"165\">11</sup> אשר דבר ה' אתו פנים אל פנים<sup data-n=\"166\">12</sup>, וכן שמואל שהי' שקול כנגד משה ואהרן<sup data-n=\"167\">13</sup>, ולכן דוקא בדורותם לא הי' נח (נחשב ל)צדיק, אבל בדורות אחרים הי' (נחשב ל)צדיק וכו';\nאבל פירוש הזוהר, שדיוק הכתוב הוא בנוגע לשלשת הדורות, \"דרא דאב­רהם ודרא דמשה ודרא דדוד\" — דורש ביאור הטעם שדוקא בשלשה דורות אלה לא הי' \"נחשב לכלום\"<sup data-n=\"168\">14</sup>?",[["155","1","ריש פרשתנו."],["156","2","ס, א — בתוספתא."],["157","3","סנהדרין קח, סע\"א. וכן בתנחומא באבער פרשתנו ו."],["158","4","פרשתנו ה."],["159","5","פ\"ל, ט."],["160","6","וראה בארוכה במפרשי רש\"י כאן, בביאור הטעם שבגנאי נקט אילו הי' בדור אברהם, ולא כב\"יש דורשין אותו לשבח — כש\"כ שאילו הי' בדור צדיקים\" סתם."],["161","7","ויתירה מזו, נולד נ\"ח שנה לפני מיתת נח. וראה ראב\"ע ריש פרשתנו."],["162","8","ראה אבות פ\"ה מ\"ב: עשרה דורות מאדם ועד נח. . מנח ועד אברהם."],["163","9","וראה יפ\"ת השלם ונזר הקודש השלם לב\"ר."],["164","10","ראה רא\"ם ודברי דוד (להט\"ז) לפרש\"י (וכן ביפ\"ת ונזה\"ק לב\"ר) בתיווך ב' הפירושים — דורשים לשבח ודורשים לגנאי, שלכו\"ע אם הי' בדור צדיקים הי' צדיק יותר, ולכו\"ע מצבו דעתה לגבי דור צדיקים אינו נחשב כו'."],["165","11","פיה\"מ להרמב\"ם סנהדרין פ' חלק היסוד השביעי."],["166","12","תשא לג, יא. וראה בהעלותך יב, ח. ובארוכה בפיה\"מ שם. רמב\"ם הל' יסוה\"ת פ\"ז ה\"ד."],["167","13","הובא במפרשי המדרש — מתנחומא קרח ה. פרש\"י שם טז, ז. ועוד."],["168","14","בבאר בשדה על פרש\"י פרשתנו (ועד\"ז בנצוצי זוהר לזוהר פרשתנו שם), מפרש כוונת הזוהר — ששלשה צדיקים אלה בקשו רחמים על אנשי דורם: אברהם ביקש רחמים על אנשי סדום, \"משה ג\"כ ביקש רחמים על דורו כמה פעמים ואמר מחני נא (תשא לב, לב. וראה שם, יא ואילך) ודוד הע\"ה ג\"כ הי' מתפלל אפי' על אויביו וכדכתיב ואני בחלותם לבושי שק וכו' (תהלים לה, יג ובפרש\"י ומצ\"ד שם)\", וכן מצינו בדוד שאמר (ש\"ב כד, יז) תהי נא ידך בי וגו' (ראה מכילתא בא בתחלתה), משא\"כ נח לא התפלל על אנשי דורו \"וכמו שגינו אותו בזוה\"ק ובמדרש הנעלם\" (זח\"א סז, ב. קו, א. בהשמטות שם רנד, ב. ח\"ג טו, א ואילך. תקו\"ז תס\"ט (קיג, א). ז\"ח (מהנ\"ע) פרשתנו כג, א), ולכן נק' מי המבול \"מי נח\" כיון דלא בעי רחמי על דורו<sup data-n=\"e2\">*</sup>.\nאבל לכאורה דוחק לפרש כן בזוהר כאן, כי בזוהר בשאר המקומות, כשמדבר בהחסרון מה שנח לא בעי רחמי על עלמא, נאמר זה בניגוד לאברהם ומשה ולא נזכר דוד (ואולי י\"ל, לפי שלא מצינו שתפלת דוד תהי' בכללות על כלל ישראל, כ\"א על אויביו, או בנוגע למצב מסויים).\n[ולהעיר מזח\"א קו, א (וראה גם בהשמטות ובז\"ח שם) \"אוף אברהם לא עבד שלימו כדקא יאות\", דביקש רק אם יש עשרה צדיקים ולא בעי רחמי יותר, ורק משה עבד שלימו כדקא יאות]."],["e2","*","בבאר בשדה (וכן בנזה\"ק השלם לב\"ר) מפרש כן הכוונה במדרש \"אילו הי' בדורו של משה או בדורו של שמואל\" (דגם שמואל התפלל על דורו, כמו שמביא בבאר בשדה שם מש\"א יב, כג)."]]],[1301670078,"ב. ונ\"ל, דג' הצדיקים שבג' הדורות שנקט בזוהר — בהם ועל ידם היתה הת­חלת ג' העיקרים במילוי תכליתה וכוו­נתה של הבריאה (שהיא בשביל ישראל שנק' ראשית ובשביל התורה שנק' רא­שית<sup data-n=\"169\">15</sup>) — שהם ישראל, תורה ומלכות: אברהם אבינו הוא התחלת עם ישראל, עיקר מעלת משה היא שעל ידו ניתנה התורה לכלל ישראל, וישראל במצב דשלימות בעולם כשהם במצב דמלכות ודוד הוא ראשית והתחלת \"עיקר המל­כות\"<sup data-n=\"170\">16</sup>.\n[וג' צדיקים אלו נרמזים בשם אדם ר\"ת אברהם<sup data-n=\"171\">17</sup> דוד משה<sup data-n=\"172\">18</sup>, והיינו שהש­למת תכלית בריאת ה\"אדם\" היא ע\"י ג' אופני העבודה של אברהם משה ודוד].\nוזהו תוכן פירוש הזוהר, שהגם שנח \"ראה עולם חדש\"<sup data-n=\"173\">19</sup>, ובפשטות שהי' לאחר המבול — בדוגמת אדם הראשון שממנו בא כל מין האנושי, ונח גם מילא בעבודתו את התפקיד של \"אדם\"<sup data-n=\"174\">20</sup>, מ\"מ, לגבי ג' הצדיקים שבשלשה דורות אלו אינו נחשב לכלום<sup data-n=\"175\">21</sup>.\nוטעם הדבר מובן, כנ\"ל, כי עיקר התחלת העבודה במילוי כוונת הבריאה היתה ע\"י ג' הצדיקים (\"אדם\") בשלשה דורות אלה.\nג. ובפרטיות יותר י\"ל:",[["169","15","תנחומא (באבער) בראשית ג' וה'. פרש\"י ר\"פ בראשית."],["170","16","ל' הרמב\"ם הל' מלכים פ\"א ה\"ח."],["171","17","ראה אוה\"ת שופטים ע' תתנ; ר\"ה ע' א'שיג ואילך (ועוד) — שאברהם תיקן מה שקלקל אדם."],["172","18","במ\"א (ראה ערכי הכינויים לבעל סה\"ד בערכו (בהגהה)) מבואר הר\"ת אדם: אדם דוד משיח. ואכ\"מ."],["173","19","ב\"ר פ\"ל, ח."],["174","20","משא\"כ לפנ\"ז לא היו שייכות עבודות אלו, כי העולם הי' בשפל המצב."],["175","21","וזהו שמדייק בזוהר \"אבל בדרין אחרנין אינו נחשב לכלום\", ולא כלשון המדרש \"אילו הי' בדורו. . לא הי' צדיק\": במדרש מדובר אודות דרגת נח עצמו, שאף שבדורו הי' אדם הגון וצדיק, מ\"מ אילו הי' (במצב זה<sup data-n=\"e3\">*</sup>) בדורו של משה או בדורו של שמואל \"לא הי' צדיק\"; אבל בזוהר נקט בלשון הווה \"אבל בדרין אחרנין אינו נחשב לכלום\" (ולא \"אילו הי' כו'\"), והיינו דעבודת נח היא עבודה בשלימות, אלא שפעולת עבודה זו בנוגע ל\"דרין אחרנין\" אינה נחשבת לכלום [בסגנון אחר, \"אינו נחשב לכלום\" לא בא לבטל ולשלול עבודת נח, אלא להגדיר סוג ואופן עבודתו, כדלקמן בפנים]. וראה לקמן ס\"ח."],["e3","*","ראה לעיל הערה 10."]]],[1301670079,"החידוש בזה שלמרות גדלותו וצד­קתו של נח אין עבודתו נחשבת לכלום לגבי דרגת עבודתם של אברהם משה ודוד — הוא, משום שבעבודת נח עצמו היתה מעין העבודה המיוחדת שבג' דורות אלו ע\"י צדיקים הנ\"ל.\nוביאור הדברים יובן, בהקדם החידוש בעבודת האדם שבג' דורות אלו, שהם ג' שלבים ודרגות בסדר העבודה:\nבדרא דאברהם: על אברהם שהי' היהודי הראשון, נאמר<sup data-n=\"176\">22</sup> \"אחד הי' אבר­הם\", ש\"כל העולם כולו מעבר אחד והוא (אברהם) מעבר אחד\"<sup data-n=\"177\">23</sup> — כל העולם היו עובדי ע\"ז ו\"אברהם<sup data-n=\"178\">24</sup> עבד ונתחכם מאליו ועבד הקב\"ה\", ועמד בתוקף נגד כל העולם, וידע שכל העולם טועים<sup data-n=\"179\">25</sup> וכו'.\nוזהו גם הענין היסודי והראשי ב­עבודת האדם בכלל, שבנ\"י מתחזקים בדביקותם בה' ועומדים בתוקף בע­בודתם — נגד ע' האומות וכל העולם המונעים ומעכבים וכו'.\nדרא דמשה, דור מ\"ת: החידוש בה­עבודה של דור מ\"ת הוא, ש(לא רק שאין העולם מפריע לעבודת האדם, אלא להיפך) שעבודת האדם פועלת בעולם קיומו וביסוסו, וכמרז\"ל<sup data-n=\"180\">26</sup> עה\"פ<sup data-n=\"181\">27</sup> \"ארץ יראה ושקטה\" מתחלה יראה ולבסוף שקטה [דתנאי התנה הקב\"ה עם מעשה בראשית, \"אם ישראל מקבלים התורה אתם מתקיימין ואם לאו אני מחזיר אתכם לתהו ובהו\"<sup data-n=\"180\">26</sup>], דלפני מ\"ת היתה הארץ (העולם) במצב של \"יראה\", ועי\"ז שישראל קבלו את התורה — \"שקטה\".\nוזהו השלב הב' בעבודת האדם, קיום העולם ע\"י התורה, שע\"י עבודתם של בנ\"י בלימוד התורה וקיום המצות (האפשרי דוקא בעוה\"ז), פועלים קיום מציאותו של העולם.\nדרא דדוד: \"עיקר המלכות\"<sup data-n=\"170\">16</sup> היא מלכות בית דוד, שענינה הוא להמליך את הקב\"ה על העולם כולו. וכמו שהי' כפשוטו, שע\"י דוד הי' גמר כיבוש ארץ ישראל מאוה\"ע, ועד למצב שכולו מלכות תיכף בתחלתו כמו שהי' בימי שלמה, שהאומות הביאו מתנות לשלמה<sup data-n=\"184\">28</sup> — שע\"י מלכות בית דוד הי' גילוי מלכות הקב\"ה בעולם.\nוזהו החידוש בדרא דדוד על דרא דמשה, שע\"י התורה ומצות הוא קיום העולם כמו שהוא, וע\"י גילוי המלכות נפעלת עלי' בעולם,\nוהשלימות בזה תהי' ע\"י \"מלך\" האח­רון מבית דוד, שהוא \"משיח האחרון\"<sup data-n=\"185\">29</sup> הנקרא \"מלך מבית דוד\"<sup data-n=\"186\">30</sup> בביאת משיח צדקנו, שאז תתגלה מלכותו של הקב\"ה בעולם כולו, הן באוה\"ע, ש\"יתקן<sup data-n=\"186\">30</sup> את העולם כולו לעבוד את ה' ביחד ש­נאמר<sup data-n=\"188\">31</sup> כי אז אהפוך אל עמים שפה ברורה. . ולעבדו שכם אחד\", \"והלכו<sup data-n=\"189\">32</sup> עמים רבים ואמרו לכו ונעלה אל הר ה' אל בית אלקי יעקב ויורינו מדרכיו ונלכה באורחותיו\"; והן בכל הנבראים שבעולם — ש\"לא ירעו ולא ישחיתו בכל",[["176","22","יחזקאל לג, כד."],["177","23","ב\"ר פמ\"ב, ח. פס\"ר פל\"ג."],["178","24","פס\"ר שם."],["179","25","ראה בארוכה רמב\"ם הל' ע\"ז פ\"א ה\"ג."],["180","26","שבת פח, א. וש\"נ."],["181","27","תהלים עו, ט."],["180","26","שבת פח, א. וש\"נ."],["170","16","ל' הרמב\"ם הל' מלכים פ\"א ה\"ח."],["184","28","ראה מ\"א קאפיטל יוד."],["185","29","ל' הרמב\"ם הל' מלכים פי\"א ה\"א."],["186","30","רמב\"ם שם ה\"ד."],["186","30","רמב\"ם שם ה\"ד."],["188","31","צפני' ג, ט."],["189","32","ישעי' ב, ג."]]],[1301670080,"הר קדשי כי מלאה הארץ דעה את ה' כמים לים מכסים\"<sup data-n=\"190\">33</sup>.\n[יסוד וסמוכין לפירוש זה (בדברי הזוהר), יש למצוא בביאור אאמו\"ר ל­זוהר שם בפרשתנו<sup data-n=\"191\">34</sup>, וז\"ל: \"קחשיב אלו הג' אברהם משה דוד. הוא, כי אלו הג' הם הג' כתרים. כתר כהונה, כתר תורה, כתר מלכות<sup data-n=\"192\">35</sup>. כהונה אברהם איש ה­חסד, והכהונה ניתנה לאברהם, כמ\"ש<sup data-n=\"193\">36</sup> אתה כהן לעולם. תורה משה, כי התורה ניתנה ע\"י משה, ונקראת תורת משה. מלכות דוד, כי המלוכה ניתנה לדוד לעולם\",\nדענין \"כתר כהונה\" הוא ע\"ד משנת\"ל בגדר \"דרא דאברהם\", שהרי ענינו של הכהן הוא שהובדל לעבוד את ה' ולשרתו, שבכללות זהו ענינו של עם ישראל, ולא עוד אלא שגם התואר \"כהונה\" שייך לכל ישראל, כמ\"ש הרמב\"ם<sup data-n=\"194\">37</sup> שזה שייך לכ\"א \"להבדל לעמוד לפני ה' לשרתו ולעובדו לדעה את ה'\", ולפרוק \"מעל צוארו עול החשבונות הרבים אשר בקשו בני האדם (שאז) הרי נתקדש קודש קד­שים\"].\nד. והנה (מעין) שלשת אופני עבודה אלו היו אצל נח בתקופת המבול:\nא) בעבודתו בעצמו — שהיא בדוגמת מה שהי' אברהם \"מעבר אחד כו'\". דאף שהדור הי' בשפל המצב ביותר — \"הש­חית כל בשר את דרכו על הארץ\"<sup data-n=\"195\">38</sup>, מ\"מ התחזק נח ו\"צדיק תמים הי' בדורותיו\", ולא נגרר אחרי הנהגת כל הדור, ואדרבה \"הי' נח הצדיק מוכיח בהם ואומר להם עשו תשובה\"<sup data-n=\"196\">39</sup>.\nב) כמו כן הי' בעבודתו ענין של פעולה בעולם (ע\"ד פעולת מתן תורה<sup data-n=\"197\">40</sup>), שעל ידו היתה הצלת כל העולם כולו<sup data-n=\"198\">41</sup>, עד שהקב\"ה נשבע ש\"לא יכרת כל בשר עוד ממי המבול ולא יהי' עוד מבול לשחת הארץ\"<sup data-n=\"199\">42</sup>.\nג) ויתירה מזו: במעשי נח היתה גם פעולה של \"עלי'\" ושינוי בעולם (ע\"ד פעולת מלכות ב\"ד). דבתיבת נח היו כל מיני בהמות וחיות כו' וביניהן גם חיות טורפות ודורסות, ואעפ\"כ לא עשו שום רעה זה לזה כלל. ומבואר בזה<sup data-n=\"200\">43</sup>, שהוא לפי שבתיבת נח הי' שורר מצב של שלום ע\"ד מ\"ש לע\"ל<sup data-n=\"201\">44</sup> \"וגר זאב עם כבש גו' לא ירעו ולא ישחיתו גו'\", כי אז (בתיבת נח) הי' \"גילוי\" שלמעלה מגדרי העולם (כפי שהוא מצד עצמו).\n[ובאמת הי' מצב זה לא רק בהמצאם בהתיבה, אלא גם לפני כניסתם בה, וכ­מבואר ברז\"ל ובפרש\"י<sup data-n=\"202\">45</sup> שלא באו אל התיבה אלא אלה שדבקו במיניהם ולא השחיתו דרכם, ועוד זאת שמאליהם באו — שכל זה הוא נס נפלא וגדול ביותר:",[["190","33","שם יא, ט."],["191","34","לקלוי\"צ הערות לזח\"א ע' כב."],["192","35","אבות פ\"ד מי\"ג (ושם (ועד\"ז הוא בכ\"מ ברז\"ל) הוא בסדר אחר. ואכ\"מ)."],["193","36","תהלים קי, ד. וראה בארוכה אוה\"ת (יהל אור) עה\"פ שם ס\"ח (וש\"נ), שקאי על אברהם."],["194","37","סוף הל' שמיטה ויובל."],["195","38","פרשתנו ו, יב."],["196","39","סנהדרין קח, סע\"א. וראה גם פרש\"י פר­שתנו שם, יד."],["197","40","להעיר שנח למד תורה (פרש\"י פרשתנו ז, ב)."],["198","41","ובאופן ד\"לא ישבותו\" (פרשתנו ח, כב)."],["199","42","פרשתנו ט, יא."],["200","43","ד\"ה כי פדה לאדה\"ז (סה\"מ אתהלך לאזניא ע' נז­ח). ועם הגהות אוה\"ת פרשתנו (כרך ג) תרסט, א ואילך. המשך וככה תרל\"ז פצ\"ה­ו. ובכ\"מ — ראה בארוכה לקו\"ש חכ\"ה ע' 29 ואילך. וש\"נ."],["201","44","ישעי' יא, ו­ט."],["202","45","סנהדרין שם, ב. פרש\"י פרשתנו ו, כ."]]],[1301670081,"א) שבעלי חיים שבהעולם באים מ­אליהם; ב) המובחרים שבהם (מינים טהורים) באו שבעה שבעה, ומשאר המינים באו שנים שנים; ג) בלכתם אל התיבה הלכו בסדר מסודר כו' מבלי להזיק זל\"ז].\nוזהו עומק כוונת דברי הזוהר כאן, דהגם שעבודת נח היתה עבודה נעלית ומיוחדת, המתאימה להיות יסוד להנהגת העולם מחדש, ובמילא היו כלולות בה כל הג' דברים הנ\"ל, בהשלמת עבודת ה\"אדם\" בהבריאה [א) לעמוד על משמר­תו חזק באופן שלא יתפעל ולא יתחשב עם סביבתו; ב) לפעול יציבות וקיום ב­עולם; ג) להעלות את העולם למעלה יותר מכפי שהוא מצ\"ע גם בתכלית הטוב] — מ\"מ \"אינו נחשב לכלום\".\nוטעם הדבר, כי זה הי' מעין גדר חינוך בלבד<sup data-n=\"203\">46</sup> להשלמת הבריאה — ג' עבודות אלו כמו שהיו לאמיתתם, בדרא דאברהם בדרא דמשה ובדרא דדוד.\nה. וי\"ל הביאור בזה:\nאף ע\"פ שבעצם מעשה המצוה אין חילוק בין קיומה מצד \"חינוך\" בלבד לקיומה מצד החיוב (מצווה ועושה) — שהרי כשמחנכין את הקטן במצוה יש לחנכו (לכמה דיעות<sup data-n=\"204\">47</sup>) לעשות בהכשר גמור כגדול — מ\"מ יש הפרש יסודי ביניהם בתוכן ענין הקיום, והוא: ענין החינוך אינו אלא להרגיל את הקטן במצות שיתחייב בהן בגדלותו<sup data-n=\"205\">48</sup>, שזהו בעיקרו ענין של מניעה והפרשה, והיינו, שלהיות ש\"עיר<sup data-n=\"206\">49</sup> פרא אדם יולד\", יש לחנכו ולהרגילו שילך בדרך הישרה באופן שכשיגדל ילך בדרך התורה<sup data-n=\"207\">50</sup>.\nומטעם זה: א) אף שהחינוך הוא בכל המצות, חובת החינוך היא במצות ל\"ת יותר מבמ\"ע<sup data-n=\"208\">51</sup>; ב) \"מחנכין אותן (ה­קטנים) לעבוד מיראה\"<sup data-n=\"209\">52</sup>, והיינו שאופן קיום המצות של הקטן אינו באופן של קיומו של הגדול המחוייב, ש\"עושה האמת מפני שהוא אמת\"<sup data-n=\"210\">53</sup>.\nונמצא שעיקר החילוק בין גדר חינוך דקטן לקיום המצות דגדול הוא — דה­קיום מצד חינוך אין בו תכלית לעצמו, אלא תכליתו שיהי' מחונך ורגיל במצות שיתחייב בהן בגדלותו; ואילו קיום ציוויי ה' בגדול הרי תכליתו הוא בה­קיום עצמו — לקיים ציוויי ה'.\nוזהו החילוק בין עבודת ופעולת נח בשלשת הענינים הנ\"ל (ישראל, תורה ומלכות), שהיתה רק בגדר חינוך, ובין עיקר ענינן כפי שהיו ב(דרא ד)אברהם, משה ודוד<sup data-n=\"211\">54</sup>:",[["203","46","ראה לקו\"ש חכ\"ב ע' 5 (באו\"א קצת) בפרטיות יותר לגבי קרבנות דנח, דתקופת האבות הוי כחינוך, וקרבנות נח לפני זמן החינוך. ולהעיר דמאברהם התחיל ב' אלפים תורה (ע\"ז ט, א)."],["204","47","ריטב\"א סוכה ב, ב (ד\"ה אר\"י מעשה). ר\"ן יומא פב, א (במשנה)."],["205","48","ראה רש\"י סוכה שם ד\"ה מדרבנן; חגיגה ו, א ד\"ה קטן."],["206","49","איוב יא, יב ובמפרשים."],["207","50","ראה בארוכה של\"ה (שער האותיות דרך ארץ) סג, ב ואילך."],["208","51","ראה שו\"ע אדה\"ז או\"ח סשמ\"ג ס\"ב ואילך.\nחינוך קטן שבתניא בתחלתו (ראה תניא עם ליקוט פי' כו' — שם). — הדיעות בזה ראה אנציקלופדי' תלמודית ערך חינוך קרוב לסופו. וש\"נ. ולהעיר מפרמ\"ג פתיחה כוללת ח\"ב אות ג' בתחילתו."],["209","52","ל' הרמב\"ם הל' תשובה פ\"י ה\"א וה\"ה."],["210","53","רמב\"ם שם ה\"ב."],["211","54","וזהו הפי' בזוהר \"אבל בדרין אחרנין אינו נחשב לכלום\", דאף שחינוך הוא יסוד האדם, וכמ\"ש (משלי כב, ו) \"חנוך לנער על פי דרכו גם כי יזקין לא יסור ממנה\", הרי אופן ודרך העבודה דחינוך לגבי אופן ודרגת העבודה דגדול המצווה ועושה בקיום המצות לשמה \"אינו נחשב לכלום\"."]]],[1301670082,"זה שנח \"תמים הי' בדורותיו\", כלומר ביחס לאנשי דורו, הרי זה (בעיקר) באותם ענינים של רשעות הדור ההוא. וכיון שעיקר רשעות של אותו הדור היתה בענינים שבין אדם לחבירו, גזל וזנות כו' \"ולא נחתם גזר דינם (של דור המבול) אלא על הגזל\"<sup data-n=\"212\">55</sup>, נמצא, שעבודת נח היתה ג\"כ (בעיקרה) בענינים שבין אדם לחבירו. דעניני \"בין אדם לחבירו\" הרי אין בהם (בכללות, ביחס לעניני \"בין אדם למקום\") תכלית בפ\"ע אלא רק כדי שלא לבלבל \"ישובו של עולם\", ע\"ד ענין החינוך, שאין התכלית בו עצמו אלא כדי להרגיל את המחונך ולהכינו לזמן החיוב (כנ\"ל). ועוד זאת: זה גופא לא הי' כ\"כ מצד הכרתו ואמונתו בהקב\"ה אלא מצד המבול, דכשם שקריאתו לאנשי דורו לעוררם לתשובה היתה מבוססת על האזהרה דהעונש שהקב\"ה יביא עליהם את המבול, עד\"ז מובן שגם עבודתו הוא היתה בעיקר ביראת העונש, ועד שארז\"ל<sup data-n=\"213\">56</sup> שלא נכנס לתיבה עד שדחקוהו המים, שגם פרט זה הוא כמו \"חינוך\" מיראה.\nמשא\"כ ב\"דרא דאברהם\", הרי (א) עיקר החידוש דאברהם (שכל העולם מעבר אחד ואברהם מעבר אחד) הי' לא (רק) בדברים שבין אדם לחבירו, אלא בעניני אמונה — שלילת ע\"ז וחיזוק אמונה בה'; (ב) הכרת אברהם בהקב\"ה (וכן פעולתו בעולם — ש\"התחיל להודיע לעם שאין ראוי לעבוד אלא לאלוקה העולם. . ולקרוא בקול גדול לכל ה­עולם ולהודיעם שיש שם אלוקה אחד לכל העולם ולו ראוי לעבוד\"<sup data-n=\"214\">57</sup>) באה מזה שהי' \"לבו משוטט ומבין עד שהשיג דרך האמת והבין קו הצדק מתבונתו הנכונה\"<sup data-n=\"214\">57</sup>, ולא מצד יראת העונש או לטובת עצמו. ואדרבה, מסר נפשו על אמונה בה'<sup data-n=\"214\">57</sup>. וכמ\"ש הרמב\"ם<sup data-n=\"210\">53</sup> ד\"עושה האמת מפני שהוא אמת\" היא מעלת אברהם אבינו.\nוהוא הדבר גם בענין הב' — הצלת וקיום העולם: זה שלאחר המבול נתחדש ש\"לא אוסיף לקלל עוד את האדמה בעבור האדם. . ולא אוסיף עוד להכות את כל חי כאשר עשיתי. . לא יכרת כל בשר עוד ממי המבול ולא יהי' עוד מבול לשחת הארץ\"<sup data-n=\"218\">58</sup>, הוא (רק) ענין של מניעת דברים בלתי רצויים<sup data-n=\"219\">59</sup>, שלילת איבוד העולם (ע\"ד החינוך להסיר את הנטי' השלילית שבאדם), משא\"כ בדרא דמשה, ע\"י מ\"ת, נתוסף קיום וחיזוק חיובי במציאות העולם, שרק אז הוצדק קיום העולם.\nוכן בענין הג': המצב של שלום ונסים שהיו בתיבה בזמן המבול (ועד\"ז בעת ההכנה כו' להמבול) — הי' ג\"כ מצד הכרח ההצלה ו\"לחיות זרע על פני כל הארץ\"<sup data-n=\"220\">60</sup>,\nואילו ב\"דרא דדוד\" — היינו מלכותו של דוד, שעל ידו היתה ההכנה לבנין המקדש<sup data-n=\"221\">61</sup> עם עשרת הנסים שנעשו לאבותינו בביהמ\"ק<sup data-n=\"222\">62</sup> — הי' אז גילוי",[["212","55","ראה פרש\"י ו, יא­יב."],["213","56","ב\"ר פל\"ב, ו. פרש\"י פרשתנו ז, ז."],["214","57","רמב\"ם הל' ע\"ז פ\"א ה\"ג."],["214","57","רמב\"ם הל' ע\"ז פ\"א ה\"ג."],["214","57","רמב\"ם הל' ע\"ז פ\"א ה\"ג."],["210","53","רמב\"ם שם ה\"ב."],["218","58","פרשתנו ח, כא. ט, יא."],["219","59","ולהעיר דגם שמו של נח הוא ע\"ש \"זה ינחמנו ממעשינו ומעצבון ידינו גו'\" (בראשית ה, כט) — נחמה ממצב בלתי רצוי."],["220","60","פרשתנו ז, ג."],["221","61","ד\"בכל כחי הכינותי לבית אלקי גו'\" (דה\"א כט, ב). והביהמ\"ק נק' על שמו — ראה תנחומא נשא יג. רש\"י נשא ז, א. וגם (לאחרי בנין הבית) פתיחת השערים היתה רק לאחר שאמר שלמה (דה\"ב ו, מב) \"זכרה לחסדי דוד\" (שבת ל, א)."],["222","62","אבות פ\"ה מ\"ה."]]],[1301670083,"מלכותו של הקב\"ה מצד השראת שכינתו בביהמ\"ק, ועד שכל העמים ראו גודל פעולת ומעלת מלכי בית דוד והתועלת דביהמ\"ק (כנ\"ל בימי שלמה), ובפרט כאשר תהי' השלימות בזה לע\"ל, שאז \"לא ירעו ולא ישחיתו בכל הר קדשי כי מלאה הארץ דעה את ה' כמים לים מכסים\".\nו. ועוד יש לומר, בעומק יותר — ע\"פ מ\"ש אאמו\"ר (בהערותיו הנ\"ל), שאברהם משה ודוד, הם ג' הכתרים כתר כהונה כתר תורה וכתר מלכות, וממשיך שם, ש\"בנח לא הי' כ\"ז, רק כתר שם טוב, שבדורותיו הי' לו שם טוב, שהוא למטה מכל אלו הג'\":\nהתואר דכתר כהונה כתר תורה וכתר מלכות, מורה שענינם הוא למעלה מהראש, כמו כתר כפשוטו שהוא למעלה מראשו של האדם, כלומר, דרגת עבודה שאין האדם מגיע לה בכח עצמו ושכלו, אלא היא למעלה הימנו. ובסגנון אחר: זהו דבר הבא מצד גדרו של הבורא ולא מצד גדרו של הנברא. לאידך, כשהאדם מוכתר בכתר — כתר כהונה כתר תורה וכתר מלכות — אין זה באופן שרוכש דבר חיצוני שהוא דבר נוסף עליו, אלא זה נעשה כל מציאותו (שהוא מוכתר בכתר זה)<sup data-n=\"223\">*62</sup>.\nוי\"ל שזהו החילוק בין עבודת נח בג' ענינים אלו בהשלמת כוונת הבריאה, דהוי בגדר \"חינוך\", לעבודות ג' הדורות דאברהם דמשה ודדוד, דהוי באופן ד\"כתר\":\nעבודתו של נח ומצבו של העולם לאחר המבול, היו רק כפי שהנברא יכול להגיע לזה בכחו<sup data-n=\"224\">63</sup>, ובמילא, הן בע­בודתו לעצמו והן בפעולתו בקיום העולם, לא הי' בזה יציאה מגדר העולם והבריאה — הבריאה נשארה בסוגה וגדרה, שאין לה שייכות (גלוי') להבורא. ואילו העבודה בדרא דאברהם<sup data-n=\"224\">63</sup> דרא דמשה ודרא דדוד היתה באופן דכתר, מצד הקב\"ה שלמעלה מהבריאה, ופשוט שאופן עבודת הנבראים לגבי עבודה הבאה מכח שלמעלה מהבריאה \"אינו נחשב לכלום\".\nז. הביאור בזה בפרטיות:\nעבודת<sup data-n=\"224\">63</sup> ה' דנח היתה קשורה עם אלקות כפי שצמצם עצמו כביכול לפי ערך הבריאה, ולכן פעלה אצלו ובו השגתו בהקב\"ה רק שלא יגרר אחר שאר בני אדם בהשחתת העולם, היפך ישובו של עולם, ולא למעלה מזה. משא\"כ באברהם, אף שהתחלת קירובו להקב\"ה היתה ע\"י ראיות מעניני ה­בריאה, היתה הכרתו בהקב\"ה (גם) כפי שהוא למעלה מהבריאה<sup data-n=\"227\">64</sup>, בחי' \"כתר\", ולכן הגיע לדרגת מסירת נפש ש\"עושה האמת מפני שהוא אמת\".\nוכן הוא בענין הב' והג', דמה שנפעל בעולם לאחרי המבול \"לא אוסיף לקלל. . לא יכרת כל בשר גו'\" והמצב ה­מיוחד שהי' בתיבת נח, אין זה (א) שינוי אמיתי במצב העולם ולא (ב) עלי' אמיתית במצב העולם.\nמשא\"כ פעולת דרא דמשה שע\"י התורה, דהיינו קיום העולם, הרי התורה",[["223","*62","ראה לקו\"ש חכ\"ז ע' 245. חלק לד ע' 43 ואילך."],["224","63","להעיר מלקו\"ש חט\"ו ע' 87 ואילך."],["224","63","להעיר מלקו\"ש חט\"ו ע' 87 ואילך."],["224","63","להעיר מלקו\"ש חט\"ו ע' 87 ואילך."],["227","64","ראה ד\"ה מי העיר תש\"ג רפ\"ט. וראה ד\"ה כל הנהנה תרפ\"ט (סה\"מ קונט' ח\"א) פ\"ט."]]],[1301670084,"קדמה לעולם<sup data-n=\"228\">65</sup>, והפעולה ע\"י התורה מותנית בתנאי (וכנ\"ל שתנאי התנה הקב\"ה עם מעשה בראשית אם יקבלו ישראל את התורה מוטב ואם לאו אחזיר אתכם לתהו ובהו)<sup data-n=\"229\">66</sup>, וכל מציאות העולם התהוותה הוא בשביל התורה שנק' ראשית,\nולמעלה מזה הוא דרא דדוד — ענין המלכות, גילוי מלכותו של הקב\"ה בעו­לם, שהיתרון בזה על הפעולה בעולם שמצד התורה הוא, שפעולת התורה בעולם אינה שייכת (כ\"כ) למציאות העו­לם עצמו, כי התורה ניתנה רק לישראל, אלא שעי\"ז שישראל קבלו את התורה וע\"י לימוד התורה וקיום המצות דישר­אל, נפעל גם בעולם;\nמשא\"כ במלכות, הרי כשם שהוא בנוגע למלכותא דארעא, שגדר המלכות הוא שזה נוגע לעצם מציאות העם, שכל מציאותם הוא המלך, עד שכל המורד במלכות חייב מיתה, שאין זה בדרך עונש אלא מסובב הבא בדרך ממילא, ועד\"ז הוא במלכות שמים, שגם קב\"ע מלכות שמים שע\"י הביטול למלך (שבעיקרו הוא במלכות בית דוד) הוא באופן שהביטול הוא בעצם מציאותם<sup data-n=\"230\">67</sup>,\nהנה עד\"ז הוא בפעולת המלכות ב­עולם, שכאשר מגלים את מלכותו של הקב\"ה בעולם, אין זה כדבר נוסף על מציאות הבריאה והעולם, אלא שזהו כל מציאות העולם, שנרגש ונגלה בו הקב\"ה מלך העולם. וכמודגש בכתוב הנ\"ל \"כי מלאה הארץ דיעה את ה' כמים לים מכסים\", שזהו כל מציאות הארץ, ע\"ד \"מים לים מכסים\", שאין הים דבר בפ\"ע אלא כל מציאות הים הוא מה שהוא מלא מים.\nח. והנה בענין זה יש הוראה בעבודת האדם (כמו בכל דבר בתורה).\nוי\"ל שזהו דיוק לשון הזוהר \"אבל בדרין אחרנין אינו נחשב לכלום\" — בלשון הווה, ולא בלשון עבר כמו (בתנ­חומא) \"אילו הי' בדורו של אברהם לא מצא ידיו ורגליו\", או כבב\"ר \"לא הי' צדיק\", כי עיקר הכוונה בזוהר אינה לדבר ח\"ו בגנותו של נח, אלא (ובעיקר) בתור הוראה בעבודת כל איש ישראל<sup data-n=\"231\">68</sup>, דגם עכשיו ישנה העבודה דנח, וע\"ז אומר, שלגבי העבודה (עתה) ב\"דרא דאברהם, דרא דמשה ודרא דדוד\" — אופן העבודה דנח \"אינו נחשב לכלום\".\nכלומר:\nהעבודה בג' ענינים כלליים אלה, ישנה כמו שהיא מצד האדם, שהאדם (הנברא) בא למסקנא, שהדרך הרצוי' היא לא להגרר אחרי הסביבה ולא להתפעל ממנה, ולעמוד בתוקף בעבודתו לקונו, ולפעול בעולם ע\"י תורה ויתירה מזו לגלות מלכותו של הקב\"ה בעולם.\nוע\"ז מלמדנו פירוש הזוהר, שכל ג' עבודות אלו צריכות להיעשות לא (רק) מצד הכרת הנברא, אלא מצד הבורא,",[["228","65","ראה פסחים נד, א. מדרש תהלים צ, ד. ב\"ר פ\"ח, ב. ועוד."],["229","66","ראה לקו\"ש ח\"ו ע' 91 ואילך."],["230","67","ראה בארוכה בכ\"ז לקו\"ש ח\"ח ע' 25 ואילך. וש\"נ."],["231","68","ראה לקו\"ש חכ\"ה ע' 20 ואילך בביאור דברי המדרש והזוהר, דמה שיש דורשין אותו לגנאי אין הכוונה לספר חסרונו וגנותו של נח — שהרי אפי' בגנות בהמה טמאה לא דיבר הכתוב (ב\"ב קכג, א) — אלא דורשים איך צ\"ל הנהגת כאו\"א, שלא תהי' הנהגתו באופן של גנאי. ע\"ש בארוכה."]]],[1301670085,"מצד הקב\"ה, שזהו בחי' כתר כהונה כתר תורה כתר מלכות, עבודה הבאה מלמעלה משכל האדם שהוא בראש. וכנ\"ל<sup data-n=\"232\">69</sup>.\n<span data-k=\"q\">(משיחות ש\"פ נח תשמ\"ה, תשמ\"ט)</span>",[["232","69","ראה זהר שם פי' הב' \"ק\"ו אילו הי' בדרא דכלהו צדיקים\", וכהדרש לשבח בסנהדרין, ב\"ר ורש\"י (הנ\"ל ס\"א).\nוע\"פ הידוע דאלו ואלו דא\"ח, ובפרט ע\"פ פי' המפרשים (הנ\"ל הערה 10) דבנדו\"ד לא פליגי — יש לפרש ע\"פ הנ\"ל ס\"ה:\nזה שנת\"ל שאופן עבודת ותקופת נח \"אינו נחשב לכלום\" להיותה בגדר חינוך שאינו תכלית בפ\"ע אלא הוא הכנה להעיקר כו', זהו בחיצוניות ובגלוי, אבל בפנימיות ושרש הענין הוא להיפך. וכמבואר במ\"א הטעם לזה שאין חינוך מצוה מן התורה, כי הוא \"למעלה\"<sup data-n=\"e4\">*</sup> מענין המצות ושייך להתקשרות עצמית שבין ישראל להקב\"ה [וראה שו\"ע אדה\"ז (או\"ח מהדו\"ת ס\"ד סוס\"ב) ד\"תחילת כניסת נפש זו הקדושה היא בחינוך לתורה ולמצות\"]. וזהו גופא הטעם לזה שחינוך הוא יסוד לכל משך חיי האדם ד\"גם כי יזקין לא יסור ממנה\", כי קיום המצות באופן דחינוך מצד תמימות ופשטות דקטן, תוכנו ופנימיותו הוא התקשרות עצמית דנפש הקדושה עם הקב\"ה, וענין זה בקיום המצות אינו בטל ממנו לעולם (ראה ספר השיחות תשמ\"ח ח\"ב ע' 615 ואילך).\nועפ\"ז ה\"ז בהתאם להמבואר (המשך תער\"ב ח\"א פר\"א) ד\"ויזכור אלקים את נח\" (פרשתנו ח, א) הוא \"מצד עצם מעלת נש\"י\", וכמבואר בלקו\"ש חכ\"ב שם."],["e4","*","ראה לקלוי\"צ שם, שכתר שם טוב \"הוא מה שפירנס י\"ב חדש את כל הבעלי חיים שהם בחי' בי\"ע. . ובי\"ע הם למטה מהג' קוין דאצילות\". וראה שם התיווך לפי' הב' \"ק\"ו אילו הי' בדרא דכולא צדיקים\", דכש\"ט — \"אם שבעצם הוא למטה מהג' כתרים אך עולה על גביהן\". ע\"ש."]]],[1301670086,"<h3>שיחה ב</h3>\nא. גרסינן במס' זבחים<sup data-n=\"233\">1</sup>: \"עד שלא הוקם המשכן הבמות מותרות כו' והכל כשירין ליקרב, בהמה חי' ועוף זכרים ונקבות תמימין ובעלי מומין טהורין. . דאמר קרא<sup data-n=\"234\">2</sup> ויבן נח מזבח לה' ויקח מכל הבהמה הטהורה ומכל עוף הטהור. . לאפוקי מחוסר אבר. . שנאסר לבני נח<sup data-n=\"235\">3</sup>. . ומכל החי מכל בשר<sup data-n=\"236\">4</sup> אמרה תורה הבא בהמה שחיין ראשי איברין שלה\". כלומר, אף שלב\"נ ליכא איסור הקרבת בעל מום כשמקריב בבמה (ועד\"ז בקר­בנות שלפני מ\"ת), מ\"מ, יש איסור<sup data-n=\"237\">5</sup> הקרבת מחוסר אבר.\nולכאורה משמע, דבעל מום ומחוסר אבר הם ב' שמות ואיסורים שונים<sup data-n=\"238\">6</sup>, ד\"מום\" פירושו כל פגימה שהיא, עד שיש מום שאינו מחמת חסרון באבר אלא רק שינוי לגבי אבר רגיל, משא\"כ מחו­סר אבר פירושו כמשמעו, חסרון.\nאבל נ\"ל דאינו כן, ע\"פ דיוק ל' הש\"ס<sup data-n=\"239\">7</sup> (בסיפור דקמצא ובר קמצא), דכאשר שלח הקיסר קרבן לישראל ל­הקריב ע\"ג המזבח, הרי \"בהדי דקאתי שדא בי' מומא בניב שפתים ואמרי לה בדוקין שבעין, דוכתא דלדידן הוה מומא ולדידהו לאו מומא הוא\" (וב­פרש\"י: לדידהו לא הוי מומא להקריב לגבוה בבמה דידהו אלא מחוסר אבר). ומדיוק הלשון \"ולדידהו לאו מומא הוא\" (ולא — \"לאו פסול הוא\" וכיו\"ב), משמע, דגם אצל ב\"נ הפסול דמחוסר אבר הוי מפני השם ד\"בעל מום\"<sup data-n=\"240\">8</sup>, אלא דאצלם רק \"מחוסר אבר\" נחשב \"בעל מום\" (וכשאינו חסר אבר נחשב תמים), משא\"כ לדידן גם \"בדוקין שבעין\" הוי מומא.\nויש לבאר זה ע\"פ משנ\"ת במ\"א<sup data-n=\"241\">9</sup> באורך, שיש כמה דרגות ואופנים בענין השלימות והתמימות, וע\"ד דרשת רז\"ל<sup data-n=\"242\">10</sup> עה\"פ<sup data-n=\"243\">11</sup> \"שנה תמימה\" — \"להביא את חודש העיבור\", דאף שגם שנה פשוטה נקראת שנה<sup data-n=\"244\">12</sup> (שלימה) שלא חסר בה מאומה, מ\"מ אינה \"שנה תמימה\", שתואר זה הוא רק לשנה מעוברת שיש בה י\"ג חדשים<sup data-n=\"245\">13</sup>. והיינו לפי שהתואר \"תמימה\" מורה לא רק על שלילת חסרון, אלא על",[["233","1","קטו, ב — קטז, א."],["234","2","פרשתנו ח, כ (ושם: העוף)."],["235","3","ראה גם ע\"ז ה, ב. נא, א. ירושלמי — פסחים פ\"ט ה\"ה; מגילה פ\"א הי\"א; סוטה פ\"ט ה\"ה — וקה\"ע ופ\"מ שם."],["236","4","פרשתנו ו, יט."],["237","5","ראה תוד\"ה מנין — ע\"ז ה, סע\"ב ובגליון הש\"ס שם. משנה למלך הל' מלכים פ\"י ה\"ז (ד\"ה ודע שמה שתירצו)."],["238","6","ולהעיר דפסול מום הוא רק \"מאבראי\", משא\"כ מחוסר אבר (ראה בכורות לט, א. רמב\"ם הל' איסורי מזבח פ\"ב הי\"א. מנ\"ח שהובא לקמן סעיף ב)."],["239","7","גיטין נו, א."],["240","8","ראה גם ל' רש\"י תמורה (ז, א ד\"ה בני נח) \"ב\"נ נצטוו מלהקריב מחוסרי אברים. . אבל על מום אחר לא כו'\", הרי ש\"מום\" ו\"חסר\" הם שם א'. ולהעיר גם מל' חז\"ל (קידושין סו, ב) \"בעל מום דעבודתו פסולה. . כשהוא שלם ולא כשהוא חסר\" (ולא \"כשהוא בעל מום\")."],["241","9","ראה לקו\"ש ח\"ל ע' 45 ואילך. וראה גם לקו\"ש חי\"ח ע' 129 ואילך. ועוד."],["242","10","ערכין לא, א (במשנה)."],["243","11","בהר כה, ל."],["244","12","ראה ר\"ן נדרים סג, א במשנה (בשם הרשב\"א). שו\"ת נוב\"י מהד\"ק אה\"ע ס\"כ."],["245","13","או שנת החמה (ראה דעת רבי במשנה ערכין שם ובפרש\"י. רש\"י פרשתנו ח, יד)."]]],[1301670087,"תמימות ושלימות נוספת (שגם בלעדה אין הדבר חסר).\nושני ענינים אלה מצינו בענין הקר­בנות (דישראל) גופא, ובלשון הרמב\"ם<sup data-n=\"246\">14</sup> \"מ\"ע להיות כל הקרבנות תמימין ומוב­חרין\", שהם ב' דינים שונים, ד\"תמימין\" היינו שהקרבן צ\"ל שלם, ועוד זאת, שצ\"ל \"מובחר\" (\"מבחר נדריכם\"<sup data-n=\"247\">15</sup>), וכמבואר ברמב\"ם<sup data-n=\"248\">16</sup> התנאים הנדרשים שהקרבן יהי' \"מובחר\" (אף שגם בלעדם אינו בעל מום).\nולפ\"ז יש לומר, שעד\"ז הוא החילוק בין קרבנות דישראל וקרבנות ב\"נ: בקרבנות דישראל (לאחר מ\"ת) נדרשת שלימות ותמימות יתירה, שגם פגם (או שינוי) בהאבר עצמו נחשב כחסרון ומום; משא\"כ לגבי השלימות והתמימות שב­קרבנות דב\"נ (וכן בקרבנות דכ\"ע דקודם מ\"ת), הרי רק מחוסר אבר הוי בגדר מום (היפך השלימות), ואילו מום ופגם בה­אבר עצמו \"לאו מומא הוא\".\nב. בדרך זו יש לבאר דברי הרמב\"ם<sup data-n=\"249\">17</sup> גבי קרבן עוף, שכתב: \"אין המומין פוסלין בעוף. . שלא נאמר<sup data-n=\"250\">18</sup> תמים זכר אלא בבהמה בלבד, בד\"א במומין קטנים אבל עוף שיבש גפו או נסמית עינו או נקטעה רגלו אסור לגבי המזבח שאין מקריבין חסר כלל\".\nוהנה דין זה (שמחוסר אבר פסול גם בעוף) ילפינן בגמ'<sup data-n=\"251\">19</sup> (וכן בתו\"כ<sup data-n=\"252\">20</sup>) ממ\"ש \"מן העוף<sup data-n=\"253\">21</sup>, ולא כל העוף\". ולפ\"ז יש מקום לומר, דדין \"תמות\" לא נאמר כלל בעוף, וכפשטות לשון הברייתא<sup data-n=\"254\">22</sup> \"אין תמות. . בעופות\", אלא שיש לימוד מיוחד למעט מחוסר אבר גם בעוף (וכפי שהאריך במנחת חינוך<sup data-n=\"255\">23</sup>, וע\"ש גם ה­נפק\"מ להלכה).\nאבל הרמב\"ם ברור דברו, דהא שמ­חוסר אבר פסול בעוף הוא (לא מפני הלימוד ד\"מן העוף\", אלא) לפי \"שאין מקריבין חסר כלל\", שדין זה (א) אינו מיוחד בעוף אלא הוא כלל בכל קרבן, (ב) נלמד (כמ\"ש הרמב\"ם לפנ\"ז<sup data-n=\"256\">24</sup>) מ­מ\"ש<sup data-n=\"257\">25</sup> \"תמימים יהיו לכם\", היינו שגם הפסול דמחוסר אבר בעוף יסודו בדין \"תמות\"<sup data-n=\"258\">26</sup>.",[["246","14","ריש הל' איסורי מזבח."],["247","15","פ' ראה יב, יא."],["248","16","שם פ\"ב ה\"ח."],["249","17","שם רפ\"ג."],["250","18","אמור כב, יט."],["251","19","קידושין כד, סע\"ב. — הובא גם ברמב\"ם בפיה\"מ שלו זבחים פ\"ז מ\"ה."],["252","20","ויקרא א, יד. הובא בפרש\"י עה\"ת שם."],["253","21","ויקרא שם."],["254","22","קידושין שם. וש\"נ. תו\"כ ופרש\"י שם."],["255","23","מצוה רפו."],["256","24","פ\"ב הי\"א."],["257","25","פינחס כח, לא. — ועפ\"ז מתורץ זה שהביא הרמב\"ם כתוב זה, אף שבש\"ס (בכורות לט, א) הובא הכתוב דאמור (כב, כא) \"תמים יהי' לרצון\", כי הכתובים דפ' אמור לא קאי בעוף, כמ\"ש הרמב\"ם כאן (רפ\"ג, והוא מתו\"כ אמור שם, יט) \"שלא נאמר תמים זכר אלא בבהמה בלבד\", ולכן הביא הכתוב דפינחס."],["258","26","וכן משמע בלח\"מ לרמב\"ם שם פ\"ג ה\"ג. ע\"ש. וראה ל' הרמב\"ם הל' אבות הטומאה פ\"ג הי\"ג.\nוצ\"ע במנ\"ח שם, שכ' בדעת הרמב\"ם \"דמחוסר אבר פסול בעוף אינו מטעם תמים<sup data-n=\"e5\">*</sup>. . אלא מלימוד אחר מן העוף\", והרי ברמב\"ם לא הובא הלימוד ד\"מן העוף\", ומלשונו \"שאין מקריבין חסר כלל\" מוכח להיפך, כבפנים."],["e5","*","וראה מנ\"ח מצוה תקל, שמתרץ קושיית הכס\"מ (הל' רוצח פ\"י ה\"ב) בדברי הרמב\"ם (שם) דאין המומין פוסלין בעגלה ערופה ואעפ\"כ טריפה פסולה, דלמה השמיט הרמב\"ם פסול מחוסר אבר (כמ\"ד בירושלמי סוטה שבהערה 3, שפסק כוותי' לגבי טריפה) — דפשוט דמחוסר אבר פסול ואינו כבעל מום, כיון דמחוסר אבר \"אינו מטעם מום דגם בעוף פסול\".\nאבל כבר תירצו במפרשים שלא הוצרך הרמב\"ם לפרט מחוסר אבר כי נלמד במכ\"ש מטריפה (מעשה רקח לרמב\"ם שם, ע\"פ חולין יא, א). ועוד. ולהעיר שבמראה הפנים לירושלמי שם תי' השמטת הרמב\"ם, ד\"הואיל וגלי רחמנא בעגלה להכשיר בה מומין הה\"ד למחוסר אבר\". ויומתק ע\"פ המבואר בפנים [אלא ששם כ' זה לפמ\"ש בדעת הרמב\"ם דגם לב\"נ מחוסר אבר כשר כמו בעל מום, כיון שהרמב\"ם לא הביא בחיבורו פסול מחוסר אבר לב\"נ (וכמו שהעיר גם המנ\"ח מצוה רפו שם). וצ\"ע. ואכ\"מ]."]]],[1301670088,"ועפ\"ז צ\"ע, דכיון שגם קרבן עוף הוא בכלל \"תמימים יהיו לכם\", מהי ההסברה שאינו בדין \"תמים\" השולל בעל מום?\nוע\"פ הנ\"ל יש לומר, שס\"ל להרמב\"ם, שאין בעל מום ומחוסר אבר ב' שמות נפרדים, שרק חד מינייהו (מחוסר אבר) ישנו בעוף, אלא שגדר התמימות הנדרש בעוף שולל רק מחוסר אבר ולא סתם מום (ע\"ד הנ\"ל גבי קרבנות ב\"נ וקרבנות שלפני מ\"ת)<sup data-n=\"259\">27</sup>.\nויש לומר בהסברת הדבר:\nקרבן בהמה הוא קרבן עשיר לגבי קרבן עוף (כדין קרבן עולה ויורד, שדל מביא קרבן עוף). והנה גדר ענין ה­עשירות אינו רק מילוי החסרון (שאצל העשיר לא חסר דבר), אלא היא שלימות נוספת. כמחז\"ל<sup data-n=\"260\">28</sup> גבי מצות צדקה \"די מחסורו<sup data-n=\"261\">29</sup> אתה מצווה עליו לפרנסו, ואי אתה מצווה עליו לעשרו\", זאת אומרת, דאף שחייבים למלא כל חסרונו של העני [עד ד\"אשר יחסר לו\"<sup data-n=\"261\">29</sup> כולל \"אפילו סוס לרכוב עליו ועבד לרוץ לפניו\"<sup data-n=\"260\">28</sup>, אם הוא בן טובים<sup data-n=\"260\">28</sup> הראוי לכך], מ\"מ אין חיוב להעשירו, הרי שעשירות היא שלימות נוספת, יותר ממילוי החסרון.\nולכן, גבי קרבן עוף (קרבן עני) רק מחוסר אבר הוי בגדר חסרון, הסותר לענין התמימות, ואילו פגם קטן \"לא הוי מומא\" והקרבן הוא בכלל \"תמימים יהיו לכם\"; ורק בקרבן בהמה, קרבן עשיר, גם פגם קטן מוציאו מכלל \"תמים\".\nג. ע\"פ נקודה זו, דזה שסתם מום (שאין בו חסרון אבר) לא הוי פסול בקרבנות דקודם מ\"ת (וכן לאחר מ\"ת בקרבן עוף דישראל), אינו לפי שאין בהם דין תמימות, אלא לפי שדרגת השלימות והתמימות הנדרשת בהם אינה נפגמת ע\"י סתם מום —\nיש ליישב (ע\"פ פנימיות הענינים) קושיית התוס'<sup data-n=\"265\">30</sup> על לשון הש\"ס בהא דמכשיר ר' עקיבא<sup data-n=\"266\">31</sup> בעלי מומין ד\"אם<sup data-n=\"267\">32</sup> עלו לא ירדו\", שהוא רק \"בדוקין שבעין הואיל וכשירין בעופות\"<sup data-n=\"268\">33</sup>. וכ' התוס' \"קשה דאיכא כמה מומין דלא פסלי",[["259","27","וי\"ל שהרמב\"ם ס\"ל, שהלימוד מ\"מן העוף\" הוא רק גילוי מילתא, שלא נתמעט עוף לגמרי מדין תמות (ע\"ד מ\"ש בתוד\"ה ת\"ל קידושין שם. תוד\"ה מנין הנ\"ל הערה 5. תוד\"ה ושנסמית שצויין בסמוך).\nולהעיר מפרש\"י בכ\"מ (זבחים — לה, ב ד\"ה וכשירין. סח, ב ד\"ה נסמית. פה, ב ד\"ה הואיל. וכן בחולין כג, א ד\"ה בבהמה), שמחוסר אבר פסול בעוף משום \"הקריבהו נא לפחתך\" (מלאכי א, ח). וכבר הקשו עליו בתוס' (זבחים לה, ב ד\"ה אלא; שם סח, ריש ע\"ב ד\"ה ושנסמית) מש\"ס הנ\"ל דלמד מ\"מן העוף\". ואכ\"מ."],["260","28","כתובות סז, ב."],["261","29","פ' ראה טו, ח."],["261","29","פ' ראה טו, ח."],["260","28","כתובות סז, ב."],["260","28","כתובות סז, ב."],["265","30","זבחים עז, ב ד\"ה הכא."],["266","31","זבחים פד, א — במשנה."],["267","32","רש\"י שם."],["268","33","ל' הש\"ס שם פה, ב. וכן לעיל שם לה, ב. ועוד."]]],[1301670089,"[שאינן מחוסרי אבר] ואמאי נקיט דוקין שבעין, וכן בגיטין<sup data-n=\"239\">7</sup> [בסיפור דקמצא ובר קמצא] הוה מצי למישדי מומא במקום אחר\" (ולא בדוקין שבעין או בניב שפ­תים דוקא<sup data-n=\"270\">34</sup>), ונשארו בקושיא<sup data-n=\"271\">35</sup>.\nוע\"פ הנ\"ל יש לומר, שבדוגמא זו מרמז הש\"ס, שהתוכן הפנימי של השלי­מות הנוספת שנתחדשה ע\"י מ\"ת בענין הקרבנות, שבגללה נשלל \"כל מום\" (בקרבן בהמה דישראל), שייך לענין הראי' דוקא<sup data-n=\"272\">36</sup>.\nד. ויובן זה ע\"פ מ\"ש בחינוך<sup data-n=\"273\">37</sup> ב­שורש טעם המצוה \"שיהי' כל קרבן תמים\", \"עם מה שהקדמנו. . בענין הקר­בנות על צד הפשט שהם לעורר ולכוין מחשבת בני איש אל הקדוש ברוך הוא, כי האדם מתפעל בכח מעשיו, על כן ראוי על כל פנים להיות הקרבן בלי מום, כי מחשבות בני אדם לא ינוחו ולא יתפשטו במין הפחות כמו בחשוב, כי הלבבות יתעוררו בחשוב ובשלם במינו יותר\".\nויש לבאר זה בעומק יותר ע\"פ דברי הבחיי<sup data-n=\"274\">38</sup> בפירוש לשון קרבן, שהוא מ­לשון קירוב, וענין הקרבנות \"הוא קירוב הכחות והמדות\" להקב\"ה. ועפ\"ז יש לומר, דזה שקרבן צ\"ל \"תמים\" בלי מום, הרי זה לפי שזה צריך \"לעורר ולכוין מחשבת בני איש\" לקרב את כל הכחות והחושים שלו \"אל הקדוש ברוך הוא\".\nוזהו שאצל ב\"נ \"דוקין שבעין\" אינם בגדר מום, כי אצל ב\"נ לא נדרש ענין הראי' באלקות.\nביאור הענין:\nאע\"פ שגם אצל ב\"נ ישנו ענין ה­אמונה בבורא עולם, דקרו לי' אלקא דאלקייא<sup data-n=\"275\">39</sup>, מ\"מ, יש חילוק עיקרי בין האמונה דב\"נ והאמונה דבנ\"י, ועד של­כמה דיעות<sup data-n=\"276\">40</sup> לא הוזהרו ב\"נ על ה­שיתוף.\nונקודת החילוק היא: אצל ישראל, ענין האמונה הוא תוצאה מזה שיש בהם \"חלק אלקה ממעל ממש\"<sup data-n=\"277\">41</sup>, ש\"ה' אחד מאיר\"<sup data-n=\"278\">42</sup> בנפשו<sup data-n=\"279\">43</sup>, וכיון שאין יסוד הא­מונה במציאותו של המאמין (שכלו והב­נתו), אלא זה ש\"ה' אחד מאיר\" ומתגלה בנפשו, הרי מובן, שבו מתגלה אמיתית אחדותו של הקב\"ה, \"ה' אחד\" ו\"אין עוד מלבדו\"<sup data-n=\"280\">44</sup>; משא\"כ אצל ב\"נ, שאין אצלם נשמה קדושה, הרי כל אמונתם באלקים היא תוצאה מתפיסתם והשגתם באלקות, וכיון שהיא מיוסדת על מציאותם, לכן אין אמונה זו שוללת (בהכרח) מציאות אחרת (או אפילו שליטה אחרת) מלבד הקב\"ה. ומהאי טעמא לא הוזהרו על השיתוף, כי האמונה הנדרשת מהם (לפי יכולתם, שאין בהם \"חלק אלקה ממעל",[["239","7","גיטין נו, א."],["270","34","וראה חדא\"ג מהרש\"א גיטין שם ע\"ד המוסר."],["271","35","ולעיל שם (לה, סע\"ב ד\"ה אלא) תי' ד­\"שאר מומין פסלי מדרבנן\". ואכ\"מ."],["272","36","בהבא לקמן ראה תו\"א תשא בהוספות (קיא, ד). מאמרי אדמו\"ר האמצעי תשא (ע' תרלד ואילך). אוה\"ת תשא (ע' א'תתמד­ה. ועוד). סהמ\"צ להצ\"צ מצות מחצית השקל (סה, סע\"ב ואילך)."],["273","37","מצוה רפו."],["274","38","ויקרא א, ט. — והוא מס' הבהיר סי' קט (מג)."],["275","39","מנחות קי, א."],["276","40","ראה הנסמן בסה\"מ מלוקט ח\"א ע' נב. אנציקלופדי' תלמודית ערך ב\"נ (ע' שנ). ועוד. וראה סהמ\"צ להצ\"צ מצות אחדות ה'. ועוד."],["277","41","ל' התניא רפ\"ב."],["278","42","ל' התניא ספי\"ח."],["279","43","בחכמה שבנפש (תניא שם). וראה תניא פל\"ה בהגהה דמדריגת החכמה היא \"אחד האמת שהוא לבדו הוא ואין זולתו\". וראה הערה 45."],["280","44","ואתחנן ד, לה."]]],[1301670090,"ממש\") היא רק שהקב\"ה \"הוא אלקא דאלקייא\".\nה. והנה החילוק בין שני אופנים אלה, הוא כמו וע\"ד החילוק בין ב' החושים דשמיעה וראי': גדר ראי' הוא שהדבר הנראה מתגלה ומאיר כמו שהוא אל האדם הרואה, היינו שאין תפיסת הדבר הנראה לפי גדרי הרואה, אלא שהדבר הנראה מאיר אליו; משא\"כ שמיעה היא מרחוק, דכאשר האדם שומע אודות דבר מסויים, הרי תפיסתו בהדבר היא ע\"י ששומע פרט אחר פרט, ועי\"ז מצטייר בשכלו הדבר, ומובן, שאין זה גילוי הדבר כמו שהוא, אלא לפי תפיסת שכלו והבנתו.\nוכן הוא בענין האמונה, דאצל ב\"נ, שאין \"ה' אחד\" מאיר ומתגלה אצלם, אלא שביכולתם להגיע לאמונה בה' ע\"י הוכחות שכליות וכו', הרי זה גדר של \"שמיעה\", ואילו אצל ישראל, ש\"ה' אחד מאיר\" בנפשם, הרי ענין האמונה אצלם הוא בגדר \"ראי'\"<sup data-n=\"281\">45</sup>.\nוזהו גם הרמז בלשון הש\"ס, שהדוג­מא למום שאינו פוסל בקרבנות קודם מ\"ת (וקרבנות ב\"נ אחר מ\"ת בבמה ש­להם) היא ממום \"בדוקין שבעין\", כי ענין הראי' באלקות נפעל בישראל (בעיקר) בשעת מתן תורה, כמ\"ש<sup data-n=\"280\">44</sup> \"אתה הראת לדעת כי ה' הוא האלקים אין עוד מ­לבדו\", \"הראת ממש, בראי' חושיית\"<sup data-n=\"283\">46</sup>, ולכן, כאשר בנ\"י מקריבים קרבן להשם, נדרש אצלם שעבודת ההקרבה תהי' בכל הכחות והחושים, גם חוש הראי', ראי' באלקות. משא\"כ בב\"נ שאין אצלם הראי' באלקות, הרי \"דוקין שבעין. . לאו מומא הוא\"<sup data-n=\"284\">47</sup>.\n[ועד\"ז בבנ\"י עצמם, דמי שהוא בתחי­לת העבודה, במצב של \"עני\" — אין עני אלא בדעת<sup data-n=\"285\">48</sup> — וחסר אצלו הדעת ב­אלקות באופן של \"הראת לדעת\", באופן של ראי' — אין דוקין שבעין (בעוף) נחשב אצלו כמום.\nולאידך גיסא, כיון שהגילוי דמ\"ת פעל גם על ב\"נ, עד שקיום ז' מצות ב\"נ צ\"ל \"מפני שצוה בהן הקב\"ה בתורה. . על ידי משה רבינו\"<sup data-n=\"286\">49</sup>, לכן גם אצלם שייך עכ\"פ מעין ענין אמונה זו, וזהו שב\"נ יכול להביא קרבנות ע\"ג מזבח שבבהמ\"ק (דישראל)<sup data-n=\"287\">50</sup>, ואזי קרבנו צ\"ל תמים ממש<sup data-n=\"288\">51</sup>].\nו. והנה כשם שהוא לענין גילוי אחדות ה' במ\"ת, שעי\"ז נשלל ענין ה­שיתוף (אף שבמצב דקודם מ\"ת (וכן בב\"נ אחר מ\"ת), גם האמונה באופן ד\"אלקא דאלקייא\" אין בה פגם) — עד\"ז הוא אחר מ\"ת, שבענין אחדות ה' גופא",[["281","45","והרי ראי' היא בחכמה (ראה לעיל הערה 43)."],["280","44","ואתחנן ד, לה."],["283","46","תניא פל\"ו."],["284","47","להעיר, שאע\"פ שבגיטין שם הובא (לענין ב\"נ) גם האופן דמום \"בניב שפתים\" (ורק בקרבן עוף דישראל הדוגמא בש\"ס בכ\"מ היא רק \"בדוקין שבעין\") — מ\"מ, בדרושים הנ\"ל (הערה 36) נתבאר החילוק בין ישראל וב\"נ רק בענין הדוגמא ד\"דוקין שבעין\", ענין הראי' באלקות.\nולכאורה י\"ל, דהא דבישראל מביא רק הדוגמא ד\"דוקין שבעין\" כי בישראל, גם במצב של \"עני\" בדעת, אפ\"ל רק חסרון בראי' באלקות ולא יתירה מזה, משא\"כ בב\"נ יתכן מצב שיהי' חסר (בתוכן הפנימי) ב\"ניב שפתים\" ומ\"מ לא נחשב מום. ועצ\"ע."],["285","48","נדרים מא, רע\"א."],["286","49","רמב\"ם הל' מלכים ספ\"ח."],["287","50","חולין יג, ב. וש\"נ. תו\"כ אמור כב, יח. פרש\"י אמור שם, כה."],["288","51","תמורה ז, א. רמב\"ם הל' איסורי מזבח פ\"א ה\"ו. פרש\"י אמור כב, יט."]]],[1301670091,"נתגלה בפנימיות התורה אופן עמוק יותר באחדותו ית' (מיוסד על ביאור הזהר<sup data-n=\"289\">52</sup> בענין \"ה' הוא האלקים\"), עד שלא רק שאין לשום דבר איזו שליטה שהיא מלבדו ית', אלא עוד זאת, שאין שום מציאות מלבדו<sup data-n=\"290\">53</sup> (וזהו הפירוש ב\"אין עוד מלבדו\", שאין שום מציאות בלעדו ית'), עד ש\"אין עוד\"<sup data-n=\"291\">54</sup> [ובזה גופא, במשך הדורות, מתגלים מזמן לזמן בפנימיות התורה אופנים עמוקים יותר, בהבנת ענין אחדות ה' בדקות יותר].\nואע\"פ שקודם שנתגלתה הבנה זו באחדות ה' לא שייך לומר שהעדר הידיעה בזה הוא ענין של חסרון ופגם ח\"ו וח\"ו, מ\"מ, לאחרי שכבר נתגלו בעולם ביאורים אלה בפירוש האמיתי דאחדות השם, הרי מי שאינו לומד ומאמין בהם ה\"ז פגם באמונתו בהשם, וה\"ז בדקות דדקות ענין של כפירה<sup data-n=\"292\">*54</sup> באחדות השם.\nוע\"ד שמצינו ברמב\"ם שפסק ל­הלכה<sup data-n=\"293\">55</sup> ד\"האומר שיש שם רבון אחד אבל שהוא גוף ובעל תמונה\" ה\"ה מין, והראב\"ד השיג \"ולמה קרא לזה מין וכמה גדולים וטובים ממנו הלכו בזו המחשבה לפי מה שראו במקראות ויותר ממה שראו בדברי האגדות המשבשות את הדעות\". והסברת שיטת הרמב\"ם, דאע\"פ שהיו \"גדולים וטובים\" שסברו שהקב\"ה הוא \"גוף ובעל תמונה\" וח\"ו לקרותם בשם \"מין\", מ\"מ, לאחרי שנתגלו ונתפרסמו הביאורים וכו' בספרי גדולי ישראל, שאי אפשר לומר כן ושזהו בסתירה לאחדות השם (כמו שביאר הרמב\"ם בהלכות יסודי התורה<sup data-n=\"294\">56</sup>), א\"כ מעתה הסובר כן מפני משמעות פשוטי המקראות או ממה שראה בדברי אגדות, הרי הוא בגדר \"מין\".\nועד\"ז כן הוא בעניננו, דלאחרי שנת­גלה בפנימיות התורה הפירוש האמיתי באחדות השם, אשר אין שום מציאות בלעדו ית', הרי מי שאינו מאמין בזה ה\"ז בדקות דדקות ענין של כפירה באחדותו ית'. וכנ\"ל — שאין להביא שום ראי' מזה שבדורות שלפני גילוי פנימיות התורה לא הי' ידוע פירוש זה באחדות השם, וא\"כ הרי אפשר שאמונה בהשם יכולה להיות בשלימות גם בלי ידיעה זו ב­אחדות השם, כי לפני התגלות זו בעולם אין בהעדר ידיעה זו שום פגם ח\"ו<sup data-n=\"295\">57</sup>; אבל לאידך, כאשר \"הכל עשה יפה בעתו\"<sup data-n=\"296\">58</sup> ונתגלתה פנימיות התורה, כולל גם האופנים העמוקים שבהבנת אחדותו ית', ההולכים ומתגלים מדור לדור, הרי זה חוב על כאו\"א מישראל ללמוד ענינים אלו ולהאמין בהם<sup data-n=\"297\">59</sup>.",[["289","52","וארא כה, א. הובא ונת' בסהמ\"צ להצ\"צ מצות אחדות ה'. ועוד."],["290","53","ראה תניא ח\"ב פ\"ו (פ, ב). סהמ\"צ להצ\"צ שם פ\"ג. ובכ\"מ. — וראה גם של\"ה בתחלתו בית הבחירה (כח, סע\"ב). ועוד."],["291","54","ואתחנן שם, לט. וראה תניא שם (בסוף העמוד). ובמ\"א נת' החידוש ב\"אין עוד\" על \"אין עוד מלבדו\". ואכ\"מ."],["292","*54","ראה בזה (ובפלוגתת הרמב\"ם והראב\"ד) פרדס שער א' פ\"ט. נת' במאמרי אדה\"ז — ענינים (ע' שלה ואילך), תק\"ע (ע' נג­ד). וראה לקו\"ש ח\"י ס\"ע 265 ואילך."],["293","55","הל' תשובה פ\"ג ה\"ז."],["294","56","פ\"א ה\"ז ואילך."],["295","57","וע\"ד קודם שנקבעה הלכה, הרי באתרי' דר' יוסי הגלילי אכלו בשר עוף בחלב (חולין קטז, א), ועד\"ז בכו\"כ ענינים."],["296","58","קהלת ג, יא ובקה\"ר שם (לענין נתינת התורה). וראה בארוכה לקו\"ש ח\"ז (ע' 206 ואילך), לענין גילוי פנימיות התורה בדורות האחרונים דוקא."],["297","59","ראה גם לקו\"ש חכ\"ה ע' 17 לענין כללות החיוב דלימוד פנימיות התורה בדורות אלו."]]],[1301670092,"והלימוד בענינים אלו ה\"ז הכנה קרובה ל\"אותו<sup data-n=\"298\">60</sup> הזמן\" ש\"יהיו<sup data-n=\"298\">60</sup> ישראל חכמים גדולים ויודעים דברים הסתומים וישיגו דעת בוראם כפי כח האדם שנאמר<sup data-n=\"300\">61</sup> כי מלאה הארץ דעה את ה' כמים לים מכסים\".\n<span data-k=\"q\">(משיחות יו\"ד שבט תשי\"ג, י\"ט כסלו תשי\"ב)</span>",[["298","60","ל' הרמב\"ם בסיום וחותם ספרו."],["298","60","ל' הרמב\"ם בסיום וחותם ספרו."],["300","61","ישעי' יא, ט."]]],[1301670093,"<h3>שיחה ג</h3>\nא. \"ויאמר אלקים זאת אות הברית גו' לדורות עולם\"<sup data-n=\"301\">1</sup>, ואיתא במדרש רבה<sup data-n=\"302\">2</sup>: \"לדרת כתיב, פרט לשני דורות [שבהם לא נראה אות הקשת בעולם], לדורו של חזקי' ולדורו של אנשי כנסת הגדולה, רבי חזקי' מוציא דורן של אנשי כנסת הגדולה ומביא דורו של ר\"ש<sup data-n=\"303\">3</sup> בן יוחאי\".\nובפרש\"י עה\"פ הובאה דרשה זו, וז\"ל: \"לדרת עולם — נכתב חסר, שיש דורות שלא הוצרכו לאות לפי שצדיקים גמורים היו כמו דורו של חזקיהו מלך יהודה ודורו של רבי שמעון בן יוחאי\".\nוכבר עמדו במפרשים<sup data-n=\"304\">4</sup> על כך, דב­מדרש נתמעטו רק שני דורות אלו, \"פרט לשני דורות\", שרק בהם לא הי' צורך באות הקשת [וכמובן גם מזה ש\"ר' חזקי' מוציא דורן של אנשי כנסת הגדולה ומביא דורו של רשב\"י\"<sup data-n=\"305\">5</sup>, שבפשטות, הטעם שהוזקק ר' חזקי' להוציא דורן של אנשי כנסת הגדולה (ולא רק להוסיף גם דורו של רשב\"י), הוא לפי שאז הם יותר מב' דורות<sup data-n=\"306\">6</sup>]; משא\"כ רש\"י כותב \"שיש דורות שלא הוצרכו כו'\" (ולא כתב \"ב' דורות\"), לפי שע\"פ פש\"מ — דרך רש\"י — אין מוכרח כמה דורות לא הוצרכו לאות<sup data-n=\"307\">7</sup> [ומ\"ש רש\"י אח\"כ \"דורו של חזקיהו כו' רשב\"י\" (שמביא רק ב' דורות) — לדוגמא נקט, אבל אפ\"ל מצד פש\"מ שהיו יותר, וכדיוק לשונו<sup data-n=\"308\">8</sup> \"כמו<sup data-n=\"309\">9</sup> דורו של חזקיהו כו' רשב\"י\"].\nוביארו, ששינוי זה תלוי באופן הלי­מוד מ\"לדרת\": המדרש דריש החסרון של ב' הווי\"ן<sup data-n=\"310\">10</sup>, ולכן כ' \"פרט לשני דורות\", ואילו לפרש\"י נלמד זה ממה ש\"נכתב חסר\", היינו שכללות החסרון שבהתיבה באה ללמדנו<sup data-n=\"311\">11</sup> שיש \"חסרון\" ב\"לדורות עולם\"<sup data-n=\"312\">12</sup>, שאין כל הדורות בכלל, כי נחסרו כמה דורות שלא הוצרכו לאות הקשת.\nולכאורה מסתבר לומר, שנוסף על",[["301","1","פרשתנו ט, יב."],["302","2","על אתר (פל\"ה, ב)."],["303","3","ראה גם ירושלמי ברכות פ\"ט ה\"ב (וכן משמע בכתובות עז, ב). מדרש תהלים מזמור לו בסופו (בהוצאת באבער. משא\"כ בשוחר טוב לפנינו \"כל ימיו של [ר' יהושע] בן לוי\" — כבכתובות שם). זח\"ג טו, א. לו, א (ולהעיר מניצוצי אורות לזח\"א רכה, א)."],["304","4","יפה תואר לב\"ר שם. משכיל לדוד על פרש\"י כאן."],["305","5","וצ\"ע בנזר הקודש (השלם) לב\"ר שם, שפי' שהמדרש נקט ב' דורות אלה רק לדוגמא (וכ­פרש\"י)."],["306","6","ומתורץ המשך המדרש שם, שבדורו של ריב\"ל נראתה הקשת — דלא כמסקנת הש\"ס (כתובות שם) — כי אז הם יותר מב' דורות."],["307","7","ובפענח רזא כאן, ד\"ששה היו, לכן חסרה ו'\"."],["308","8","וכן דייק בנחלת יעקב על פרש\"י כאן."],["309","9","ברוב כת\"י רש\"י שתח\"י ליתא תיבת \"כמו\" [ובדפוס ראשון — \"היו\" במקום \"כמו\", ולכאורה הוא טה\"ד]. אבל ישנה בדפוסי רש\"י הנפוצים (ובדפוס ב' דפרש\"י \"כגון\")."],["310","10","ראה גם מת\"כ לב\"ר שם."],["311","11","אף שרש\"י לא נחית (בפי' עה\"ת) לבאר כל החסרות שבמקרא, כמשנ\"ת כמ\"פ — הרי בנדו\"ד כל תיבת \"לדורות\" מיותרת (באר בשדה על פרש\"י כאן)."],["312","12","ראה נחלת יעקב ועוד על פרש\"י. — וראה רא\"ם ועוד באו\"א. וכבר שקו\"ט במפרשים. ואכ\"מ."]]],[1301670094,"פלוגתתם באופן מדרש הפסוקים — אם מ\"לדרת\" נתמעטו רק ב' דורות, או מספר סתמי של דורות (\"יש דורות\") — יש חילוק בין ב' אופנים אלה גם בתוכן הענין, וכדלקמן.\nב. ויש לומר, שהמדרש ופרש\"י מחולקים בטעם הדבר שדורות אלו לא הוצרכו לאות, שיש לבארו בב' אופנים: א) שזהו מצד זכות הצדיקים שבדור, המגינה על העולם. ב) מצד מצב כל אנשי הדור, שמצד צדקתם כו' אינם זקוקים לאות הקשת, שמלכתחילה אינם ראויים לעונש.\nברש\"י מפורש \"שיש דורות שלא הוצרכו לאות לפי שצדיקים גמורים היו\", שתיבת \"היו\" מוסבת על תיבת \"דורות\" שלפני', שהדורות עצמם היו צדיקים גמורים. ומזה מובן, שהדוגמאות שמביא רש\"י אח\"כ, \"כמו דורו של חזקיהו מלך יהודה ודורו של רבי שמ­עון בן יוחאי\", אין כוונתו בזה להדגיש גודל צדקתם של שני צדיקים אלה<sup data-n=\"313\">13</sup>, אלא שאנשי דורו של חזקיהו ואנשי דורו של רשב\"י היו צדיקים גמורים. וכדמצינו בפירוש בחז\"ל<sup data-n=\"314\">14</sup> לגבי דורו של חזקיהו, שבימיו \"בדקו מדן ועד באר שבע ולא מצאו עם הארץ כו' ולא מצאו תינוק ותינוקת איש ואשה שלא היו בקיאין בהלכות טומאה וטהרה ועל אותו הדור הוא אומר כו'\" — וזוהי הסיבה שלא הוצרכו לאות.\n[ואף שזה בא על ידי חזקיהו המלך (כמסופר בחז\"ל שם<sup data-n=\"315\">15</sup>), מ\"מ, מה שנוגע כאן (בטעם שלא היו צריכים לאות) אינו גודל זכותו דחזקי' בזה, אלא זה שב­פועל היו אנשי דורו צדיקים גמורים].\nאבל המדרש ס\"ל שהטעם שנתמעטו ב' דורות אלו מאות הקשת הוא מצד גודל צדקתם של חזקיהו ושל (אנשי כנסת הגדולה, או) רשב\"י עצמם. וכמובן גם מהמשך דברי המדרש<sup data-n=\"316\">16</sup>, שמסופר שם אודות דברי רשב\"י לאליהו הנביא בנו­גע לר' יהושע בן לוי<sup data-n=\"317\">17</sup>, דכיון שנראתה הקשת בימיו אין הוא כדאי לראות פניו, שמזה מובן, שהמעלה של אי ראיית קשת שבימי רשב\"י מתייחסת לרשב\"י עצמו (ולא לאנשי דורו), שמצד גודל צדקתו של רשב\"י לא נראתה קשת בימיו. וכן מובן ממה שהמדרש ממשיך ומבאר עוד כמה מעלות ושבחים של רשב\"י, כי שבחים אלה מוסיפים ביאור בטעם שלא נראתה קשת בימיו<sup data-n=\"318\">18</sup>.\n[ומדוייק גם כן שאחת ממעלותיו של רשב\"י שהובאה במדרש שם היא — דברי רשב\"י שזכותו גדלה כ\"כ עד שיכול לסבול<sup data-n=\"319\">19</sup> את כל הדורות \"עד מלכא משיחא\" (וכלשון רשב\"י שהובא בגמ'<sup data-n=\"320\">20</sup> \"יכול אני לפטור את כל העולם כולו מן הדין\") — שזהו בהתאם לכך שבדורו לא נראתה קשת, דאף אם היו",[["313","13","ע\"ד פרש\"י בש\"ס (כתובות שם) \"ואם יש צדיק גמור בדור אין צריך אות\". אבל ראה הנסמן בהערה 15."],["314","14","סנהדרין צד, ב (הובא גם ביפ\"ת לב\"ר שם. וראה לקמן הערה 22)."],["315","15","וראה לקו\"ש ח\"ד (ע' 1230. ע' 1235 ואילך) בנוגע לריב\"ל, שהוא פעל זיכוך בהדור. וראה לקו\"ש חי\"ז ע' 363 הערה 77."],["316","16","וכן בירושלמי ברכות שם."],["317","17","ראה גם כתובות שם. מדרש תהלים שם. פסיקתא דר\"כ פ' ויהי בשלח. ועוד."],["318","18","ראה נזר הקודש (השלם) לב\"ר שם. — ודלא כמ\"ש ביפה תואר (השלם) לב\"ר שם, ששבחים אלה הובאו שם רק דרך אגב (ולשיטתו אזיל, שבמדרש נוגע בעיקר מצב הדור — ראה הערה 22)."],["319","19","ביחד עם אברהם אבינו או אחי' השילוני (ב\"ר שם. וראה סוכה מה, ב)."],["320","20","סוכה שם."]]],[1301670095,"ראויים לעונש, הרי זכותו של רשב\"י מגינה עליהם ופוטרת אותם מן הדין, ובמילא אינם צריכים לאות הקשת<sup data-n=\"321\">21</sup>].\nג. ועפ\"ז יש לומר, שזהו גם תוכן החילוק בין שיטת המדרש ושיטת פרש\"י עה\"ת אם נתמעטו רק ב' דורות, או יותר מזה:\nלהמדרש שנתמעטו רק ב' דורות, ה\"ז לשיטתו שהמיעוט מאות הקשת בא מצד גודל צדקת הצדיק שבדור, שביכולתו להגן על כל העולם כולו, שצדיק בדרגא כזו לא נמצא בדרך כלל<sup data-n=\"322\">22</sup>, וכמובן מזה גופא שרק רשב\"י אמר על עצמו \"יכול אני לפטור את כל העולם כולו מן הדין\", היינו שזהו דבר חידוש אפילו לגבי תנאים וצדיקים אחרים.\nועד\"ז היא כוונת המדרש בנוגע ל­חזקי', שגם אצלו מצינו הפלאה מיוחדת, כמאמר חז\"ל<sup data-n=\"323\">23</sup> שביקש הקב\"ה לעשות חזקיהו משיח, וכיון שהי' ראוי להיות גואלם של ישראל מובן שגדלה זכותו להגן על כל העולם כולו.\nמשא\"כ לשיטת רש\"י, שהכוונה ש­כללות הדור היו צדיקים גמורים (כי לא היו חייבים עונש מבול, כדלקמן), הרי אין זה דבר מיוחד רק לדורו של חזקיהו ודורו של רשב\"י, שהרי היו עוד דורות כאלו (ע\"ד שהובא גם בחז\"ל עה\"פ<sup data-n=\"324\">24</sup> \"שקר החן גו' אשה יראת ה' היא תתהלל\" בנוגע לדורו של ר' יהודה ב\"ר אילעאי, ועוד).\nד. ויש לבאר יסוד הפלוגתא בין המדרש ופרש\"י (אם זה שדורות אלו לא הוצרכו לאות הוא מחמת זכות הצדיק או מפני מעלת אנשי הדור) — שזה תלוי בגדר הצורך באות הקשת.\nובהקדם תמי' עצומה לכאורה במ­חז\"ל זה, שרק בדורות אחדים לא הוצרכו לאות הקשת: \"אות\" הקשת היא, כמפורש בכתוב, להזכיר את הברית ש\"לא יהי' עוד המים למבול לשחת כל בשר\"<sup data-n=\"325\">25</sup>, ובפשטות, הצורך בהאות הוא רק כאשר יש מקום לעונש של מבול (מצד רוע ההנהגה כו')<sup data-n=\"326\">26</sup>, אלא שאעפ\"כ לא יהי' מבול — מפני הבטחתו של הקב\"ה.\nותמוה: כיצד אפשר לומר שרק כאשר יש \"צדיקים גמורים\" (כלשון רש\"י) אז אין צריכים לאות הקשת? הרי גם אם אינם צדיקים גמורים, ואפילו אם הם רשעים, הרי כל זמן שאינם במצב של אנשי דור המבול — שהעולם הי' אז בשפל המצב ביותר, \"רבה רעת האדם",[["321","21","וי\"ל שזהו טעמו של ר' חזקי' (בב\"ר שם) שהוציא דורם של אנשי כנה\"ג ומביא דורו של רשב\"י, כי עיקר מעלת אנשי כנה\"ג היא ש\"המה הרבו תורה בישראל\" (יפ\"ת שם), משא\"כ אצל רשב\"י מפורשת מעלתו שגדלה זכותו להגן על כל העולם כולו."],["322","22","ומתורצת קושיית היפ\"ת (השלם) שם \"שכמה דורות כשרים הוו\" (וראה גם מלאכת הקודש על פרש\"י כאן. ושם, שתי' היפ\"ת ד\"כך היתה מסורת בידו כו' אפשר אלו היו צדיקים טפי מן השאר\" — \"אין זה מספיק\". ע\"ש) — כי זהו רק לפירושו שלא היו צריכים לאות הקשת מצד מצב הדור (שהיתה הרבה תורה בישראל כו'): משא\"כ ע\"פ המבואר בפנים שתלוי בזכותו של צדיק אחד שיכול להגן על כל העולם כולו — שזה הי' רק בב' דורות."],["323","23","סנהדרין שם, א."],["324","24","משלי לא, ל. סנהדרין כ, א (הובא במלאכת הקודש על פרש\"י כאן)."],["325","25","פרשתנו ט, טו (וכן שם, יא)."],["326","26","ראה רש\"י ט, יד. טז. וראה בחיי כאן, שהאות הזה נראה רק \"בזמן שהדור מחוייב\" (ושם, שנלמד מלדרת חסר, \"שאין אות הקשת אלא בזמן החיוב ודורות החסרים\")."]]],[1301670096,"בארץ גו'\"<sup data-n=\"327\">27</sup>, ועד ש\"ותשחת הארץ. . השחית כל בשר את דרכו על הארץ\"<sup data-n=\"328\">28</sup> — אין מקום לעונש של מבול [כפי ש­רואים, שקודם המבול, אף שכל הדורות שלפנ\"ז \"היו מכעיסין ובאין\"<sup data-n=\"329\">29</sup>, וכבר בדורו של אנוש (בנו של שת) עבדו עבודה זרה<sup data-n=\"330\">30</sup>, בכ\"ז לא הי' עונש כזה של איבוד העולם כולו<sup data-n=\"331\">31</sup>] — וא\"כ, איך אפשר לומר, שרק בדורות ש\"צדיקים גמורים היו\" לא היו צריכים לאות הקשת?\nה. והנה ע\"ד הדרש יש לתרץ, שאין הפירוש שבכל פעם שרואים קשת ה\"ז סימן שהעולם הוא במצב שראוי לעונש של מבול והעולם ניצל רק בזכות הבטחת הקב\"ה (הנזכרת על ידי אות הקשת) — אלא שהקב\"ה קבע את אות הקשת בטבע הבריאה<sup data-n=\"332\">32</sup> באופן תמידי, לזכרון עולם, שגם אם יהי' העולם במצב שפל כזה שיהי' ראוי לעונש של מבול, מובטחים אנו (בשבועה<sup data-n=\"333\">33</sup> \"לא אוסיף\" \"ולא אוסיף\") ש\"לא<sup data-n=\"334\">34</sup> יהי' עוד מבול לשחת הארץ\". ולכן נראית הקשת גם בדורות שאין ראויים לעונש של מבול.\nוזהו גם היסוד לדעת המדרש, שדו­רות שלא נראתה בהם הקשת<sup data-n=\"335\">35</sup>, הי' זה מחמת זכות הצדיקים של הדור (זכותו של חזקיהו המלך וזכותו של רשב\"י) — ולא מפני גודל הצדקות של אנשי הדור:\nהסיבה להעדר ראיית קשת בדורות אלו אינה מפני שרק דורות אלו לא היו במצב שאין ראויים לעונש של מבול — דודאי אינו כן, ואדרבה, רובם ככולם של הדורות אינם ראויים לעונש של מבול ח\"ו; אלא זה שלא נראתה הקשת בימיהם בא להורות על גודל זכותו של הצדיק הנמצא בדור ההוא<sup data-n=\"336\">36</sup>, שגם אילו יצוייר שדורו הי' בשפל המצב כמצב דור המבול, וגם לא היתה הבטחה ש\"לא יהי' עוד מבול\", מ\"מ בזכותו לא היו נענשים (כמאמר רשב\"י הנ\"ל \"יכול אני לפטור את כל העולם כולו מן הדין\").\nאבל בפרש\"י על התורה אי אפשר לבאר כן, כי עה\"פ<sup data-n=\"337\">37</sup> \"והי' בענני ענן על הארץ ונראתה הקשת בענן\", מפרש \"בענני ענן — כשתעלה במחשבה לפני להביא חשך ואבדון לעולם\"<sup data-n=\"338\">38</sup>. שמזה מובן, שע\"פ פשוטו של מקרא, זה ש\"נראתה הקשת בענן\"<sup data-n=\"335\">35</sup> הוא תוצאה מזה שעלה במחשבה \"להביא חשך ואבדון לעולם\".\n[דבשלמא במ\"ש אח\"כ<sup data-n=\"340\">39</sup> \"והיתה ה­",[["327","27","בראשית ו, ה."],["328","28","ריש פרשתנו (ו, יא­יב). וראה רש\"י שם."],["329","29","ל' המשנה — אבות פ\"ה מ\"ב."],["330","30","רש\"י בראשית ד, כו."],["331","31","להעיר מרש\"י בראשית (ו, ד) \"אבדן של דור אנוש שעלה אוקיינוס והציף שליש העולם כו'\". — וראה לקמן הערה 57."],["332","32","וידועה השקו\"ט במפרשי התורה (ועוד) איך אפ\"ל שקשת היא \"אות\" — והרי לכאורה הו\"ע ב­טבע הבריאה (מששת ימי בראשית). — ובכל אופן, לאחרי המבול, בודאי ה\"ז ענין בטבע הבריאה. ואכ\"מ."],["333","33","פרשתנו ח, כא ובפרש\"י."],["334","34","שם ט, יא."],["335","35","בכלי יקר כאן (ט, יד) מפרש הלשון שלא נראתה הקשת בימיהם — \"שהבריות לא היו חוקרין אחריו ולא השתדלו לראותו\" (וכן מ\"ש \"ונראתה הקשת בענן\" היינו שיסתכלו בו כו'). ע\"ש באורך. אבל מפשטות הלשון משמע, שבדורות אלה (נעשה נס ו)לא היתה נראית כלל."],["336","36","ראה באר בשדה על פרש\"י כאן \"שלא נצרכו לאות שהם (הצדיקים) עצמן אות לעולם דומיא דשבת כו'\"."],["337","37","ט, יד."],["338","38","וכבר האריכו במפרשי רש\"י בביאור הטעם שרש\"י מוציא התיבות \"בענני ענן\" מפשוטן. ואכ\"מ."],["335","35","בכלי יקר כאן (ט, יד) מפרש הלשון שלא נראתה הקשת בימיהם — \"שהבריות לא היו חוקרין אחריו ולא השתדלו לראותו\" (וכן מ\"ש \"ונראתה הקשת בענן\" היינו שיסתכלו בו כו'). ע\"ש באורך. אבל מפשטות הלשון משמע, שבדורות אלה (נעשה נס ו)לא היתה נראית כלל."],["340","39","שם, טז."]]],[1301670097,"קשת בענן וראיתי' לזכור ברית עולם\", אפשר לפרש, שהקשת בענן הוא ענין תמידי, אלא דכאשר יעלה במחשבה לפניו להביא חשך ואבדון לעולם, אזי תועיל ראיית הקשת (\"וראיתי'\"), שיזכור הקב\"ה כביכול<sup data-n=\"341\">40</sup> את הברית עולם. משא\"כ בפסוק \"והי' בענני ענן גו'\", שנאמר \"ונראתה הקשת בענן\" (ולא \"וראיתי' גו'\")].\nוהדרא קושיא לדוכתא — כיצד יתכן לומר, שבמשך כל הדורות (מלבד ה­דורות המועטים שלא נראתה הקשת בימיהם) הי' העולם במצב כזה שיש מחשבה לפניו ית' \"להביא חושך ואבדון לעולם\" (כמו דור המבול)?!\nו. ונראה לומר בזה — שע\"פ פשוטו של מקרא, הגדר של עונש המבול שנש­לל ע\"י הבטחת הקב\"ה, אינו רק שלילת הבאת מבול על כל הארץ כולה, אלא אפילו על חלק מן הארץ<sup data-n=\"342\">41</sup> [והפירוש ב\"ולא יכרת כל בשר\"<sup data-n=\"334\">34</sup>, \"ולא יהי' עוד המים למבול לשחת כל בשר\"<sup data-n=\"344\">42</sup> — אין פירושו כל בשר ביחד<sup data-n=\"345\">43</sup> (\"כל\" במובן של כלל הדברים), אלא \"כל בשר\" היינו אף אחד מה\"בשר\"<sup data-n=\"346\">*43</sup> (\"כל\" במובן \"שום\", כמו \"לא תעשה כל מלאכה\"<sup data-n=\"347\">44</sup>, \"וכל אדם לא יהי' באוהל מועד\"<sup data-n=\"348\">45</sup>, ועוד)].\nדהנה<sup data-n=\"e1\">*</sup> שונה עונש המבול משאר ה­עונשים המסופרים בתורה, שאצל המבול נאמר<sup data-n=\"349\">46</sup> \"וימח את כל היקום אשר על פני האדמה\", שזה מורה על ענין של איבוד מוחלט, וסיבת הדבר מפורשת בכתוב, כי המבול לא בא רק לענוש את אנשי דור המבול, אלא מפני ש\"וינחם<sup data-n=\"350\">47</sup> ה' כי עשה את האדם גו' ויאמר ה' אמחה את האדם גו' כי נחמתי כי עשיתים\", כלומר, שהקב\"ה התחרט כביכול על עצם ברי­את האדם (ושאר הנבראים), ולכן בא למחות ולאבד את הבריאה אשר עשה.\nדעונש זה הוא עונש מסוג מיוחד. דישנם עונשים חמורים, עד עונשים באופן של כליון, וגם באופן שנאבד לא רק מין המדבר אלא גם הבעלי חיים (כמו עונש עיר הנדחת<sup data-n=\"351\">48</sup>), ועד שהארץ עצמה נשחתה, ע\"ד הפיכת סדום ועמו­רה<sup data-n=\"352\">49</sup>. אבל מ\"מ כ\"ז הוא רק דרך עונש, שאנשי המקום חטאו כ\"כ בעיני ה', עד שנתחייבו כלי' למקום (ועד שיש צורך לאבד את מקום מגורם). אבל בכל זה לא נאמר אצלם לשון של \"וימח\"<sup data-n=\"353\">50</sup> ונח­מה (חרטה) על עצם בריאתם, ע\"ד שמצי­נו במבול.\nוזהו גם הטעם לחילוק העיקרי בין המבול והפיכת סדום, דגבי הפיכת סדום",[["341","40","להעיר מרד\"ק כאן (ט, טו­טז). אבודרהם הל' ברכות שער ח'."],["342","41","ודלא כרד\"ק ומהרש\"א שבהערה 43. וכן בסוטה יא, א. תוספתא תענית פ\"ב, יא (ויל\"ש פרשתנו רמז סא) \"מבול של יחידים יש\". ע\"ש (וראה גם אברבנאל, עקידה ועוד פרשתנו כאן). — וראה הערה 59."],["334","34","שם ט, יא."],["344","42","שם, טו."],["345","43","כפירוש הרד\"ק (שם, יא). וכן בחדא\"ג מהרש\"א לסוטה שם."],["346","*43","ראה גליון מהרש\"א סוטה שם."],["347","44","יתרו כ, י. ועוד."],["348","45","אחרי טז, יז."],["349","46","פרשתנו ז, כג."],["350","47","ס\"פ בראשית (ו, ו­ז)."],["351","48","פ' ראה יג, טז­יז."],["352","49","וירא יט, כד­כה. (ולהעיר מתוספתא ויל\"ש שהועתק לקמן בשוה\"ג להערה 59). וראה לקמן ע' 72 ואילך."],["353","50","ורק בעמלק נאמר (בשלח יז, יד) \"מחה אמחה את זכר עמלק\", \"תמחה את זכר עמלק\" (ס\"פ תצא. וראה רש\"י שם). ואכ\"מ."],["e1","*","בהבא לקמן ראה גם \"רשימות\" חוברת ג' (קה\"ת, תשנ\"ה) ע' 37 ואילך. המו\"ל."]]],[1301670098,"מצינו שאם היו בה צדיקים היו ניצולים, כטענת אברהם<sup data-n=\"354\">51</sup> \"האף תספה צדיק עם רשע. . חלילה לך גו' להמית צדיק עם רשע\", אלא שלפועל כל אנשי סדום<sup data-n=\"355\">*51</sup> היו \"רעים וחטאים לה' מאד\"<sup data-n=\"356\">52</sup> משא\"כ גבי המבול לא היתה הגבלה זו, שהרי כל העולם כולו (מלבד נח ומשפחתו) נאבד, וודאי אין לומר שכל אנשי דור המבול ממש וקטני קטנים בכלל (מלבד נח ומשפחתו) היו גרועים כ\"כ עד שנת­חייבו כלי'<sup data-n=\"357\">53</sup>:\nוהיינו לפי שהמבול לא הי' בדרך עונש (משפט מיתה כו'), אלא חרטה על עצם בריאת האדם, ולכן לא נפק\"מ בין רשע גמור לרשע שאינו גמור (שיש לו גם מעשים טובים) כו', דכאשר לא קיים רצון על בריאת האדם בדרך ממילא הכל נאבד<sup data-n=\"358\">54</sup> [והצלת נח ומשפחתו היתה כדי<sup data-n=\"359\">55</sup> לבנות מהם \"עולם<sup data-n=\"360\">56</sup> חדש\"<sup data-n=\"361\">*56</sup>].\nומזה מובן, שהחילוק בין גדר המבול ושאר עונשים שייך גם כשהמדובר באומה ומדינה אחת או עיר אחת וכיו\"ב. שאפשר להיות מצב שהנהגתם גרועה כ\"כ עד שע\"פ שורת הדין הי' הקב\"ה מתחרט על בריאתם כו' והי' צ\"ל בהם \"וימח\"<sup data-n=\"362\">57</sup>.\nוזהו החידוש של הבטחת הקב\"ה<sup data-n=\"334\">34</sup> \"והקימותי את בריתי אתכם ולא יכרת כל בשר עוד גו' ולא יהי' עוד מבול לשחת הארץ\", שהיא שוללת גם האפ­שריות<sup data-n=\"364\">58</sup> של השחתת חלק מן העולם<sup data-n=\"365\">59</sup> —",[["354","51","וירא יח, כג­כה."],["355","*51","רש\"י וירא יט, ד ד\"ה כל העם."],["356","52","ל' הכתוב לך יג, יג. ועד\"ז וירא יח, כ."],["357","53","ומ\"ש (פרשתנו ו, יב) \"השחית כל בשר\" — הרי פרש\"י שם \"אפי' בהמה חי' ועוף נזקקין כו'\", ואין ראי' ש\"כל אדם\" (ממש) השחית את דרכו."],["358","54","כמפורש ברש\"י (פרשתנו ו, יג) \"והורגת טובים ורעים\" (וראה לבוש שם. ומתורצת השקו\"ט במפרשי רש\"י). ולהעיר מפרש\"י וירא יח, כה ד\"ה חלילה לך (הב') ובמפרשי רש\"י שם. רש\"י שם כ, ד [ושאני פרש\"י בראשית (ה, לב) \"אם רשעים כו' ואם צדיקים כו' תיבות הרבה\" — דקאי בבני נח עצמו].\nורק אם היו י' צדיקים — הי' כל העולם ניצל בזכותם (רש\"י וירא יח, לב). וי\"ל כי \"טוב\" זה הי' מספיק להצדיק קיום העולם (ולהעיר מרמב\"ם הל' תשובה פ\"ג ה\"ב)."],["359","55","וע\"ד \"ואכלם ואעשה אותך לגוי גדול\" (תשא לב, י. ועד\"ז שלח יד, יב)."],["360","56","ל' המדרש ב\"ר פ\"ל, ח. וכ\"ה גם בפשטות (שאחרי המבול הי' עולם חדש)."],["361","*56","ראה סנהדרין (קח, א) ש\"אף על נח נחתך גזר דין אלא שמצא חן בעיני ה'\". וע\"פ המבואר בפנים י\"ל הכוונה, דכיון שהיתה חרטה על כללות בריאת האדם, לא היתה מועלת צדקתו של נח להצילו מגז\"ד זה, אלא שמצא חן בעיני ה', לבנות ממנו \"עולם חדש\". וראה מפרשי הע\"י שם."],["362","57","ע\"ד פרש\"י (הנ\"ל הערה 31) \"שעלה אוקיינוס והציף (רק) שליש העולם\". — אלא שזה הי' לפני המבול (וכמו הכנה אליו — ראה רש\"י שם)."],["334","34","שם ט, יא."],["364","58","ולהעיר מפרש\"י (פרשתנו ט, ט), שהבטחת הקב\"ה באה מפני דאגתו של נח לעסוק בפו\"ר, \"עד שהבטיחו הקב\"ה שלא לשחת העולם עוד\" — והרי מובן בפשטות, דאף שעיקר דאגה זו היתה באיבוד כל העולם (ע\"ד רש\"י בראשית ד, כד), מ\"מ, בודאי הי' דואג שגם חלק מצאצאיו לא יהי' נאבד לגמרי (ולהעיר מרש\"י בראשית ה, לב)."],["365","59","ברש\"י ישן שמות (א, י) — מסוטה יא, א — \"והם לא הבינו שעל כל העולם אינו מביא מבול אבל הוא מביא על אומה אחת\". — אבל צ\"ע אם זהו מרש\"י עצמו (ובדפוס א' וב' דפרש\"י, וכן בכת\"י רש\"י שתח\"י — ליתא). ועוד י\"ל, שעיקר הכוונה שם היא לעונש (והריגה) ע\"י מים (ולא איבוד ו\"וימח\", המבואר בפנים). כי הבטחת הקב\"ה היתה בשתים: (א) שלא יהי' עוד מבול על כל העולם (אבל על חלק מן העולם שייך). (ב) שלא לשחת כל בשר<sup data-n=\"e6\">*</sup>, דהיינו מחיית כל היקום לשם איבוד (וי\"ל שזה לא שייך אפילו על חלק מן העולם)."],["e6","*","להעיר מזבחים קטז, א (ומכילתא ר\"פ יתרו. ועד\"ז ביל\"ש שבהערה 41): מבול של אש מביא. . א\"ל כבר נשבע שאינו משחית כל בשר. אבל בסוטה שם (וכן בתוספתא ויל\"ש שבהערה הנ\"ל), שרק מבול של מים אינו מביא, משא\"כ ע\"י אש וחרב (ובתוספתא ויל\"ש שם: של אש ושל גפרית. . כדרך שהביא על הסדומיים). וראה ערכין יז, א (ולכאורה זוהי גם שיטת הרמב\"ם בהל' תשובה שם: וכן כל העולם כולו כו'. ע\"ש). ואכ\"מ."]]],[1301670099,"בדומה להשחתת העולם ע\"י המבול, דהיינו בכוונה למחות ולאבד כליל חלק זה של העולם.\nז. ובזה מתורץ פרש\"י עה\"פ \"בענני ענן\" — \"כשתעלה במחשבה לפני להביא חשך ואבדון לעולם\", שמזה משמע שכל פעם שרואים קשת ה\"ז בגלל שהיתה מחשבה לפניו להביא חשך ואבדון לעו­לם:\nדיוקו של רש\"י הוא \"חשך ואבדון לעולם\", כלומר, לא השחתת כל העולם כולו, אלא \"חשך ואבדון לעולם\", היינו \"חשך ואבדון\" בחלק מסויים של העו­לם<sup data-n=\"366\">60</sup>, שאם תעלה מחשבה לפניו להביא כלי' והשחתה (לא בדרך עונש, אלא) בתור \"חשך ואבדון\", למחות את היקום אשר ברא (ניחום על עצם בריאתו) — לו יהא אפילו בחלק מסויים של העולם — אזי ע\"י ראיית הקשת נשללת מחשבה זו.\nודבר זה שייך במשך כל הדורות, שגם אם מצב כללות העולם הוא כדבעי, מ\"מ אפשר שישנם מקומות בעולם שההנהגה שם היא בשפל המצב ביותר, ע\"ד הנהגתם של אנשי דור המבול, ולכן רואים שם קשת, כדי לשלול \"חשך ואבדון\" באותו מקום ששם ההנהגה היא באופן בלתי רצוי.\nח. וע\"פ כל הנ\"ל מובן יסודו של רש\"י לפרש שהדורות שלא נראתה בהם הקשת הי' זה מפני \"שצדיקים גמורים היו\" (כללות כל הדור) — כי העדר ראיית הקשת מורה, שאין אף מקום אחד בעולם (היינו בבני ישראל, שבשבילם נברא העולם, כפרש\"י בתחילת פרשת בראשית<sup data-n=\"367\">61</sup>) שאצלם ישנה הנהגה בלתי רצוי' (באופן שראויים ל\"חשך ואבדון\").\nוזהו טעמו של רש\"י לפרש שכללות הדור \"צדיקים גמורים היו\", שרק בגלל זה אפשר לומר \"שלא הוצרכו לאות\"<sup data-n=\"368\">62</sup>. וענין זה מצינו בפירוש גבי חזקיהו המלך, וכנ\"ל שבימיו \"בדקו מדן ועד באר שבע ולא מצאו עם הארץ כו' ולא מצאו תינוק ותינוקת איש ואשה שלא היו בקיאין בהלכות טומאה וטהרה ועל אותו הדור הוא אומר כו'\", היינו שבכל מקומות מושבות בנ\"י היו כדבעי כו', ומזה מובן שכן הי' גם מצב דורו של רשב\"י (וכ­מפורש ברש\"י כאן ש\"צדיקים גמורים היו\")<sup data-n=\"369\">63</sup>.\nועפ\"ז יובן עוד יותר מ\"ש רש\"י \"שיש דורות כו' כמו דורו של חזקיהו כו'\", שמזה משמע, שהיו יותר מב' דורות (כנ\"ל ס\"א) — כי כל זמן שהנהגת בני ישראל אינה כהנהגת אנשי דור המבול, אין צריכים לאות הקשת. ובודאי היו כו\"כ דורות, שהנהגת כל ישראל, לכל מושבותיהם, היתה כדבעי, עכ\"פ הרבה יותר טוב מהנהגת דור המבול, באופן שלא הי' אף מקום אחד בעולם (בבני ישראל) שראויים ח\"ו לעונש המבול<sup data-n=\"370\">64</sup>.",[["366","60","ובפרט ע\"פ הגירסא בדפוס א' דפרש\"י — \"בעולם\" (לא \"לעולם\")."],["367","61","שמזה מובן, שלאחרי מ\"ת, הבאת מבול לעולם תלוי' בהנהגתם של ישראל דייקא."],["368","62","משא\"כ זה שצדיק הדור מגין על כל הדור — אינו שולל (עכ\"פ ע\"ד הפשט) עונש על חלק (או יחידים) של הדור, אלא היא הגנה כללית על כללות הדור."],["369","63","ומפורש הדבר בכ\"מ בזהר (ראה זח\"ב ט, א. קמז, א. זח\"ג עט, רע\"א. ועוד)."],["370","64","אלא שצע\"ק לשון רש\"י \"שצדיקים גמורים היו\" — שע\"פ הנ\"ל, גם אם לא היו צדיקים גמורים, לא הוצרכו לאות הקשת.\nויש לומר, שאין כוונת רש\"י ב\"צדיקים גמורים היו\", שכאו\"א מאנשי הדור הי' בגדר \"צדיק גמור\" ממש, אלא שזהו תיאור הדור, דכיון שכללות כל הדור היו צדיקים, לכן הדור נקרא בשם \"צדיקים גמורים\" (בסגנון אחר: \"גמורים\" אינו תואר איכות הצדקות, אלא כמות הצדקות, שכל הדור בשלימות היו צדיקים). ועצ\"ע."]]],[1301670100,"ט. והנה הטעם הפנימי שלדעת המד­רש רק בב' דורות של חזקיהו המלך ורשב\"י לא נראתה הקשת [וגם רש\"י נקט ב' דורות אלו דוקא (אף שלשיטת רש\"י היו עוד דורות כאלה)] — יש לומר:\nמבואר בכ\"מ<sup data-n=\"371\">65</sup> שהמבול בא \"לטהר את הארץ\", שזוהי גם כוונת חז\"ל<sup data-n=\"372\">66</sup> שנח \"ראה עולם חדש\", כי ע\"י המבול נעשה חידוש במעשה בראשית, שהעולם נטהר ונתעלה למדריגה חדשה, עד שנקרא \"עולם חדש\".\nוזהו ענינה של אות הקשת ש\"לא יהי' עוד מבול לשחת הארץ\" — להורות, שע\"י המבול נטהרה הארץ באופן שאי אפשר עוד שהעולם יהי' במצב שפל כזה שיהי' ראוי למבול<sup data-n=\"373\">67</sup>.\nוהנה התחדשות כזו בהבריאה תהי' בביאת משיח צדקנו, שאז יהיו \"השמים החדשים והארץ החדשה\"<sup data-n=\"374\">68</sup>.\nוזהו גם הרמז שדוקא אצל חזקיהו המלך ורשב\"י מצינו שלא הוצרכו לאות הקשת, כי שניהם שייכים לביאת ה­משיח: בנוגע לחזקיהו נאמר שביקש הקב\"ה לעשותו משיח (כנ\"ל), וכן רשב\"י חיבר ספר הזהר, אשר \"יפקון בי' מן גלותא ברחמי\"<sup data-n=\"375\">69</sup>.\nונמצא שע\"י עבודתם היו ראויים לפעול התחדשות בהבריאה, ולכן \"לא הוצרכו לאות\" הקשת, כיון שהיו יכולים לפעול התחדשות הבריאה (ע\"ד ההת­חדשות הנעשית ע\"י המבול) על ידי עבודתם הם.\n<span data-k=\"q\">(משיחת ש\"פ נח תשמ\"ה)</span>",[["371","65","תו\"א ריש פרשתנו. וכן בתו\"ח, אוה\"ת ודרושי רבותינו נשיאינו שלאח\"ז."],["372","66","נסמן לעיל הערה 56."],["373","67","ראה עד\"ז אברבנאל ועקידה פרשתנו. וראה לקו\"ש חט\"ו ע' 52 ואילך (ובהנסמן בהערה 31 שם)."],["374","68","ישעי' סו, כב."],["375","69","רע\"מ נשא קכד, ב. וראה גם תקו\"ז ת\"ו בסופו. — ולהעיר מזח\"ב שם (ע\"ד דורו של רשב\"י) \"עד דייתי מלכא משיחא\". וראה סידור (סוף ש' הל\"ג בעומר) לפי שהי' שרשו. . מבחי' משיח."]]],[1301670101,"<h3>שיחה א</h3>\nא. שנו חכמים<sup data-n=\"376\">1</sup>: חמשה<sup data-n=\"377\">2</sup> קנינים קנה הקב\"ה בעולמו ואלו הן, תורה קנין אחד, שמים וארץ קנין אחד, אברהם קנין אחד, ישראל קנין אחד, בית המקדש קנין אחד.\nוצריך להבין: מל' הברייתא \"חמשה קנינים קנה הקב\"ה בעולמו\" מובן, שהעולם כולו אינו קנינו של הקב\"ה. ואינו מובן: כיון שהוא ית' ברא הכל הרי הכל שלו וברשותו, וכמ\"ש<sup data-n=\"378\">3</sup> \"לה' הארץ ומלואה תבל ויושבי בה כי הוא גו' יסדה גו'\" (ועד\"ז בעוד מקומות), וכפרש\"י עה\"פ<sup data-n=\"379\">4</sup> \"קונה שמים וארץ\" [שהובא לקמן בבריי­תא כראי' על \"אברהם קנין אחד\", \"ד­כתיב<sup data-n=\"379\">4</sup> ויברכהו ויאמר ברוך אברם לא­ל עליון קונה שמים וארץ\"] — \"ע\"י עשייתן קנאן להיות שלו\".\nגם צ\"ב (וכפי שעמדו במפרשים):\nא) כיון ששמים וארץ, שהם כללות העולם, הם קנינו של הקב\"ה — איזה דבר \"בעולמו\" אינו בכלל קנין זה?\nב) מדוע לא נחשבו שמים וארץ כשני קנינים?\nג) לראי' ששמים וארץ הם קנין אחד — הובא הכתוב<sup data-n=\"381\">5</sup> \"השמים כסאי והארץ הדום רגלי גו'\" (ואח\"כ הובאה ראי' נוספת<sup data-n=\"382\">6</sup> מהכתוב<sup data-n=\"383\">7</sup> \"מה רבו גו' מלאה הארץ קנינך\", שבו לא נזכרו \"שמים\") — ולכאורה הו\"ל להביא ראי' מפורשת מהפסוק \"קונה שמים וארץ\"<sup data-n=\"384\">8</sup>?\nד) למה נמנה אברהם כ\"קנין\" בפני עצמו, ואינו בכלל ה\"קנין\" ד\"ישראל\" (והרי תחילת עם ישראל היא אברהם אבינו, הראשון דהג' אבות)?\nה) בפסוק שהביא לראי' על אברהם, \"ויברכהו ויאמר ברוך אברם לא­ל עליון קונה שמים וארץ\", לא נזכר שאברהם נקרא \"קנין\" (אלא שאברהם<sup data-n=\"385\">9</sup> הוא \"קונה שמים וארץ\").\nו) מהו הדיוק אומרו \"קנין אחד\" בכל אחד מהקנינים — \"תורה כו' שו\"א קנין אחד אברהם קנין אחד כו'\" — ולא אמר \"קנין שני, שלישי וכו'\". ויתרה מזה — למה מוסיף התנא בכלל תיבות אלו \"קנין אחד\", ולא נקט בקיצור: \"חמשה קנינים כו' בעולמו, ואלו הן, תורה, שו\"א, אברהם, ישראל ובית המקדש\".",[["376","1","אבות פ\"ו, י."],["377","2","כ\"ה באבות לפנינו. וי\"ג \"ד'\". וכבר הובאה השקו\"ט במפרשים ע\"ד שינויי הגירסאות שבזה בכ\"מ — פסחים פז, ב. מכילתא בשלח עה\"פ (טו, טז) עם זו קנית. ספרי האזינו עה\"פ (לב, ו) אביך קניך. ועוד (נסמנו בתו\"ש פרשתנו יד, יט אות קיג). — ראה מחזור וויטרי, נחלת אבות (לאברבנאל) ועוד אבות שם. וראה ע\"ד החסידות אוה\"ת במדבר (שבועות) ע' קפא ואילך (ושם ע' קצט). סה\"מ תרל\"ו ח\"ב ע' רפ ואילך (ושם ע' תקל ואילך). ועוד."],["378","3","תהלים כד, א­ב. וראה ר\"ה (לא, רע\"א) \"על שם שקנה כו'\". — ובנוסח תפילת העמידה (ברכת אבות) \"קונה הכל\"."],["379","4","פרשתנו שם. וראה גם רש\"י ר\"פ בראשית \"כל הארץ של הקב\"ה היא, הוא בראה כו'\". ועוד."],["379","4","פרשתנו שם. וראה גם רש\"י ר\"פ בראשית \"כל הארץ של הקב\"ה היא, הוא בראה כו'\". ועוד."],["381","5","ישעי' סו, א."],["382","6","וראה לקמן סעיף ד."],["383","7","תהלים קד, כד."],["384","8","וכ\"ה בפסחים שם."],["385","9","נוסף ע\"ז שבפשטות קאי \"קונה שמים וארץ\" על \"א­ל עליון\" ולא על \"אברם\", וע\"ד הנאמר להלן שם בדברי אברהם (יד, כב). וראה במפרשים ומאמרים שנסמנו בהערה 2."]]],[1301670102,"ב. במפרשים ביארו<sup data-n=\"386\">10</sup>, שכוונת התנא בלשון \"קנין\" כאן אינה לזה שהדברים הם בבעלותו וברשותו של הקב\"ה — כי ענין זה הוא בכל הנבראים כולם — אלא לענין עמוק יותר בגדר \"קנין\". כלומר: דברים אלה אינם רק כמו רכושו של אדם שהוא דבר בפ\"ע הנמצא בבעלותו, ויכול לעשות בו כרצונו, אלא עצם מציאותם היא \"רשו­תו\" של הקב\"ה, כי כל ענינם של דברים אלה הוא מה שהם \"משמשים<sup data-n=\"387\">11</sup> לאלקותו יתברך\".\nובזה מתורץ גם דיוק לשון הברייתא \"חמשה קנינים קנה הקב\"ה בעולמו\" — דלכאורה תיבת \"בעולמו\" מיותרת. ועוד זאת — שמדייק \"בעולמו\", דלכאורה הול\"ל \"בעולם\".\nאלא שבזה מדגיש התנא, שכוונתו כאן לדרגא עמוקה יותר בגדר \"קנין\", דאף שכללות העולם הוא \"עולמו\", קנינו ור­כושו של הקב\"ה (כיון שהוא ית' ברא את הכל), מ\"מ אין זה דומה לחמשה דברים אלה שהם קנויים לו ית' באופן מיוחד, יתר על קנינו בכל העולם כולו.\nכי כל העולם כולו, גם כפי שניכר בו שהוא \"עולמו\", קנינו של הקב\"ה, ה\"ז ב­אופן שהוא מציאות לעצמו שהיא ברשותו ובבעלותו של הקב\"ה (ולכן חל עליו תואר \"עולם\", מלשון העלם<sup data-n=\"388\">12</sup>, דכיון שהוא מציאות בפ\"ע, הרי זה העלם והסתר על אלקות); משא\"כ חמשה \"קנינים\" אלה אינם ענין של \"מציאות\" נפרדת, אלא מציאותם ומהותם היא גילוי אלקות ומעיקרא הם כולא חד עם קוב\"ה: התורה היא חכמתו ורצונו של הקב\"ה; נשמות ישראל (ושל אברהם בראש) הם \"חלק אלוקה ממעל ממש\"<sup data-n=\"389\">13</sup>; וביהמ\"ק הוא מקום מנוחתו ית', \"ועשו<sup data-n=\"390\">14</sup> לי מקדש ושכנתי בתוכם\".\nועפ\"ז מובן זה שלא הביא לראי' על \"שמים וארץ קנין אחד\" את הכתוב \"קונה שמים וארץ\" אלא \"כה גו' השמים כסאי והארץ הדום רגלי\", כי \"קונה שמים וארץ\" פירושו (כנ\"ל) ש\"ע\"י עשייתן קנאן להיות שלו\", ואינו ענין לגדר ה\"קנין\" המבואר כאן; ולכן מביא הא ד\"השמים כסאי וה­ארץ הדום רגלי\", דלא קאי על כללות ענין שמים וארץ, אלא על פרט זה שבהם, מה שעל ידם יש התגלות אלקות בעולם, שהשמים הם כסאו של הקב\"ה, והארץ — הדום רגליו.\n[ולכן נחשבו \"קנין אחד\", כי בענין זה, מה שהם אמצעי לגילוי הקב\"ה בעולם, הרי שניהם יחד הם ענין אחד, כמו כסא והדום רגלים כפשוטם, שעל ידי שניהם יחד יושב האדם על מקומו במנוחה כו'<sup data-n=\"391\">15</sup>].\nויש לומר, שזהו גם מה שמרמז התנא בהוסיפו \"קנין אחד\" לאחרי כל קנין, להו­רות, שגדר קנינים אלה הוא לגלות את ה\"אחד\", אחדותו של הקב\"ה<sup data-n=\"392\">16</sup> [ע\"ד פירוש כ\"ק מו\"ח אדמו\"ר<sup data-n=\"393\">17</sup> בלשון ההגדה \"אחד חכם ואחד רשע וכו'\", שבכל א' מהד' בנים ישנו ה\"אחד\"].\nג. אבל אין זה ביאור מספיק, כי מ­",[["386","10","ראה נחלת אבות שם. דרך חיים (לה­מהר\"ל). ועוד. מאמרי אדמו\"ר האמצעי שמות ח\"א ע' נא.\nביאור \"חמשה קנינים\" ע\"ד החסידות — ראה מאמרי אדה\"ז על מארז\"ל (ע' קכ ואילך). מאמרי אדמו\"ר האמצעי במדבר ח\"ב (ע' תתנא ואילך). אוה\"ת במדבר הנ\"ל (ע' קעד ואילך). סה\"מ תרל\"ו הנ\"ל (ע' רנא ואילך. שם ע' תקכד ואילך). ועוד."],["387","11","ל' המאירי בבית הבחירה על אבות שם. וראה נחלת אבות ודרך חיים שם."],["388","12","לקו\"ת שלח לז, ד. ובכ\"מ."],["389","13","ל' התניא רפ\"ב."],["390","14","תרומה כה, ח."],["391","15","ראה גם דרך חיים שם. וראה ע\"ד החסידות לקו\"ת שה\"ש נא, ב. ועוד."],["392","16","ראה גם אוה\"ת שם ס\"ע קצח."],["393","17","ס' השיחות תש\"ג ע' 74."]]],[1301670103,"לשון התנא \"חמשה קנינים קנה הקב\"ה\" (לא \"חמשה קנינים יש לו להקב\"ה\"), מש­מע, שזה שחמשה דברים אלה הם קנינו של הקב\"ה בא ע\"י פעולה וחידוש, כאילו הם תחילה (כמו) ברשות אחרת והקב\"ה קונה אותם — וע\"פ הנ\"ל, הרי אדרבה, דוקא חמשה דברים אלה הם מלכתחילה כולא חד עם קוב\"ה?\nונ\"ל, בהקדם דיוק ל' הברייתא \"חמשה קנינים קנה הקב\"ה בעולמו\", שבזה מודגש, שקאי כאן כפי שחמשה דברים אלה נמצאים בעולם. והיינו, דזה שהם \"קנינו\" של הקב\"ה אינו רק כפי שהם למעלה מן העולם [כמחז\"ל<sup data-n=\"394\">18</sup> שתורה ישראל וביהמ\"ק הם מהדברים שקדמו לעולם, וגם זה ששמים וארץ הם \"כסאי. . והדום רגלי\" הוא כפי שהם למעלה משאר נבראים], אלא שגם כפי שירדו ונתלבשו בגשמיות העולם, נשארו במעלתם העקרית, שהם \"קנינו\" של הקב\"ה.\nועפ\"ז יובן גודל העילוי של חמשה דברים אלה לגבי שאר הנבראים — ש­בגלל זה רק הם נקראים בשם \"קנין\":\n\"קנין\" מורה על העתקת החפץ כמו שהוא מרשות לרשות. והיינו, שלא נעשה שינוי בגוף החפץ, כ\"א רק זה שיוצא מרשות המוכר לרשות הלוקח, \"שמתחילה היתה הסחורה מונחת בקופסא אצל המוכר ועל ידי הקנין בא. . להלוקח\"<sup data-n=\"395\">19</sup>.\nוכמבואר<sup data-n=\"396\">20</sup> גם בענין ד' הלשונות<sup data-n=\"397\">21</sup> \"ברוך עושך. . יוצרך. . בוראך. . קונך\", דג' הלשונות עושך יוצרך ובוראך מורות על התהוות הנברא ובריאתו מאין ליש, וקאי על העולמות שהם מציאות יש ו\"הוית דבר חדש\"<sup data-n=\"398\">22</sup>, משא\"כ הלשון \"קונך\" מורה על דבר שבא מן ההעלם אל הגילוי (כעין שינוי רשות), אבל לא \"הוית דבר חדש\".\nובעניננו:\nאף שכל העולם כולו הוא קנינו של הקב\"ה להיותו בורא העולם, מ\"מ ענין זה אינו ניכר בהעולם מצד עצמו; וכדי שיהי' ניכר בעולם שהוא \"עולמו\" של הקב\"ה צ\"ל שינוי בחפצא דהעולם, דרק ע\"י בי­טול ישות העולם, הזדככות חומריותו והעלאתו למעלה, אפשר להכיר בעניני ה­עולם שמציאותם היא \"אמיתת המצאו\" (ש­לא נמצאו אלא מאמיתת המצאו<sup data-n=\"399\">23</sup>). דכשם שמציאותם היא בגדר בריאה יצירה וע­שי', הווית דבר חדש, כמו\"כ לאידך, הת­אחדותם עם הקב\"ה היא ע\"י השינוי וה­חידוש במציאותם, לעשותם מ\"יש\" ל\"אין\" — ולכן לא חל עליהם גדר ותואר \"קנין\".\nמשא\"כ חמשה דברים אלה נקראים \"קנין\", לפי שאופן התאחדותם עם הקב\"ה אינו אלא בגדר \"קנין\"<sup data-n=\"400\">24</sup>, העברה מרשות לרשות בלי שינוי (וכ\"ש לא חידוש) ב­חפצא שלהם, שדברים אלה כמו שהם הרי הם ברשותו של הקב\"ה, לפי שכל ענינם וגדרם הוא גילוי אלקות.\nוזהו שהתנא מחדש \"חמשה קנינים קנה הקב\"ה בעולמו\" — דזה שדברים אלה הם \"קנין\" (שאין כאן שינוי חפצא, אלא רק העברה מרשות לרשות), הוא (גם) כפי שירדו ונתלבשו בעולם. דשאר הנבראים שהם מחודשים מאין ליש, הרי העלאתם",[["394","18","ראה פסחים נד, א. ב\"ר פ\"א, ד (ושם גם בנוגע לאבות (אברהם)). ועוד."],["395","19","תו\"א משפטים עה, ד."],["396","20","שם עו, ב."],["397","21","נוסח קידוש לבנה (כנוסח האריז\"ל (כסדר ד' עולמות אבי\"ע) — ובמס' סופרים (פ\"כ ה\"ב) לפנינו בשינוי סדר (כר\"ת יעקב). וראה טאו\"ח סו\"ס תכו. ואכ\"מ)."],["398","22","ל' התו\"א שם עה, ד."],["399","23","רמב\"ם ריש הל' יסודי התורה."],["400","24","וגם שמים וארץ, שעליהם נאמר \"בראשית ברא גו'\" — י\"ל שזה שהם \"כסאי. . והדום רגלי\" (של הקב\"ה) הוא בגדר \"קנין\"."]]],[1301670104,"לקדושה שיהי' ניכר בהם שהם קנויים לה' הוא ע\"י שינוי החפצא (כנ\"ל), שבירת ו­ביטול החומריות וזיכוך הגשמיות כו'; משא\"כ חמשה דברים אלה, הרי גם כפי שהם מלובשים בגשמיות העולם אינם אלא \"קנין\"<sup data-n=\"401\">25</sup>, שהתאחדותם עם קוב\"ה אינה זקוקה לשינוי חפצא.\nועפ\"ז מתורץ דיוק ל' התנא \"חמשה קנינים קנה הקב\"ה בעולמו\" (ולא \"יש לו להקב\"ה\"), כי ענין זה, שההתלבשות בגשמיות העולם אינה פועלת שינוי במהות ומעלת דברים אלה כדברים אלקיים, אינו בדרך ממילא (דאדרבה, ע\"פ טבע הדברים התלבשות כזו צריכה לפעול שינוי), אלא זהו פעולה מיוחדת מלמעלה<sup data-n=\"402\">26</sup> \"לקנות\" דברים אלה.\nד. הסברת הענין בפרטיות:\n\"תורה קנין אחד\": אע\"פ שהתורה \"ירדה. . ממדריגה למדריגה. . עד שנת­לבשה בדברים גשמיים וענייני עוה\"ז\"<sup data-n=\"403\">27</sup>, וכן שהתורה נתלבשה בטענות של שקר כו'<sup data-n=\"404\">28</sup>, הרי אין ירידה והתלבשות זו גורעת ח\"ו ממעלתה העצמית<sup data-n=\"405\">29</sup> שהיא חכמתו ורצונו של הקב\"ה, ואין צורך בשינוי חפצא (ביטול ה\"גשמיות\", שבה נתלבשה התורה) בשביל התאחדותה עם קוב\"ה.\nועד\"ז בשאר ה\"קנינים\":\n\"ישראל קנין אחד\": גם כפי שנשמת ישראל ירדה לעוה\"ז ונתלבשה בגוף ה­אדם, שעי\"ז נתגשמה (קצת) בערך למע­לתה ורוחניותה קודם התלבשותה בגוף (דאל\"כ לא היתה שייכת להתלבשות ול­החיות גוף האדם), הרי גם במצב זה הרי היא \"חלק אלקה ממעל ממש\"<sup data-n=\"406\">30</sup>.\nובזה מתורץ בפשטות הטעם שאצל ישראל לא הסתפק התנא בהבאת הכתוב<sup data-n=\"407\">31</sup> \"עד יעבור גו' עם זו קנית\" (שבו מפורש שישראל הם \"קנין\") אלא מוסיף \"ואומר<sup data-n=\"408\">32</sup> לקדושים אשר בארץ המה גו'\" — כי הפסוק \"עד יעבור גו'\" קאי בזמן שהיו ישראל במדבר, ששם לא עסקו (כ\"כ) בדברים גשמיים, משא\"כ בכתוב \"לקדו­שים אשר בארץ המה גו'\", שבו נרמזת עבודת ישראל בארץ דוקא, דגם בהיותם עסוקים בענינים ארציים — \"קדושים. . המה\".\nוכן בבית המקדש: זה שהוא בית גשמי, בנוי מדברים גשמיים כו', אינו מגרע מענין השראת השכינה שבמקדש, והקב\"ה נמצא ומתגלה שם בכל עצמותו.\nועוד יש לומר, דלא רק קדושת ה­מקדש עצמו אינה נגרעת ע\"י היותה מלו­בשת בבית גשמי, אלא גם הקדושה ה­מתפשטת ממנו בעולם כולו — כמחז\"ל<sup data-n=\"409\">33</sup>",[["401","25","וזהו גם הדיוק \"קנין אחד\", כידוע החילוק בין \"אחד\" ל\"יחיד\", ד\"יחיד\" היא האחדות שמצד למעלה מן העולמות, משא\"כ \"אחד\" ענינו — המשכת וגילוי אחדותו של הקב\"ה בעולם גופא, בז' רקיעים וארץ וד' רוחות העולם (תו\"א ר\"פ וארא. ובכ\"מ)."],["402","26","וי\"ל שענין זה הוא מצד (המשכת) העצמות, דמצד יש האמיתי אפשר שיהי' חיבור דיש הנברא כמו שהוא במציאותו עם יש האמיתי (ראה ביאוה\"ז בשלח (מג, ג). ועוד. וראה סה\"מ מלוקט ח\"א ע' צג)."],["403","27","ל' התניא פ\"ד."],["404","28","ראה קונטרס עץ החיים פי\"א (ע' 38). סה\"מ תש\"ד ע' 108."],["405","29","להעיר מברכות (כב, א) אין ד\"ת מקבלין טומאה."],["406","30","עיין ביאוה\"ז לאדמו\"ר האמצעי (קטו, ב) ולהצ\"צ (ע' תקמח). ד\"ה אנכי וד\"ה פנים בפנים תרס\"ז (בהמשך תרס\"ו). ועוד. — ולהעיר מלקו\"ש ביאורים בלקוטי לוי\"צ על אגה\"ת (קה\"ת, תשנ\"ב) ע' 86 ואילך, 98 ואילך."],["407","31","בשלח טו, טז."],["408","32","תהלים טז, ג."],["409","33","מנחות פו, ב. ובתנחומא תצוה ו (בסופו): שיהא האור יוצא מן בית המקדש ומאיר לעולם. ועוד."]]],[1301670105,"\"לא לאורה אני צריך כו' עדות הוא לכל באי עולם שהשכינה שורה בישראל\" — היא בגדר \"קנין\", שלא נשתנתה ממהותה ומעלתה ע\"י התפשטותה לחוץ.\nוזהו שמביא גם גבי בית המקדש שני כתובים: \"מכון לשבתך פעלת ה' גו'<sup data-n=\"410\">34</sup> ואומר<sup data-n=\"411\">35</sup> ויביאם אל גבול קדשו הר זה קנתה ימינו\": הפסוק הא', \"מכון לשבתך גו'\", מדבר בקדושת המקדש עצמו, וה­פסוק השני, \"ויביאם אל גבול קדשו, הר זה קנתה ימינו\", קאי על התפשטות קדושת המקדש לחוץ, כל הר הבית (\"הר זה\"), ועד לכל ארץ ישראל כולה, הנקראת \"גבול קדשו\"<sup data-n=\"412\">36</sup> (מפני קדושת המקדש שבה).\nועד\"ז ב\"שמים וארץ קנין אחד\": הענין ד\"קנינו\" של הקב\"ה אינו רק בשמים וארץ הרוחניים (להיותם \"כסאי. . והדום רג­לי\"), אלא זה נמשך גם בשמים וארץ גשמיים, דבהם ישנם ענינים של גילוי אלקות (שלמעלה מהטבע), ע\"ד הא דצבא השמים הם \"חזקים כיום הבראם\"<sup data-n=\"413\">37</sup>, ש­נצחיות זו היא התגלות כח האין סוף<sup data-n=\"414\">38</sup>, וכן כח הצמיחה שבארץ, שהוא גילוי כח האין סוף<sup data-n=\"415\">39</sup> שרק בכחו ויכלתו להוות יש מאין.\nולכן גם כאן לא הסתפק התנא בהבאת הכתוב \"השמים כסאי והארץ הדום רגלי\", אלא מוסיף ראי' שני', \"ואומר מה רבו גו' מלאה הארץ קנינך\", דגם בארץ הלזו התחתונה<sup data-n=\"416\">40</sup> נמשך ה\"קנין\" דשמים וארץ<sup data-n=\"417\">41</sup>.\nה. ע\"פ הנ\"ל יש לבאר גם הטעם ש­אברהם נמנה כאן כ\"קנין\" בפני עצמו, ואינו נכלל ב\"קנין\" הכללי ד\"ישראל\", ומביא לראי' הכתוב \"ויברכהו גו' קונה שמים וארץ\":\nמבואר במדרש<sup data-n=\"418\">42</sup>, שזה שאברהם נקרא \"קונה שמים וארץ\" הוא לפי שאברהם הכיר את הקב\"ה בין הבריות, שעי\"ז \"הקנהו להקב\"ה שמים וארץ\"<sup data-n=\"419\">43</sup>, ולכן א\"ל הקב\"ה \"מעלה אני עליך כאילו אתה שותף עמי בברייתו של עולם\"<sup data-n=\"418\">42</sup> (כאילו שאב­רהם הוא \"קונה שמים וארץ\"). זאת אומרת, שענינו של אברהם הוא, לגלות אחדותו של הקב\"ה בעולם גופא, שהבריות יכירו את השם.\nולכן נפרט אברהם כ\"קנין\" בפני עצמו, דזה ש\"ישראל קנין אחד\" קאי על נשמת כאו\"א מישראל, דגם בירידתה לעולם הזה והתלבשותה בגוף גשמי היא \"קנינו\" של הקב\"ה כנ\"ל באורך; אבל זה ש\"אב­רהם קנין אחד\" הוא מצד פעולתו בעולם, כהדגשת הכתוב שהביא לראי', שאברהם נקרא \"קונה שמים וארץ\". דזה שאברהם הי' יכול לפעול הכרת אלקות אצל הבריות עוד לפני מתן תורה, מורה על גודל הפלאת אברהם ואופן התאחדותו עם בוראו, \"א­ל עליון\"<sup data-n=\"421\">44</sup>, עד שלא זו בלבד",[["410","34","בשלח שם, יז."],["411","35","תהלים עח, נד."],["412","36","ראב\"ע ומצו\"ד שם."],["413","37","ראה ירושלמי ברכות פ\"א ה\"א."],["414","38","ראה ס' החקירה להצ\"צ בתחילתו (ד, א). שם קא, ב ואילך. ובכ\"מ."],["415","39","ראה תניא אגה\"ק סו\"ס כ (קלא, סע\"ב ואילך). ועוד."],["416","40","וגם שמים (גשמיים) בכלל \"ארץ\"."],["417","41","אבל לאידך לא אמר שהארץ עצמה היא הקנין, אלא שהארץ מלאה \"קנינים\", כי כנ\"ל, אין המדובר כאן בכך שכל הארץ כולה היא קנינו של הקב\"ה, אלא גדר \"קנין\" הוא — גילוי אלקות גם בגשמיות (באופן שאין צ\"ל שינוי חפצא, אלא הדבר כמו שהוא אפשר לעבור לרשותו של הקב\"ה), וענין זה אינו באופן גלוי בכל הנבראים, אף שהארץ \"מלאה\" ב\"קנינים\" כאלו, כנ\"ל."],["418","42","ב\"ר עה\"פ (פמ\"ג, ז)."],["419","43","ל' חז\"ל — סוטה ד, סע\"ב. אגדת בראשית פמ\"ט."],["418","42","ב\"ר עה\"פ (פמ\"ג, ז)."],["421","44","ולהעיר מלקו\"ת ואתחנן (ח, ריש ע\"ב) בפי' \"ברוך גו' לא­ל עליון קונה שמים וארץ\", \"ששמים וארץ רוחניות וגשמיות בטלין לפניו בשוה\". ע\"ש. — ע\"ד הנ\"ל בגדר \"קנין\", שנמצא למטה כמו למעלה בלי שינוי."]]],[1301670106,"שלא התפעל מכל העולם כולו, \"כל העו­לם כולו מעבר אחד והוא מעבר אחד\"<sup data-n=\"422\">45</sup>, אלא עוד זאת, \"אחד הי' אברהם\"<sup data-n=\"423\">46</sup>, שהמשיך \"ה' אחד\"<sup data-n=\"424\">47</sup> גם בארץ<sup data-n=\"425\">48</sup>, ע\"י שפעל הכרת אלקות גם בבריות עצמם, \"קונה שמים וארץ\".\n<span data-k=\"q\">(משיחות ש\"פ בלק וש\"פ ראה תשל\"ז; ד\"ה חמשה קנינים תשי\"ב)</span>",[["422","45","ב\"ר ספמ\"ב. פסיקתא רבתי פל\"ג."],["423","46","יחזקאל לג, כד. — ולהעיר מהפירוש (סה\"מ תרכ\"ז ע' סב) \"אחד הי' אברהם, אחד ואין כיוצא בו\", לפי ש\"הי' כו' תמיד בבחי' עליות המדריגות, בלא בחי' ירידה כלל\" (דלא כשאר צדיקים). ושם, ש\"נמשך מצד בחי' אני ה' לא שניתי\"."],["424","47","להעיר מב\"ר פל\"ח, ו (בתחילתו)."],["425","48","אור התורה (יהל אור) לתהלים ע' שנו. ושם, שלכן נאמר \"אחד\" ולא \"יחיד\" (וראה לעיל הערה 25)."]]],[1301670107,"<h3>שיחה ב</h3>\nא. לפני הציווי על מצות מילה שב­פרשתנו — \"ואתה<sup data-n=\"426\">1</sup> את בריתי תשמור גו' זאת בריתי אשר תשמרו גו' המול לכם כל זכר\" נאמרה לאברהם<sup data-n=\"427\">2</sup> ההבטחה \"ונתתי לך ולזרעך אחריך את ארץ מגו­ריך את כל ארץ כנען לאחוזת עולם\".\nומשמעות הכתובים היא שירושת הארץ תלוי' במצות מילה, וכ\"ה בפירוש בדרשת רז\"ל בתחלת פרשת מילה \"הת­הלך<sup data-n=\"428\">3</sup> לפני והי' תמים\" — \"התהלך<sup data-n=\"429\">4</sup> לפני במצות מילה\"; \"ואתנה<sup data-n=\"430\">5</sup> בריתי ביני וביניך\" — \"ברית<sup data-n=\"431\">6</sup> של אהבה וברית הארץ להורישה לך ע\"י מצוה זו\". ובב\"ר עה\"פ<sup data-n=\"432\">7</sup> \"אם מקיימין בניך את המילה הן נכנסים לארץ ואם לאו אין נכנסין לארץ. . כך אמר הקב\"ה לאברהם אבינו ונתתי לך ולזרעך אחריך וגו' על מנת ואתה את בריתי תשמור\", וכן מפורש בזהר וארא<sup data-n=\"433\">8</sup> ד\"כל מאן דאתגזר ירית ארעא\".\nוצריך להבין: הרי כבר הובטחה ארץ ישראל לאברהם אבינו בברית בין ה­בתרים, כמ\"ש<sup data-n=\"434\">9</sup> \"ביום ההוא כרת ה' את אברם ברית לאמר לזרעך נתתי את הארץ הזאת גו'\"<sup data-n=\"435\">10</sup>, ומה נוסף בהבטחה זו שתלוי' במצות<sup data-n=\"436\">11</sup> ברית מילה<sup data-n=\"437\">12</sup>?\nואף שלכאורה יש חידוש בהבטחה זו, שנתפרש בה שנתינת הארץ היא (באופן של) \"לאחוזת עולם\", הרי מלבד זאת שצריך ביאור מדוע דוקא פרט זה תלוי בקיום מצות מילה<sup data-n=\"438\">*12</sup>, הרי לפי פשוטו גם ההבטחה הקודמת היא \"לאחוזת עולם\", שהרי ניתנה ב\"ברית\", שברית היא — לנצח ועולמית שאין בה הפסק.\nב. והנה לכאורה יש לפרש שה­חידוש בהבטחה זו הוא, כדיוק לשון",[["426","1","יז, ט ואילך."],["427","2","שם, ח."],["428","3","שם, א."],["429","4","ל' רש\"י שם \"לפי מדרשו\". וראה נדרים לא, ב במשנה. ב\"ר פמ\"ו, א. תנחומא פרשתנו טז­יז. ובכ\"מ."],["430","5","יז, ב."],["431","6","פרש\"י שם. ולכאו' ה\"ז בהמשך להפירוש \"לפי מדרשו\", כי לפי פשוטו וכן לפי תרגומו — פי' \"התהלך לפני גו'\" אינו במצות מילה."],["432","7","פמ\"ו, ט."],["433","8","ח\"ב כג, א."],["434","9","טו, יח. וראה ב\"ר עה\"פ (פמ\"ד, כב): מאמרו של הקב\"ה מעשה. ובירושלמי חלה (פ\"ב ה\"א) \"כבר נתתי\". וראה לקו\"ש חט\"ו ע' 204 ואילך."],["435","10","וההבטחות על נתינת הארץ בתחלת פר­שתנו (יב, ז. יג, טו ואילך. ועוד) הי' לאחרי ברית בין הבתרים, דברית בין הבתרים הי' בהיות אברם בן ע' שנה (לפרש\"י בא יב, מ), והבטחות הנ\"ל היו כאשר הי' אברם בן ע\"ה שנה (פרשתנו יב, ד) — ראה של\"ה פרשתנו רעז, א."],["436","11","להעיר שבירושלמי נדרים פ\"ג ה\"ט, שמונה י\"ג הבריתות שבמצות מילה, מתחיל \"כתיב ביום ההוא כרת ה' גו'\", הפסוק הנאמר בברית בין הבתרים<sup data-n=\"e7\">*</sup>. ובתנחומא פרשתנו כ למד מהפסוקים דברית בין הבתרים — בנוגע למילה. ועל דברי הטור (יו\"ד סי' רס) \"ובזכותה (דמילה) נכרת לו ברית על נתינת הארץ\" כתב בב\"י \"נראה דהיינו מדכתיב ביום ההוא כרת ה' את אברם ברית לאמר לזרעך נתתי\". וראה ב\"ח שם."],["437","12","השייכות דמילה לארץ ישראל ע\"ד ה­חסידות — ראה לקו\"ת עקב (טז, ג ואילך). סידור (עם דא\"ח) קיא, א ואילך. ועוד."],["438","*12","ראה לקו\"ת וסידור שם."],["e7","*","ברמב\"ם סוף הל' מילה לא הובא. וראה לקו\"ש חכ\"ה ע' 54 ואילך."]]],[1301670108,"המדרש, \"אם מקיימין בניך את המילה הן נכנסין לארץ\", היינו שהמדובר כאן הוא לא על נתינת הארץ לישראל באופן של \"אחוזת עולם\" (כי זה הי' כבר ב­ברית בין הבתרים), אלא ע\"ד כניסתן של ישראל בפועל אל הארץ<sup data-n=\"439\">13</sup>, שהיא תלוי' בקיום מצות מילה. וכן יש לדייק לכאו­רה מלשון הזהר הנ\"ל \"דכל מאן דאתגזר ירית ארעא\", שאין המדובר אודות ירושת הארץ לעם ישראל בכלל, שזה נפעל בברית בין הבתרים, אלא בזכותו של כל יחיד ויחיד בחלקו בארץ, שזה נעשה בשעת הכניסה לארץ בפועל.\nאבל אין לפרש כן, שהרי בזהר שם אמר זה בהכתוב המפורש<sup data-n=\"440\">14</sup> \"וגם הקי­מותי את בריתי אתם לתת להם את ארץ כנען\", ד\"כל מאן דאתגזר ירית ארעא\", שנתינת וירושת ארץ ישראל תלוי' והיתה בזכות המילה<sup data-n=\"441\">15</sup>, שנתינת הארץ לכלל ישראל (ולא רק הכניסה לארץ ונתינתה לכל פרט) תלוי' במילה.\nג. ויובן בהקדם מ\"ש אאמו\"ר ב­הערותיו על הזהר שם<sup data-n=\"442\">16</sup>, וז\"ל: \"ואמר ירית כמ\"ש בפסוק<sup data-n=\"443\">17</sup> יירשו ארץ ירושה דוקא שירושה אין לה הפסק<sup data-n=\"444\">18</sup>, כי הרי זהו ע\"י מילה ומילה מאחר שנימול אין לה הפסק כי א\"א שיהי' עוד בלתי נימול ונשאר זה בו לעולם בלי הפסק, לכן כמו\"כ מה שנוטל הארץ הוא בירושה שאין לה הפסק\", וממשיך \"ומה שגלו ישראל מארצם<sup data-n=\"445\">*18</sup>, והרי אין זה ירושה שאין לה הפסק\", ומבאר זה בשני אופנים — (א) \"הנה זהו רק למשך זמן ואח\"כ ישובו\", (ב) \"ועוד זאת כי הרי זהו ע\"י חטאים ועונות שעי\"ז נמשכת הערלה וע\"ד הבא<sup data-n=\"446\">19</sup> על ארמית ערלתו נמשכת ואינו נראה נימול עוד ח\"ו, והיינו מה שמילה ר\"ת מתנה יש לה הפסק\"<sup data-n=\"444\">18</sup>.\nולכאורה צריך ביאור: מפשטות לשו­נו בתירוץ הב' משמע שרק לפי תירוץ זה הגלות הוא בגדר \"הפסק\" (\"מתנה יש לה הפסק\"), משא\"כ לפי התירוץ הא' (ש\"זהו רק למשך זמן ואח\"כ ישובו\") לא מקרי הגלות הפסק, כי כיון שהוא \"רק למשך זמן\" הרי גם בזמן הגלות היא ארצם ובבעלותם, ולא נפסקה מהם ירושת הארץ. אבל לכאורה אם כן, למה מפרש בתירוץ הב' דהוי הפסק והרי גם הגלות הבא בסיבת חטאים ועונות אינו מבטל הבעלות על הארץ, וכמו ש­אומרים \"מפני חטאינו גלינו מארצנו ונתרחקנו מעל אדמתנו\", דגם כשגלו מהארץ \"מפני חטאינו\" הרי היא ארצנו ואדמתנו [ועד דלכמה דיעות<sup data-n=\"448\">20</sup> אפילו מי שאין לו קרקע יכול לכתוב בשטר והקניתי לו ארבע אמות לפי ש\"אין כל אדם מישראל שאין לו ד' אמות בארץ ישראל\"<sup data-n=\"449\">21</sup>], ולמה נקט בתירוץ הב' שזהו מתנה דיש לה הפסק.",[["439","13","וכן יל\"פ בהמשך לשון המדרש שם (המובא לעיל) \"אמר להם מה אתם סבורין שאתם נכנסין לארץ ערלים כך אמר הקב\"ה לאברהם אבינו ונתתי לך ולזרעך אחריך וגו' על מנת ואתה את בריתי תשמור\"."],["440","14","וארא ו, ד."],["441","15","וראה נצוצי אורות לזהר שם אות ה."],["442","16","לקוטי לוי\"צ ח\"ב ע' מז."],["443","17","ישעי' ס, כא."],["444","18","ראה ב\"ב קכט, ב. קלג, א."],["445","*18","ראה גם השאלה בלקו\"ת וסידור שם."],["446","19","עירובין יט, א."],["444","18","ראה ב\"ב קכט, ב. קלג, א."],["448","20","שו\"ת מהר\"ם בר' ברוך סי' תקלו. וראה ס' השטרות לר\"י ברצלוני ע' 43. אוצר הגאונים קידושין תשובות סי' קמו ואילך. ועוד. וראה לקו\"ש ח\"כ ע' 309 הערה 69."],["449","21","ובשו\"ת שם ממשיך: ואם תאמר נטלוה הגוים ואנן בגלות, קיימא לן לרבנן דקרקע אינה נגזלת ובחזקת ישראל היא וארץ ישראל נקראת ע\"ש ישראל כו'."]]],[1301670109,"וע\"כ צ\"ל דתרווייהו איתנהו בה, שיש ב' דרגות ואופנים הן בא\"י הן במצות מילה: א) כפי שהיא באופן ד\"ירושה\" שאין לה הפסק, דמצד זה הפסק לזמן לאו שמי' הפסק. ב) כפי שהיא באופן ד\"מתנה (ש)יש לה הפסק\".\nד. ויש לבאר זה ע\"פ מה שמצינו בנוגע למילה, דנוסף ע\"ז שכ\"א מישראל, גם איש ישראל שאינו יכול לקיים מצות מילה בפועל (\"כגון<sup data-n=\"450\">22</sup> שמתו אחיו מחמת המילה\" וכיו\"ב), נק' \"מהול\"<sup data-n=\"451\">23</sup>, הרי גם בנוגע למושך ערלתו, מצינו בזה חילוקי דינים: הרמב\"ם<sup data-n=\"452\">24</sup> כתב \"וכל המפר ברי­תו של אברהם אבינו והניח ערלתו או משכה<sup data-n=\"453\">25</sup> כו'\", היינו שלדעת הרמב\"ם משיכת הערלה הוי בכלל \"מפר בריתו של אברהם אבינו\", ולאידך איתא בגמ'<sup data-n=\"454\">*25</sup> וכן פסק הרמב\"ם<sup data-n=\"455\">26</sup> \"משוך מותר לאכול בתרומה ואע\"פ שנראה כערל\" (ומה ש­מסיים \"ומד\"ס שימול פעם שני' עד שיראה מהול\", פירשו כמה מפרשי הרמב\"ם<sup data-n=\"456\">27</sup> שהוא רק למצוה ואין זה מעכב אכילת תרומה אפילו מדרבנן<sup data-n=\"457\">28</sup>). ומזה מוכח, שאע\"פ שנראה כערל, אינו ערל ואינו נקרא ערל<sup data-n=\"458\">29</sup>, שלכן מותר לאכול בתרו­מה.\nומהמשך דברי הגמ'<sup data-n=\"459\">30</sup> שמקשה מה­ברייתא שבה נאמר \"את בריתי הפר<sup data-n=\"460\">31</sup> לרבות את המשוך\", ומתרץ שזהו רק \"מדרבנן וקרא אסמכתא בעלמא\", מוכח, דמדאורייתא אינו בכלל \"את בריתי הפר\" [ולפי הנ\"ל בדעת הרמב\"ם שגם מד\"ס אינו ערל ומותר לאכול בתרומה (ומה שצריך למול פעם שני' הוא לפי שנראה כערל) נמצא שגם מד\"ס אינו בגדר ד\"בריתי הפר\"<sup data-n=\"461\">32</sup>]<sup data-n=\"462\">33</sup>.",[["450","22","רש\"י למשנה שבהערה הבאה. וראה נ\"כ הטושו\"ע שבהערה הבאה."],["451","23","משנה נדרים לא, ב. רמב\"ם הל' נדרים פ\"ט הכ\"ב. טושו\"ע יו\"ד סרי\"ז סקמ\"א­ב."],["452","24","הל' מילה פ\"ג ה\"ח."],["453","25","בכס\"מ ציין לאבות פ\"ג מי\"א ושם איתא רק \"המפר בריתו של א\"א\". וראה פיהמ\"ש להרמב\"ם אבות שם (מירושלמי פאה פ\"א ה\"א קרוב לסופה). רע\"ב ורבינו יונה שם."],["454","*25","יבמות עב, א."],["455","26","הל' תרומות פ\"ז ה\"י. וראה הערה 28."],["456","27","רדב\"ז, כס\"מ, משנה למלך (ומסיים: ומה­ירושלמי דפרקין (פ\"ח ה\"א) נראה כגי' האחרת כו'), ועד\"ז במשנה למלך הל' מלכים (פ\"י ה\"ז)."],["457","28","והיינו כגירסת הגמ' שלפנינו דאיתותב ר\"ה (גי' ופי' הא' ברש\"י (ד\"ה קתני) ותוס' (ד\"ה מיתיבי) שם) דס\"ל דבר תורה משוך אוכל בתרומה ומדב­ריהם גזרו עליו מפני שנראה כערל. — ולכמה דיעות (ראה ערוך לנר יבמות שם (ד\"ה תיובתא), מראה הפנים לירושלמי יבמות שם. ועוד), לדעת הרמב\"ם (וראה גם גי' הב' ברש\"י ותוס' שם) אסור לאכול בתרומה עד שימול. ואכ\"מ."],["458","29","כן משמע לפי הצפע\"נ הל' תשובה פ\"ג ה\"ו (ח, ב). הל' תרומות פ\"ב הי\"ב (מג, ג­ד). שו\"ת צפע\"נ נ.י. סרס\"ח — שערל לא מקרי אבל מצות מילה ביטל. ע\"ש (אף דיש לפרש שבהל' תרומות מדבר במשוך לא באופן שעשה להכעיס להפר הברית).\nלכללות דין משוך וחיובו למול שנית (והשקו\"ט בסוגיא דיבמות ובב' הלכות הנ\"ל ברמב\"ם) ראה גם אור זרוע הל' מילה סי' צח. שו\"ת צ\"צ יו\"ד סי' רא (ושם מפרש דמשוך היינו שנדבק<sup data-n=\"e8\">*</sup>). שו\"ת פרי יצחק ח\"א סכ\"ז בארוכה. ובכ\"מ."],["459","30","יבמות שם."],["460","31","פרשתנו יז, יד."],["461","32","אבל ראה שו\"ת פרי יצחק שם. ועוד."],["462","33","וראה צפע\"נ הנ\"ל (ובעוד מקומות — נעתקו כמה מהם בצפע\"נ עה\"ת בא יב, מד (ע' מח ואילך)), מה שמפרש במכילתא (בא שם) \"ומלתה אותו אז יאכל בו להביא את שנתקיימה בו מצות מילה אפילו שעה אחת אפילו שחזר הבשר וחפה העטרה אינו מעכבו לאכול בפסח ולא בתרומה\", ומלשון רש\"י יבמות (ע, ב ד\"ה אדרבה)<sup data-n=\"e9\">*</sup> \"ערלות דגופי' משמל פעם אחת שוב אינה חוזרת עליו\" דמשמע דגם במשוך אינה חוזרת עליו."],["e8","*","ראה ס' אגרות קודש כ\"ק אדמו\"ר שליט\"א חי\"ז ע' רס. המו\"ל."],["e9","*","וראה גם פרש\"י עירובין יט, א ד\"ה ולא (בבועל ארמית) \"דמשכה ערלתו ודומה לו כמי שאינו נימול\"."]]],[1301670110,"ומוכח מכל זה שבברית דמילה יש שני גדרים: \"בריתו של אברהם אבינו\", שבזה אפשרית הפרה ע\"י מעשה האדם, שע\"י פעולתו יפר הברית; \"בריתי\" ד­הקב\"ה, שכיון שנמול פעם אחת שוב אי אפשר להאדם לבטל ולהפר ברית זה, ולכן לא מקרי משוך ערל לענין אכילת תרומה.\nה. והביאור בזה:\nשונה הברית בין הקב\"ה ואברהם מ\"ברית\" בין שני אנשים, שמתקשרים להיות אוהבים זה את זה, משא\"כ בכר\"ב בין הקב\"ה ואברהם (בין בורא לנברא), יש חילוק בין הברית כפי שהיא מצד הקב\"ה והברית כפי שהיא מצד אברהם. ואף שעיקר הברית הוא מצד הקב\"ה, מצד כח הבורא נעשית הברית באופן ד\"ברית עולם\", הרי ישנו בזה גם צד של הנברא, \"ואתה את בריתי תשמור\".\nוהם שני הפרטים הנ\"ל שבברית מי­לה: כמו שהוא מצד הקב\"ה, \"בריתי\", וכמו שהוא מצד אברהם אבינו.\nוהיינו שבענין כריתת הברית והת­קשרות עם הקב\"ה, ישנם שני פרטים, כמו שהוא מצד הנברא ופעולתו, בריתו של א\"א, שבגילוי' של התקשרות זו אפשר שיהי' הפסק, והוא מה ש\"מילה ר\"ת מתנה יש לה הפסק\", ולכן אפשר שמעשה האדם יפגע בזה, דמשוך נקרא \"מפר בריתו של אברהם אבינו\"; וכמו שהוא מצד הבורא, שהיא התקשרות שאי אפשר להיות בה הפסק, כיון שאינו דבר שנעשה מצד הנברא אלא מצד הקב\"ה, שלכן נק' \"בריתי\", ומצד זה גם משוך אינו נק' ערל, כי אין פעולת האדם יכול להפר ברית זו.\nויש לומר, דהגם שבכללות ניתנו שני ענינים אלו בברית דאברהם, הרי ב­פרטיות יותר, זהו החילוק בין הברית כמו שהיא לפני מ\"ת, לכמו שהיא לאחרי מ\"ת שאז נצטוינו \"וביום השמיני ימול\"<sup data-n=\"463\">34</sup>.\nוכמו שמדייק הרמב\"ם<sup data-n=\"464\">35</sup> \"ושים לבך על העיקר הגדול. . שכל מה שאנו מרחיקין או עושים היום אין אנו עושין אלא במצות הקב\"ה ע\"י משה רבינו ע\"ה לא שהקב\"ה אמר זה לנביאים שלפניו. . אין אנו מלין מפני שאברהם אבינו ע\"ה מל עצמו ואנשי ביתו אלא מפני שהקב\"ה צוה אותנו ע\"י משה רבינו שנמול\".\nדהברית כפי שהיא לפני מ\"ת, לפני ביטול ה\"גזירה\" דעליונים לא ירדו ל­תחתונים (כדברי המדרש הידועים<sup data-n=\"465\">36</sup>), הרי היא בעיקר ובגלוי הברית שמצד הנב­רא, מצד אברהם אבינו; ואילו הברית כמו שהיא לאחרי מ\"ת, היא בעיקר כמו שהוא מצד הקב\"ה.\nוע\"ד כללות החילוק בין המצות שלאחרי מ\"ת, לגבי המצוות שקיימו האבות קודם שניתנה תורה, שארז\"ל<sup data-n=\"466\">37</sup> \"כל המצות שעשו לפניך האבות ריחות",[["463","34","תזריע יב, ג. וראה בכ\"ז באו\"א קצת לקו\"ש ח\"ל ע' 55 ואילך. וש\"נ."],["464","35","פיהמ\"ש חולין ספ\"ז."],["465","36","שמו\"ר פי\"ב, ג. תנחומא וארא טו."],["466","37","שהש\"ר פ\"א, ג (א)."]]],[1301670111,"היו, אבל אנו שמן תורק שמך כו'\", שב\"ריח\" ישנם שני ענינים: א) אינו אלא התפשטות הדבר ואינו חלק מעצם הדבר (שלכן ע\"י הריח לא נחסר כלום מ­הדבר), ב) כעבור משך זמן נכלה הריח. ועד\"ז נמשלו המצוות שקיימו האבות ל\"ריח\", כי א) לא הי' בהם כח הבורא כמו במצוות שלאחרי מ\"ת, כי קיומן הי' בכח עצמם, ב) לא הי' בהם הכח לקבוע באופן נצחי קדושת המצות בהדברים הגשמיים שבהם נעשו המצות.\nומזה מובן גם במצות מילה, שאף שהי' ע\"ז ציווי דהיינו (גם) נתינת כח מלמעלה, מ\"מ, כיון שהי' לפני ביטול הגזירה דעליונים לא ירדו לתחתונים, לא הי' בקיומה קודם מ\"ת אותו התוקף של המצוות שלאחרי מ\"ת, שנצטוינו<sup data-n=\"467\">38</sup> ע\"י \"אנכי ה' אלקיך\", אנכי<sup data-n=\"468\">39</sup> מי ש­אנכי<sup data-n=\"469\">40</sup>.\nו. עפ\"ז יש לבאר ב' לשונות שמצינו במדרשים בענין ברית מילה:\nבב\"ר<sup data-n=\"470\">41</sup> איתא \"א\"ר לוי לעת\"ל אב­רהם יושב על פתח גיהנם ואינו מניח אדם מהול מישראל לירד לתוכה ואותן שחטאו יותר מדאי מה עושה להם מעביר את הערלה וכו' ונותנה עליהם ומורידן לגיהנם כו'\", ובשמו\"ר<sup data-n=\"471\">42</sup> איתא \"שאין ישראל המהולים יורדין לגיהנם אמר ר' ברכי' כדי שלא יהיו המינים ורשעי ישראל אומרים הואיל ואנו מהולין אין אנו יורדין לגיהנם מה ה­קב\"ה עושה משלח מלאך ומושך ערלתן והם יורדין לגיהנם שנאמר כו'\".\nויש לעיין בזה: כיון שאאע\"ה \"אינו מניח אדם מהול מישראל לירד לתוכה (לגיהנם)\", ו\"אין ישראלים המהולים יור­דין לגיהנם\", מדוע יורדים אלו \"שחטאו יותר מדאי\" (וכיו\"ב) לגיהנם?\nגם יש להבין החילוק בין שני ה­מדרשים, שבב\"ר איתא שאברהם אבינו עצמו מעביר את הערלה כו' ונותנה עליהם, ובשמו\"ר איתא שמלאך מושך ערלתן כו'<sup data-n=\"472\">43</sup>.\nועכצ\"ל שמעשיהם גרמו להם שיופ­קע מהם שם \"מהול\", אלא שבזה יש שני אופנים. דכאשר \"חטאו יותר מדאי\", פירושו הפרת הברית שלהם עם הקב\"ה, ולכן כלפי אברהם אבינו ובריתו הוא בגדר \"ערל\" שהוא שייך לגיהנם, ולכן אברהם \"מעביר את הערלה כו' ונותנה עליהם\", היינו שמצד \"אברהם\" הם בגדר \"ערלים\". אמנם בשמו\"ר שם קאי כלפי בריתו של הקב\"ה, שמצד זה גם מי שחטא \"יותר מדאי\" לא מקרי מיפר ה­ברית, ולא נעשה ערל ממש, אלא רק \"מינים ורשעי ישראל\" שהם כמומרים ר\"ל, עליהם יש מקום לומר שהם כער­לים [ועוד זאת, מדברי המדרש מובן, שגם הם אינם בגדר \"ערלים\" ממש (שלכן אין המלאך מביא ערלה ועושה אותם לערלים ממש, אלא מושך ערלתן, שע\"פ הלכה אינו בגדר דהפר ברית ממש<sup data-n=\"473\">44</sup>), אלא \"כדי שלא יהיו המינים ורשעי ישראל אומרים הואיל ואנו מהולין אין אנו יורדין לגיהנם\", היינו שאין זה אלא כדי לבטל אמירתן והוראת היתר לאנ­",[["467","38","יתרו כ, ב."],["468","39","דלא אתפס בשם ולא אתרמיז בשום אות וקוצא כו' (לקו\"ת פינחס פ, ב)."],["469","40","ראה בכ\"ז לקו\"ש ח\"ה ע' 88 ואילך. וש\"נ."],["470","41","פמ\"ח, ח."],["471","42","פי\"ט, ד."],["472","43","ראה ביאור השינויים וכו' לקו\"ש ח\"ג ע' 764 בהערה."],["473","44","וראה בהערה בלקו\"ש שם בסופה."]]],[1301670112,"שים הללו להמשיך בהנהגה של מינות ורשעות].\nז. עפ\"ז יש לבאר גם בנוגע לירושת ארץ ישראל:\nארץ ישראל ניתנה לעם ישראל ב­ברית עולם ע\"י הקב\"ה לאברהם אבינו, ופשיטא שאין שייך בזה הפסק באיזה אופן שהוא, שתמיד היא של ישראל, היא בבעלותן.\nאבל כשם שהי' בנתינת הארץ בפועל, שמצינו ג' אופנים בחלוקתה (לשבטים ולמשפחות): ירושה (באופן של נחלה), חלוקה ע\"פ טעם ושכל, וחלוקה ע\"פ הגורל, וכמשנ\"ת במ\"א בארוכה<sup data-n=\"474\">45</sup> שג' ענינים אלו הם ע\"ד ג' הענינים דירושה מכר ומתנה<sup data-n=\"475\">46</sup>, כן הי' גם (מקור) ג' ענינים אלו בנתינתה לאברהם אבינו (לעם ישראל בכלל).\nהחילוק בין ג' ענינים אלו בפשטות הוא, שמכר הוא דבר הניתן ללוקח תמורת תשלום, ובמילא מובן, שהוא בהתאם ולפי ערך תשלום של הלוקח.\nמתנה באה בעיקר מצד הנותן המתנה, בלי תשלום מצד המקבל כבמכר, אבל סו\"ס יש למצב ופעולת המקבל בזה יחס וערך למתנה, דאי לאו דעביד לי' נייחא לנפשי' לא הוי יהיב לי' מתנתא<sup data-n=\"476\">47</sup>.\nמשא\"כ ירושה הוא דבר שאינו תלוי כלל בעבודת היורש או במעמדו ומצבו, דבאיזה מצב שהוא הרי הוא יורש הכל. וי\"ל הטעם, כי ירושה אינה נתינה לשני, אלא כלשון הכתוב<sup data-n=\"477\">48</sup> \"תחת אבותיך יהיו בניך\", שהיורש עומד במקום המוריש, שהוא הוא המוריש, ובמילא יש לו ה­בעלות על נכסי המוריש (ואין בירושה משום שינוי רשות)<sup data-n=\"478\">49</sup>.\nומעין ג' ענינים אלו (ובדקות יותר) הוא גם בארץ ישראל:\n\"ביום ההוא כרת ה' את אברם ברית לאמר לזרעך נתתי את הארץ הזאת\" — הרי ברית זו היתה בקשר עם גזירת ברית בין הבתרים, \"ידוע<sup data-n=\"479\">50</sup> תדע כי גר יהי' זרעך בארץ לא להם ועבדום וענו אותם ארבע מאות שנה וגו' ודור רביעי ישובו הנה\", שזה הי' מעין \"חוב\" שעל בנ\"י לפרוע עבור ירושת הארץ. ובלשון רש\"י בכ\"מ<sup data-n=\"480\">51</sup> \"שטר חוב\" של גזירת כי גר יהי' זרעך המוטל על זרעו של יצחק (ושלכן \"וילך (עשו) אל ארץ מפני יעקב אחיו\"<sup data-n=\"481\">52</sup>, \"אמר אלך לי מכאן אין לי חלק לא במתנה שנתנה לו הארץ הזאת ולא בפרעון השטר\"<sup data-n=\"482\">53</sup>).\nאמנם בברית מילה הוסיף הקב\"ה \"ונתתי לך ולזרעך אחריך את ארץ מגוריך את כל ארץ כנען לאחוזת עולם והייתי להם לאלקים\", שאינו תלוי וקשור עם פעולת ועבודת האדם.\nאלא שבזה גופא שני אופנים — אופן של מתנה ואופן של ירושה, ושניהם",[["474","45","ראה לקו\"ש חי\"ג ע' 114 ואילך (באו\"א). וש\"נ. חכ\"ח ע' 176 ואילך."],["475","46","ראה ע\"ד מתנה וירושה בא\"י — ירושלמי ב\"ב פ\"ח ה\"ב. צפע\"נ עה\"ת פרשתנו טו, ז­ח."],["476","47","ראה גיטין נ, ב. ב\"ב קנו, א. ועוד. וראה לקו\"ש חי\"ג שם הערה 41."],["477","48","תהלים מה, יז. וראה ב\"ב קנט, רע\"א."],["478","49","ראה בכ\"מ בס' צפע\"נ (שו\"ת צפע\"נ דווינסק ח\"א סקי\"ח. שו\"ת ווארשא ח\"ב סקי\"ח. השלמה יג, א)."],["479","50","טו, יג. טז."],["480","51","וישלח לו, ז. חוקת כ, יד."],["481","52","וישלח שם, ו."],["482","53","ל' רש\"י שם, ז."]]],[1301670113,"שייכים למצות מילה, וכמודגש גם בה­כתוב בהפרשה:\nבתחילת הפרשה נאמר \"ואתנה בריתי ביני וביניך\" (שהוא כפרש\"י \"ברית של אהבה וברית הארץ להורישה לך ע\"י מצוה זו\" כנ\"ל) לאחרי שנאמר הציווי (על המילה) \"התהלך לפני והי' תמים\".\nולהלן בפרשה מקדים \"ונתתי לך ולזרעך אחריך את ארץ מגוריך את כל ארץ כנען לאחוזת עולם\" ואח\"כ ממשיך \"ויאמר אלקים אל אברהם ואתה את בריתי תשמור גו' זאת בריתי אשר תשמרו גו' המול לכם כל זכר\".\nויש לומר שבזה נרמזים שני הענינים שבנתינת הארץ, באופן של מתנה ובאופן של ירושה:\nגם הנתינה הראשונה שנאמרה בפר­שת מילה \"להורישה לך ע\"י מצוה זו\", אינה באופן של תנאי וחוב, אלא \"ואתנה בריתי ביני וביניך\", והוא בדוגמת מתנה שבאה בעיקר מצד הנותן, אלא שבאה לו מצד עלייתו של מקבל המתנה למצב נע­לה יותר, עביד לי' נייחא לנפשי', שהוא התוכן דמצות מילה.\nלמעלה מזה הוא מה שנאמר \"ונתתי לך ולזרעך אחריך גו' לאחוזת עולם, והייתי להם לאלקים\", שבדיבור זה דנתינת הארץ \"לאחוזת עולם\" נאמר שהקב\"ה הוא אלקים דבנ\"י, והוא ברית הארץ באופן של ירושה, מבלי תנאים או שייכות למצבם של ישראל, אלא מצד עצם מציאותם שהם כולא חד עם קוב\"ה, אלא שמוסיף בדיבור בפ\"ע, \"ויאמר אלקים אל אברהם ואתה את בריתי תשמור\".\nוהם שני הפרטים שבא\"י, בהתאם לשני הגדרים שבמילה, שמצד בריתו של אברהם אבינו שבמצות מילה, היינו כפי ששייכת עדיין להנברא ומעמדו ומצבו, הרי השייכות לא\"י היא באופן של מתנה, שסו\"ס מעמד ומצב המקבל תופס מקום כאן, ובמילא בשינוי מעמד ומצב דישראל (שאינו במצב דעביד נייחא לנפשי'), אפשר בזה הפסק, היינו שאינו ניכר בגלוי שייכותו לבריתו של אברהם אבינו, ובמילא לא\"י.\nולכן ענין זה נרמז בהר\"ת דהאותיות של מילה \"מתנה יש לה הפסק\", דאותיות מורה על גילוי של הדבר, אות מלשון \"אתא<sup data-n=\"483\">54</sup> בקר\"<sup data-n=\"484\">55</sup>.\nאבל מצד בריתו של הקב\"ה שבמצות מילה, לא שייך בזה שום ביטול או הפסק ח\"ו, מאחר שכל כולו הוא מצד הבורא, ואין תפיסת מקום למעמד ומצב האדם, ולכן זהו קיים תמיד, באיזה מצב שיהודי נמצא, דמאחר שנימול פ\"א ה\"ה בברית עולם עם הקב\"ה, וכ\"ה בנוגע לא\"י, שאין בזה הפסק כלל.\nוזהו שמתרץ אאמו\"ר בתירוץ הא' \"הנה זהו רק למשך זמן ואח\"כ ישובו\", שאין בזה משום הפסק כ\"א אדרבה, זה מבטא ומורה על דבר זה גופא, שגם במצב שחסר בגילוי התקשרות דבנ\"י, ולכן גלו ישראל למשך זמן, לא חסר עי\"ז בבריתם והתקשרותם, ויודעים גם אז שאח\"כ ישובו.\nוכשם שהי' במצרים שבזכות ברית מילה ודם פסח גאלתי אתכם ממצרים<sup data-n=\"485\">56</sup>, כן הוא גם לעתיד ש\"בזכותם אתם עתידין ליגאל בסוף\"<sup data-n=\"486\">57</sup>, \"הקב\"ה גואלם",[["483","54","ישעי' כא, יב."],["484","55","ראה תו\"א מקץ מב, ב. מאמרי אדה\"ז תקס\"ג ח\"א ע' שיא. סידור יז, ד. ובכ\"מ."],["485","56","פדר\"א פכ\"ט. מכילתא ופרש\"י בא יב, ו."],["486","57","פדר\"א שם. וראה רד\"ל שם אות לח."]]],[1301670114,"בזכות המילה\"<sup data-n=\"487\">58</sup>, ובקרוב ממש יבואו<sup data-n=\"488\">59</sup> ישראל שנקראו נחלה לארץ שהיא נחלת עולם לבני ישראל, בביאת משיח צדקנו, בעגלא דידן.\n<span data-k=\"q\">(משיחת ש\"פ וארא תש\"מ)</span>",[["487","58","אגדת בראשית רפי\"ז."],["488","59","ראה מכילתא בשלח טו, יז."]]],[1301670115,"<h3>שיחה ג</h3>\nא. במקור הדין שמילה דוחה את ה­שבת, מצינו (בכללות) ג' לימודים, שנים בש\"ס<sup data-n=\"489\">1</sup> וא' במכילתא<sup data-n=\"490\">2</sup>:\nלדעת ר' נחמן בר יצחק<sup data-n=\"491\">3</sup> נלמד הדבר מגז\"ש: דנין אות ברית ודורות מאות ברית ודורות (בשבת כתיב<sup data-n=\"492\">4</sup> \"כי אות היא\"<sup data-n=\"493\">5</sup>, \"לדורותם ברית עולם\"<sup data-n=\"494\">6</sup>, ובמילה כתיב בפרשתנו<sup data-n=\"495\">7</sup> \"והי' לאות ברית גו'\" \"ובן שמונת ימים ימול לכם כל זכר לדורותיכם\"<sup data-n=\"496\">8</sup>).\nלדעת ר' יוחנן נלמד מהכתוב<sup data-n=\"497\">9</sup> \"ביום השמיני ימול\" — \"ביום<sup data-n=\"498\">10</sup> אפילו בשבת\".\nובמכילתא עה\"פ<sup data-n=\"499\">11</sup> \"ושמרו בני ישר­אל את השבת לעשות את השבת\" איתא: \"רבי אליעזר אומר דבר שהברית כרותה לו ואיזו זו זו מילה\", וכתבו במפרשים<sup data-n=\"500\">12</sup> דכוונת המכילתא להמשך הכתוב \"לדו­רותם ברית עולם\"<sup data-n=\"501\">13</sup>, \"זו מילה שמותר לעשותה בשבת\".\nוהנה לפום ריהטא החילוק בין ג' לימודים אלה הוא: לדעת ר\"א במכילתא הלימוד דמילה מותרת בשבת הוא מ­כתוב שנאמר בפרשת שבת; לדעת ר\"י בגמ' הלימוד הוא מפרשת מילה (בפ' תזריע); ואילו לדעת רנב\"י נלמד הדין מכתוב בפרשתנו (בגז\"ש)<sup data-n=\"502\">14</sup>, בפרשת מילת אברהם אבינו.",[["489","1","שבת קלב, א.\nבגמ' שם יש עוד דיעות — (א) הוא הלכה למשה מסיני, (ב) דעת ר\"א בר יעקב \"אמר קרא שמיני שמיני אפילו בשבת\" (שנכלל בלימוד הב' שבפנים שלמדים מהכתוב דפ' תזריע)."],["490","2","וראה ילפותא דר\"י בתוספתא שהובאה לקמן הערה 18."],["491","3","בנוסחת הכ\"י בדק\"ס הוא הכל מדברי הגמ', דשקו\"ט בביאור דעת רבי אלעזר אתיא אות אות, וליתא שם בעל המאמר רנב\"י. אבל הובא בבה\"ג הל' מילה בתחילתו. ר\"ח שבת שם (ושם \"ונדחו דבריו (דר\"א) ובא ר\"נ בר יצחק ולמדו כו'\"). וכן מוכח בתוד\"ה תניא וברמב\"ן וריטב\"א שם. ועוד."],["492","4","תשא לא, יג."],["493","5","כן הובא בפרש\"י שם ד\"ה אתיא אות אות. ובר\"ח שם הובא בלימוד דר\"נ הכתוב שלאח\"ז (פסוק יז) \"ביני ובין בני ישראל אות היא לעולם\". ואולי נקט רש\"י המוקדם בקרא."],["494","6","תשא שם, טז. הובא בפרש\"י שבת שם ד\"ה אלא אתיא וד\"ה דורות."],["495","7","יז, יא (פרש\"י שם ד\"ה אתיא)."],["496","8","יז, יב — כ\"ה בפרש\"י שם ד\"ה דורות. ובר\"ח שם בלימוד דר\"נ הובא הכתוב שלפנ\"ז (שם, ט) \"ואתה את בריתי תשמור אתה וזרעך אחריך ל­דורותם\". וראה מהרש\"ל בפרש\"י שם."],["497","9","תזריע יב, ג. והברייתא שבגמ' שם \"תניא כוותי' דר\"י. . שמיני ימול אפי' בשבת\" היא בתו\"כ תזריע שם."],["498","10","וכן הובא בשאילתות אחרי (שאילתא צג בתחלתה). בה\"ג הל' מילה (אלא דבהנ\"ל הלימוד מ\"וביום\" — בוא\"ו. וראה גם חידושי הרמב\"ן שבת שם). וכ\"ה בשו\"ע אדה\"ז או\"ח ר\"ס שלא."],["499","11","תשא שם, טז. וכ\"ה ביל\"ש עה\"פ (רמז שצא)."],["500","12","ראה זית רענן (לבעל מג\"א) ליל\"ש שם. וכ\"ה בכמה מפרשי המכילתא."],["501","13","וראה מכילתא מהדורת האראוויץ ועוד — גירסא כזו במכילתא (ויל\"ש)."],["502","14","כ\"ה לפי פשטות הגמ', דמהלימוד \"דנין אות ברית ודורות כו'\" למדין ד\"מילה גופא. . דוחה שבת\". וכן מפורש בבה\"ג שם. ולהעיר מתוד\"ה תניא כוותי' דיש לפרש דדרשת רנב\"י \"אות ברית דורות אתיא למכשירין\", לר\"א דמכשירין דוחין שבת. וראה חידושי הרמב\"ן והריטב\"א שם. ואכ\"מ."]]],[1301670116,"ויש לומר, שמהחילוק במקור הדב­רים נובע גם חילוק בגדר הדין דמילה<sup data-n=\"503\">15</sup> דוחה את השבת<sup data-n=\"504\">16</sup>:\nלהדיעה שנלמד מהכתוב דפ' תזריע (\"ביום השמיני ימול\"), נמצא, דהא דמלין גם בשבת הוא מדיני מילה (ולא מדיני שבת), דאף שכבר נאמרו (וישנם) איסורי שבת, יש דין מיוחד במילה שהיא דוחה שבת. ולפי אופן זה משמע דהא דמילה דוחה שבת הוא בגדר דחוי'<sup data-n=\"505\">17</sup>, או גם הותרה<sup data-n=\"505\">17</sup>, דביחס לקיום מצות מילה בשמונה הותר איסור שבת<sup data-n=\"507\">18</sup>;\nלדעת המכילתא שנלמד מהכתוב ב­פרשת שבת משמע שהוא מדיני שבת<sup data-n=\"508\">19</sup>,",[["503","15","לכאו' יש לומר, דנפק\"מ למעשה בין לימוד הא' (מהגז\"ש ממילת אברהם) ולימוד הב' והג' — לענין פריעה, כיון שלא ניתנה פריעת מילה ל­אברהם (יבמות עא, ב), ולכן, לפי לימוד הא' הנ\"ל אין פריעה דוחה שבת.\nאבל דוחק הוא, כי עכשיו מל ולא פרע כאילו לא מל (משנה שבת קלז, ריש ע\"ב) והרי \"היא מכלל המילה\" (שו\"ע אדה\"ז שם)<sup data-n=\"e10\">*</sup> — ראה בה\"ג הל' מילה שם (ולהעיר מפיה\"מ להרמב\"ם שבת שם). שו\"ת הרמ\"א סע\"ו (\"דפריעה ג\"כ בכלל ימול בשר ערלתו הוא, דמל ולא פרע כאילו לא מל, וא\"כ הכל שרי רחמנא\"). שו\"ת חת\"ס יו\"ד סי' רמט. ולהעיר דאב­רהם עצמו \"פרע מילתן\" כמ\"ש התוס' יבמות שם ד\"ה לא (ובאשכול הל' מילה (סל\"ז) דלגי' אחת בגמ' וכן לדעת הירושלמי (שבת פי\"ט ה\"ב. יבמות פ\"ח ה\"א) ומדרשים \"נתנה לא\"א פריעה\". וראה מאירי שם, דהא שלא ניתנה פריעה לאברהם פירושו מפני שהוא לא הוצרך בה כו', אבל קיימה בישמעאל. ועד\"ז בפרש\"י פרשתנו יז, כה. וראה שו\"ת צ\"צ יו\"ד סר\"ב אות ט). וראה ע\"ד החסידות סידור שער המילה ד\"ה בעת ההיא (קמד, א ואילך). סהמ\"צ להצ\"צ מצות מילה (י, ב). אוה\"ת פרשתנו (כרך ד' תשכט, א). יתרו (ע' תתי ואילך). ואכ\"מ."],["504","16","עפ\"ז יש לבאר הא דבבה\"ג שם כתב \"והלכה כר' יוחנן\", דלכאורה למאי נפק\"מ [והרי כתב שם לפנ\"ז (משבת קלג, א) \"אמר רבי יהודה א\"ר הלכה כר\"ע (וממשיך) ומנין למילה עצמה שדוחה כו'\" — הרי דלכו\"ע מילה דוחה שבת, ולא מכשירין, ופלוגתת ר\"י ושאר אמוראי היא רק בטעם הלימוד<sup data-n=\"e11\">*</sup>] — אלא שמקור הלימוד הוא נפק\"מ להלכה, כבפנים.\nוכן משמע בשאילתות שם \"ואי מתייליד בשבתא שרי למימהלי' בשבתא\", והיינו לפי שיטתו דלמדין מ\"וביום\" הנאמר בפ' תזריע."],["505","17","וכידועה הפלוגתא (והשקו\"ט) בזה ברא­שונים ובפוסקים, ואם צריך למעט בחילול אם אפשר, וכיו\"ב. ואכ\"מ."],["505","17","וכידועה הפלוגתא (והשקו\"ט) בזה ברא­שונים ובפוסקים, ואם צריך למעט בחילול אם אפשר, וכיו\"ב. ואכ\"מ."],["507","18","להעיר גם מדעת רבי יוסי בתוספתא שבת (פט\"ז, יג): מנין לפקוח נפש שדוחה [את השבת] שנאמר את שבתותי תשמרו יכול במילה ועבודה ופקוח נפש ת\"ל אך חלק (ובמכילתא תשא לא, יג (וכן ביומא פה, ב) ליתא בדברי ר\"י מילה ועבודה). ולכאורה יש לפרש שבא ללמד שכולם דוחים שבת. ומזה שנאמר בפרשת שבת ובמיעוט \"אך\", משמע שהוא בגדר הותרה או שהלאו לא נאמר בהם — ראה בהנסמן בהערה 20. אבל בחסדי דוד השלם לתוספתא שם, וכן במנחת בכורים שם, מפרשים גם לגירסא שלנו שלימוד ר\"י הוא רק לענין פקו\"נ שדוחה שבת."],["508","19","ויש לומר, דנפק\"מ גם להלכה, לפי מה שחקר בצפע\"נ (שו\"ת צפע\"נ דווינסק ח\"ב סכ\"ג. צפע\"נ מהד\"ת כו, ב) \"אם מילה דוחה שבת המילה בזמנה או החיוב שצריך למול בזמנה זה דוחה שבת ונ\"מ כגון אשה לפי פסק הרמב\"ם (רפ\"ב דהל' מילה) והרי\"ף. . דאשה כשרה למול אם היא מותרת למול בשבת כיון דעלי' ליכא חיוב למול\":\nללימוד דר\"י מפסוק \"וביום השמיני ימול\" הא דמילה דוחה שבת (או הותרה) הוא מצד חיוב המצוה (הנאמר בכתוב), ולדרשת ר\"א במכילתא הוא מצד עצם החפצא דמילה (והרי לא נאמר כאן חיוב מצוה דמילה אלא הא דהיא ברית לדורותיכם), ולפ\"ז, להלימוד דהמכילתא אשה יכולה למול בשבת. ולהעיר דאשה כמאן דמהילא דמיא (ע\"ז כז, א), ובפרט לפי המבואר לקמן בפנים שנוגע לקדושת שבת, דאשה ישנה לא רק בחיובי ואיסורי שבת אלא גם במצות וקידוש שבת מה\"ת (ברכות כ, ב. רמב\"ם הל' ע\"ז פי\"ב ה\"ג. טושו\"ע (ודאדה\"ז) או\"ח סי' רעא ס\"ב (ס\"ה))."],["e10","*","וראה נמוק\"י ב\"מ ל, א (טז, סע\"א בדפי הרי\"ף). צפע\"נ על הרמב\"ם הל' מילה פ\"א ה\"א."],["e11","*","ובפרט שהגירסא בבה\"ג שונה מהגירסא בגמ' לפנינו: בגמ' \"תניא כוותי' דרבי יוחנן ודלא כר\"א בר יעקב\" (שבב' לימודים אלה שקו\"ט בגמ', ומסיים \"אלא מחוורתא כדרבי יוחנן\"), ואילו בבה\"ג לא הובאה בכלל דעת רב אחא בר יעקב, אלא מביא (תחלה) דרשת ר' יוחנן, ו(אח\"כ) הדרשות דלמדין אות ברית ודורות כו', וע\"ז ממשיך \"תניא כוותי' דר\"י\", כאילו שמהברייתא בא להוכיח כר\"י ולא כר\"נ בן יצחק, וע\"ז מסיים \"והלכה כר' יוחנן\". וראה חי' הרמב\"ן, רשב\"א, ריטב\"א וחי' הר\"ן שם."]]],[1301670117,"ויש לומר, דהיינו לא רק שהוא תנאי באיסורי שבת<sup data-n=\"509\">20</sup>, שמלכתחילה לא נאמרו במקום מילה בזמנה, אלא זהו קיום מצות שבת, \"ושמרו בני ישראל את השבת לעשות את השבת לדורותם ברית עולם\", שמהדרכים \"לעשות את השבת\"<sup data-n=\"510\">21</sup> הוא למול בשבת<sup data-n=\"511\">22</sup>, כי עי\"ז \"שומרים ועושים\" את (קדושת) השבת<sup data-n=\"512\">23</sup>. וכמובן בפשטות, כי שבת הרי (כהמשך הכתוב) \"ביני ובין בני ישראל אות היא לעולם\"<sup data-n=\"513\">24</sup>, וקיום ושלימות האות והברית דשבת היא ב­קיום האות והברית דמילה, שהיא ברית ואות בבשר, כמ\"ש<sup data-n=\"514\">25</sup> בריתי בבשרכם לברית עולם<sup data-n=\"515\">26</sup>.\nאמנם לפי דרשת ר\"נ בר יצחק ש­מקור דין זה הוא מפרשת מילה שנאמרה לאברהם, הרי נמצא, דהא דמלין בשבת הוא מזמן אברהם אבינו<sup data-n=\"516\">27</sup>, לפני שניתנה תורה ולפני שנאמרה כל פרשת שבת. ויש לומר שלפי זה, הוא לא רק דין מ­דיני מילה או דיני שבת, אלא שהוא למעלה ממדידת התורה, ולמעלה מכל גדר השבת<sup data-n=\"517\">28</sup> [וע\"ד לשון רז\"ל<sup data-n=\"518\">29</sup> \"גדולה מילה שנכרתו עלי' שלש עשרה בריתות",[["509","20","ראה באמונות ודיעות להרס\"ג מאמר ג ס\"ט \"והרביעית. . כי הקרבן היתה קודם מצות השבת ולא יתכן שתמנענה מצות השבת ויהי' זה בטול ואסרה שאר המעשים חוץ מן הקרבן והמילה הקודמים לה\". וראה הלשון בדברי הגאונים (לענין עשה דוחה ל\"ת ודברים ש\"בדבור אחד נאמרו\") — ר\"נ גאון לשבת שם קלג, א. תשובות מהר\"ם אלשקר סי' קב מר\"ש ורב האי גאון. הליכות עולם שער ד' קרוב לסופו. וראה תורת האדם להרמב\"ן ענין הכהנים ד\"ה \"תורת כהנים\" בסופו (בהוצאת שעוועל — ס\"ע קלז ואילך)."],["510","21","ראה פי' מרכבת המשנה ומלבי\"ם ל­מכילתא שם."],["511","22","להעיר מהגירסא במכילתא הנ\"ל הערה 13 \"לעשות בשבת\". וראה זח\"ב צב, א. ובציוני פרשתנו (יז, ב) כי סוד השבת בסוד המילה ומצות מילה בזמנה הוא קיום השבת ובשניהם נאמר או\"ת וברי\"ת אם כן המילה היא עצמה שבת. ובמגיד מישרים להב\"י פ' תזריע ד\"ה והלא: וביום השמיני ימול וכו' כלומר כד תסתלק בבינה דאיהי תמינאה מיבעי' לי' למיגזר ערלה כו' ומשום הכי דחי' שבת דתמן איהו שבת הגדול."],["512","23","ועפ\"ז יומתק הקשר וההמשך דדרשה זו להדרשות הסמוכות לה במכילתא: דרשה שלפנ\"ז \"ר\"נ אמר חלל עליו שבת אחת כדי שישמור שבתות הרבה\", ובדרשה שלאח\"ז \"כל המשמר את השבת כאילו עשה השבת\". וראה במפרשי המכילתא."],["513","24","תשא לא, יז."],["514","25","פרשתנו יז, יג."],["515","26","להעיר מרמב\"ן (פרשתנו יז, ט) בטעם דמילה דוחה שבת. ובספר האמונה והבטחון (ב­הוצאת שעוועל — פכ\"א, ע' תכה) כתב הרמב\"ן \"מילה דוחה את השבת מפני שהיא קבועה בגופו של אדם ואין הפסק לקיומה והשבת יש לה הפסק ב­מוצאי שבת\"."],["516","27","ראה מרכבת המשנה שבהערה 21."],["517","28","ראה בארוכה ע\"ד החסידות בלקו\"ת תזריע ד\"ה למנצח על השמינית על מילה שניתנה בשמיני (כ, סע\"ג ואילך). סידור שער המילה בתחלתו (קלט, א). אוה\"ת ויקרא (כרך ב') ע' תקב ואילך. סהמ\"צ להצ\"צ מצות מילה (ט, ב ואילך). ובכ\"מ."],["518","29","משנה נדרים לא, ב (וראה רמב\"ם סוף הל' מילה)."]]],[1301670118,"(משא\"כ על \"כל<sup data-n=\"519\">30</sup> מצות התורה נכרתו עליהן שלש בריתות\")<sup data-n=\"520\">31</sup>. . שדוחה את השבת\"].\nב. ויש לבאר זה בהקדם הידוע, ד­תוכן מצות מילה מדגיש ענין מסירת נפש, וכמו שאמרו רז\"ל עה\"פ<sup data-n=\"521\">32</sup> כי עליך הרגנו כל היום \"וכי אפשר לו לאדם ליהרג בכל יום אלא זו מילה\"<sup data-n=\"522\">33</sup>, וכ­מבואר בארוכה במדרשים דמצות מילה היא כענין הקרבן, ו\"גדול<sup data-n=\"523\">34</sup> כחה יותר מן הקרבן, שהקרבן בממונו והמילה ב­גופו. . ועל כן נחשב לו לעקידה וזבח כאילו עקד את עצמו וכתיב<sup data-n=\"524\">35</sup> כורתי בריתי עלי זבח\", וכן מבואר בכ\"מ בזהר<sup data-n=\"525\">36</sup> דכאשר אדם מישראל מל את בנו ה\"ז כאילו הקריבו.\nוהנה ענין וכח המסירת נפש שישנו בכל ישראל הוא ירושה לנו מאבותינו, כמו שמבאר אדמו\"ר הזקן בספר התניא<sup data-n=\"526\">37</sup>, ובפרט מאברהם אבינו, כידוע<sup data-n=\"527\">38</sup> שאב­רהם \"פתח את הצינור\" למסירת נפש.\nולכאורה צריך ביאור בזה, הרי ענין המסירת נפש שישנו בישראל הוא מה שמוסרים נפשם עבור יחוד וקדושת שמו יתברך, לקיים התורה והמצוות, שניתנה לכאו\"א מישראל במתן תורה, ואיך זה בא בירושה מאברהם שהי' לפני מתן תורה ולפני כללות ענין התורה והמצוות [וכמו שהוא במצות מילה כפשוטה, ש­\"אין<sup data-n=\"528\">39</sup> אנו מלין מפני שאברהם אבינו ע\"ה מל עצמו ואנשי ביתו אלא מפני שהקב\"ה צוה אותנו על ידי משה רבינו שנמול\"].\nוי\"ל הביאור בזה:\nהחידוש שבמ\"ת מבואר במדרש<sup data-n=\"529\">40</sup>, ש­לפני מ\"ת היתה גזירה שעליונים לא ירדו לתחתונים ותחתונים לא יעלו ל­עליונים, ובמ\"ת נתבטלה הגזירה, \"ואני המתחיל\", ש\"וירד<sup data-n=\"530\">41</sup> ה' על הר סיני\", ואח\"כ \"ואל<sup data-n=\"531\">42</sup> משה אמר עלה אל ה'\", ולכן קדושת ישראל ותוקפה שנעשה על ידי התורה ומצוות לאחרי מ\"ת, ה\"ז למעלה לגמרי מכפי שהיתה לפני מ\"ת, לפני ביטול הגזירה.\nאמנם כל הגדרים דעליונים ותחתונים ה\"ה גדרים השייכים לגדרי העולם, אבל בבחי' זו שלמעלה לגמרי מגדר עליון",[["519","30","רמב\"ם שם."],["520","31","ראה תו\"א סוף פרשתנו (אוה\"ת פרשתנו כרך ד' תשכה, א ואילך. ובכ\"מ) בפי' מרז\"ל שב­פנים, גדולה מילה, שהוא בחי' מילה הגדולה שמלמעלה למטה שלמע' מהתורה, דעל התורה נאמר (נצבים ל, יב) לא בשמים היא שנשפלה למטה מבחי' שמים ור\"ת \"מי יעלה לנו השמימה\" (נצבים שם) הוא מילה וס\"ת הוי', שמילה היא למעלה מהתורה ולמעלה מהוי'. ע\"ש."],["521","32","תהלים מד, כג. יל\"ש ואתחנן רמז תתלז."],["522","33","וראה גיטין נז, סע\"ב ובפרש\"י שם \"זימנין דמיית\". וראה שבת (קל, א) כל מצוה שמסרו ישראל עצמן למיתה עליהן בשעת גזירת המלכות כגון עכו\"ם ומילה עדיין היא מוחזקת בידם."],["523","34","לשון רבינו בחיי פרשתנו יז, יג."],["524","35","תהלים נ, ה."],["525","36","זח\"א צג, א. צד, ב ואילך. ח\"ב סו, ריש ע\"ב. ח\"ג מד, א. ועוד. וראה פרקי דר\"א פכ\"ט וברד\"ל שם אות מא."],["526","37","פי\"ח. ושם הוא בביאור זה שהאהבה המסו­תרת שבלב כל ישראל היא ירושה לנו מאבותינו, וע\"ש השייכות לענין האמונה ומסירת נפש. וראה מאמרי אדמו\"ר האמצעי שמות (ח\"ב ע' שמט). \"היום יום\" כא אלול. ג' מרחשון. וראה בהנסמן בהערה הבאה."],["527","38","ראה תניא אגה\"ק סכ\"א. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קל. סה\"מ תרע\"ח ע' רפג. תפר\"ח ע' קב."],["528","39","ל' הרמב\"ם בפיה\"מ ספ\"ז דחולין."],["529","40","שמו\"ר פי\"ב, ג. תנחומא וארא טו."],["530","41","יתרו יט, כ."],["531","42","משפטים כד, א."]]],[1301670119,"ותחתון, לא שייך לומר שלגבי' קיימת גזירה בין עליונים ותחתונים.\nובסגנון תורת החסידות, הרי עצמותו ית' נמצא בעליונים ותחתונים בלי שום חילוק כלל, וכשם שלא שייך לומר בזה חילוק במקום, כך לא שייך חילוק בזמן דקודם מ\"ת ולאחרי מ\"ת. וזה שמבואר במדרש דהחידוש דמ\"ת הוא ביטול ה­גזירה בין עליונים ותחתונים, הוא ביחס ומצד הגדרים ד\"עליונים\" ו\"תחתונים\", שבעליונים ותחתונים גופא ניתן הכח לחברם במ\"ת, על ידי התורה ומצות דבני ישראל.\nועפ\"ז מובן בנוגע לבנ\"י, דזה שבמ\"ת חלה עליהם קדושה מיוחדת, הוא מצד דרגת ה\"גילוי\" של נשמות ישראל, כי מצד עצם הנשמה, זה שעצם הנשמה מיוחדת בו יתברך באופן שהם דבר א' כביכול, לא שייך לחלק בין לפני מ\"ת ולאחר מ\"ת, דכשם שלגבי עצמותו ית' אינו שייך כל גדר הגזירה, כן הוא לגבי העצמות דבנ\"י.\nוהחידוש דמ\"ת הוא בדרגת הגילוי, שענין זה, כמו שהוא לאמיתתו מצד העצם של בנ\"י, יורגש בכחות האדם כפי שהם מלובשים בגוף בעולם הזה.\nג. ועפ\"ז מובן הא דענין המס\"נ של בנ\"י לאחר מ\"ת היא ירושה לנו מאבו­תינו, כי אברהם אבינו (והאבות בכלל) מורה על בחי' העצם דבנ\"י<sup data-n=\"532\">43</sup>, שמצד זה ליתא לכל הגדרים דעליון ותחתון, ומ­בחי' זו בא כח המסירת נפש<sup data-n=\"533\">44</sup>.\nאמנם במ\"ת נתחדש, שבחי' זו דמס\"נ נמשכת גם בגדר הגילויים, דעליונים ותחתונים.\nויש לומר, שהם שני הגדרים בענין המסירת נפש:\nא) מסירת נפש כמו שהיא ע\"פ גדרי התורה שהיא בג'<sup data-n=\"534\">45</sup> העבירות שבהן נצ­טוינו \"יהרג ואל יעבור\";\nב) מסירת נפש בכלל ובכל עניניו שתמיד עומד מוכן למסור נפשו להקב\"ה גם כשאינו מחוייב בזה ע\"פ דין ה­תורה<sup data-n=\"535\">46</sup>, ויתירה מזה, גם כשע\"פ תורה יש בזה שאלות וספיקות האם מותר למסור נפשו<sup data-n=\"536\">47</sup> — שמס\"נ זו היא מצד דרגת ישראל שלמעלה מהתורה<sup data-n=\"537\">48</sup>, וכמ­רז\"ל<sup data-n=\"538\">49</sup> מחשבתן של ישראל קדמה לכל דבר, גם למחשבת התורה.\nוזהו שלדעת ר\"נ בר יצחק למדים מילה בשבת מהכתובים בפ' מילה ד­אברהם, כי מדובר בגדר זה שבמילה<sup data-n=\"539\">50</sup>",[["532","43","ראה לקו\"ש ח\"ל ע' 58 ואילך."],["533","44","ראה סה\"מ תרע\"ח ותפר\"ח שם."],["534","45","או גם בשאר מצוות כשהוא בפרהסיא או בשעת הגזירה — ראה בכ\"ז רמב\"ם הל' יסודי התורה פ\"ה. טושו\"ע יו\"ד סי' קנז."],["535","46","ראה כס\"מ הל' יסוה\"ת שם ה\"ד. טיו\"ד שם בריש הסימן ובנ\"כ. שו\"ע ורמ\"א שם ס\"א. ש\"ך שם סק\"א. ונ\"כ השו\"ע שם."],["536","47","להעיר ממעשה פינחס דארז\"ל (ירושלמי סנהדרין פ\"ט ה\"ז) שהי' \"שלא ברצון חכמים\". וראה לקו\"ש חי\"ח ע' 319 ואילך. וש\"נ."],["537","48","ראה סה\"מ תרנ\"ט ע' יג. סה\"מ תש\"ט ע' 121. וראה הערה שם."],["538","49","ראה ב\"ר פ\"א, ד. תדבא\"ר פי\"ד."],["539","50","ראה בארוכה בהנסמן לעיל הערה 28, ש­בחי' מילה היא מבחי' א\"ק שאין אתעדל\"ת מגעת שם כלל, והארתו מאירה בכל מקום, שלגבי' אצילות ועשי' שווין, וע\"י העברת המונע והמנגד שהיא הערלה ממילא ומעצמו יאיר. וע\"ש שזהו הטעם למילה בשמיני דוקא, בחי' שמיני שלמעלה מכל ס' השתלשלות.\nועפ\"ז מובן הטעם שרק מילה בזמנה דוחה שבת (ולא מילה שלא בזמנה), כי גילוי גדר זה שבמילה (שלמעלה מציוויי התורה) הוא בעיקר במילה בזמנה, שהיא ביום השמיני, ולא במילה שלא בזמנה. ובפרט במילה שלא בזמנה אצל גדול, שהיא קשורה עם \"הסכמתו\" למול א\"ע, היינו לא ענין של מס\"נ של­מעלה מטו\"ד לגמרי, אלא התערבות של מציאותו, טו\"ד ורגש כו' — ראה בארוכה לקו\"ש ח\"א ס\"ע 19 ואילך. חכ\"ה ע' 88 ואילך."]]],[1301670120,"שלמעלה מציוויי התורה, שמצד זה ישנו בכל יהודי הטבע למסור נפשו על יחוד שמו ית', גם כשאינו מחוייב בזה ע\"פ תורה [וזה שייך גם לענין המילה כ­פשוטה, כדאיתא בספרים<sup data-n=\"540\">51</sup> דענין המילה הוא \"לצרף. . את ישראל. . וצירוף זה היינו בחינה ונסיון אם ימסור נפשו על קדושת שמו ית' וכשירגיל עצמו מנעוריו באחד מאבריו יהי' נקל בעיניו גם כי יזקין למסור כל נפשו לשמים\"]<sup data-n=\"541\">52</sup>.\nד. והנה מכיון שגדר זה שבמילה, גדר המס\"נ שלמעלה מהתורה, נלמד מזה שמילה דוחה שבת, צריך לומר, שיש לזה ביטוי גם בגוף מעשה מצות המילה ביום השבת.\nויש לומר, שדבר זה נראה בזה גופא שאיש ישראל מל קטן מישראל ביום השבת:\nאף שמדובר במוהל אומן וה\"ז חשש רחוק שיקלקל במילה, הרי אפשר שלא יגמור המילה כדבעי, ונמצא מחלל שבת, כדמשמע בגמ'<sup data-n=\"542\">53</sup> שזה יתכן גם באומן<sup data-n=\"543\">54</sup>. זאת ועוד, דגם כשמל כדבעי, למה צריך הוא להכניס את עצמו בזה ולעשות פעולה דחילול שבת<sup data-n=\"543\">54</sup>. בשלמא האב ה\"ז מצוה דידי' למול את בנו<sup data-n=\"545\">55</sup> ביום השמיני, אבל אחר שאי\"ז מצותי'<sup data-n=\"546\">56</sup>, ומל במקום האב<sup data-n=\"547\">57</sup>, למה לו לעשות פעולה היפך משמירה שלו דשבת<sup data-n=\"548\">58</sup>?\nאלא, לפי שגדר ענין המילה בשבת ענינה גילוי העצם דישראל שלמעלה מהתורה, ולכן ה\"ז מודגש גם בפעולת המילה, שהמוהל מוכן למסור נפשו ברוחניות, לעשות מעשה דחילול שבת למול את התינוק.\nומוהל שאינו מוכן למסור נפשו ו­למול בשבת, אינו יכול למול גם בחול, כי הרי ע\"י המילה נעשית תחילת כניסת נפש זו הקדושה<sup data-n=\"549\">59</sup>, והיינו התקשרות עצמית זו דישראל בקוב\"ה שלמעלה מהתורה, ודבר זה אפשרי אם תכונה זו נראית במוהל הבא למול את התינוק להכניסו בבריתו של אברהם אבינו ע\"ה.",[["540","51","עוללות אפרים ח\"ג ע' יט מאמר תסט."],["541","52","ראה אוה\"ת שבועות (ע' קיח ואילך) ב­כריתות ברית דאברהם. וראה שם ע' קיט: \"וזהו ענין גילוי העטרה שהוא בחי' יו\"ד דחכמה עילאה כו' ובכל נפש מישראל מתגלה בפנימי' חכמה שבנפשו גילוי אא\"ס שבפנימי' חכמה עילאה ממש, ועי\"ז יכול למסור נפשו על קדושת השם כידוע\"."],["542","53","שבת קלג, ב: ואם לא הילקט ענוש כרת. מני א\"ר כהנא אומן כו'."],["543","54","ראה שו\"ע יו\"ד סו\"ס רסו ובנ\"כ שם ה­שקו\"ט כאשר לא גמר המילה ולענין ב' מוהלין."],["543","54","ראה שו\"ע יו\"ד סו\"ס רסו ובנ\"כ שם ה­שקו\"ט כאשר לא גמר המילה ולענין ב' מוהלין."],["545","55","ראה לשון אדה\"ז בשו\"ע או\"ח סשל\"א סי\"ג."],["546","56","ראה רש\"י יבמות עא, ב ד\"ה חבושין. ו­להעיר משו\"ע אדה\"ז או\"ח סתל\"ב קו\"א סק\"ב."],["547","57","להעיר מש\"ך חו\"מ סי' שפב סק\"ד דלדעת הרא\"ש (חולין פ' כיסוי הדם ס\"ח) לא מהני שליחות במילה — ראה קצוה\"ח חו\"מ שם סק\"ב."],["548","58","בטור יו\"ד סרס\"ו מביא מר\"א הלוי, ד\"אם האב יודע למול אין לו למול בשבת אם יש אחר שיודע למול דהא מילה הוא פסיק רישא גבי דידי' דהוא מכוין לתקן את בנו אבל לגבי אחר לא מקרי תיקון ושרי\". אבל ראה תרומת הדשן סרס\"ה (הובא בב\"י ובב\"ח שם) דאין חילוק בזה<sup data-n=\"e12\">*</sup>. וראה שאגת ארי' סנ\"ט, ושם דגם לר\"א הלוי גם ע\"י אחר איכא חילול."],["549","59","שו\"ע אדה\"ז או\"ח מהד\"ת סוס\"ד."],["e12","*","ולכאורה כ\"ה לפי פסק השו\"ע (וראה רמ\"א) שם ס\"ז. שו\"ע אדה\"ז שבהערה 55."]]],[1301670121,"ה. ויש לומר, דענין זה, שממילת אברהם בא ונמשך לישראל ענין זה שבמילה שהיא למעלה מגדרי התורה, נראה גם בעצם מילת אברהם:\nאיתא בפרקי דר\"א<sup data-n=\"550\">60</sup> דמילת אברהם היתה ביום הכפורים<sup data-n=\"551\">61</sup>. ולכאורה צ\"ב, דכיון שקיים אברהם אבינו כל התורה כולה עד שלא ניתנה<sup data-n=\"552\">62</sup> איך מל א\"ע ביוהכ\"פ, והרי מילה שלא בזמנה אינה דוחה את השבת ולא את היו\"ט<sup data-n=\"553\">63</sup>?\nוהנה ע\"פ פשט לא קשה, דכיון שאז נצטווה על המילה, ד\"בו ביום שציוהו מל\"<sup data-n=\"554\">64</sup>, ה\"ז מילה בזמנה שדוחה שבת ויו\"ט. אבל ע\"פ פנימיות הענינים יש לומר, דלהיות שמילת אברהם היתה בבחינה זו שלמעלה מגדרי התורה, לכן גם מילתו בפועל היתה באופן שקיום המצוה דחה שבת וגם שבת שבתון דיום הכפורים.\nוע\"פ הנ\"ל — דהא דלמדים מפרשת מילה דאברהם דמילה דוחה שבת, שייך להתקשרות עצמית דישראל בקוב\"ה ו­ענין המסירת נפש שלמעלה מהתורה — יומתק ביותר הא דמילת אברהם היתה ביום הכפורים דוקא<sup data-n=\"555\">65</sup>, כי זה שייך לה­כפרה דיוהכ\"פ, וכדאיתא בפרקי דר\"א שם (בהמשך להלימוד דביום הכפורים נמול אברהם, \"אתיא עצם עצם מיום הכפורים\") \"וכל שנה ושנה הקב\"ה רואה דם הברית של מילה של אברהם אבינו ומכפר על כל עונותינו שנאמר<sup data-n=\"556\">66</sup> כי ב­יום הזה יכפר עליכם לטהר אתכם וגו'\", כי אמיתית כפרת יום הכפורים היא מה שעיצומו של יום מכפר<sup data-n=\"557\">67</sup>, וענינה הוא גילוי ההתקשרות העצמית של ישראל בקוב\"ה שלמעלה מכל גדר פגם (ול­מעלה מהתורה), ובבחינה זו לא מגיע מעיקרא כל ענין החטאים ועוונות, ולכן כאשר מתגלית בחינה זו בישראל מתכפרים ממילא כל הפגמים, כמבואר במ\"א בארוכה<sup data-n=\"558\">68</sup>.\nו. וזהו שהג' לימודים הנ\"ל מבטאים ג' ענינים שישנם במילה:\nא) מה שהיא א' מתרי\"ג מצות התורה, אלא שבזה גופא ה\"ה גדולה<sup data-n=\"559\">69</sup> מהם ולכן היא דוחה את המצות דשבת.\nב) מה שהיא מצוה כללית, שהיא שקולה כנגד כל המצות<sup data-n=\"560\">70</sup>, ולכן קיומה הוא גם בשבת, כי זה פועל שלימות בהאות של הקב\"ה בישראל, ביני ובין",[["550","60","פכ\"ט, הובא בתוד\"ה אלא (ר\"ה יא, א)."],["551","61","ובתוס' שם עוד דיעה, שהי' בט\"ו ניסן יו\"ט דפסח."],["552","62","ראה יומא כח, ב. משנה סוף קידושין. פרש\"י תולדות כו, ה (מב\"ר פס\"ד, ד. וש\"נ)."],["553","63","שבת קלב, ב. קלג, א. רמב\"ם הל' מילה פ\"א ה\"ט. טושו\"ע יו\"ד ר\"ס רסו."],["554","64","ל' התוס' ר\"ה שם בסופו. פרש\"י פרשתנו יז, כג."],["555","65","ראה אוה\"ת פרשתנו (כרך ד) תשל, ב."],["556","66","אחרי טז, ל."],["557","67","ראה שבועות יג, א ואילך — דעת רבי. וראה רמב\"ם הל' תשובה פ\"א ה\"ג (דאף שפסק כרבנן דיוהכ\"פ מכפר רק על השבים, כ' הלשון) \"ועצמו של יוהכ\"פ מכפר לשבים (שנאמר כי ביום הזה יכפר עליכם)\". וראה בהנסמן בהערה הבאה, שלכו\"ע עיקר הכפרה דיוהכ\"פ הוא מה שעיצומו של יום מכפר, אלא שלדעת רבנן, בכדי להגיע לכפרה זו צריך לתשובה. ואכ\"מ."],["558","68","ראה לקו\"ש ח\"ד ע' 1150 ואילך. ועוד."],["559","69","כבמשנה נדרים לא, ב: גדולה מילה ש­דוחה את השבת החמורה."],["560","70","גי' הע\"י בש\"ס בסיום המשנה נדרים שם. וכ\"ה גי' הר\"ן והתוס' (והובא עה\"ג בש\"ס שם). ובשל\"ה חלק תושב\"כ פרשתנו (רעט, ב) בהגהה: מילה שקולה נגד כל התורה וכן ברית מילה עולה תרי\"ג כי ברית תרי\"ב ובתוספת מצות מילה תרי\"ג."]]],[1301670122,"בני ישראל אות היא לעולם, בריתי בבשרכם לברית עולם<sup data-n=\"561\">71</sup>.\nג) זה שהיא למעלה מהמדידה והג­בלה דתורה ומצות, השייכת לברית והת­קשרות עצמית דבנ\"י בקוב\"ה, וקשר זה מתבטא במילת אברהם עצמו, \"בעצם היום הזה נימול אברהם\"<sup data-n=\"562\">72</sup>, שנמול ביום הכפורים, שבת שבתון.\n<span data-k=\"q\">(משיחות ליל שמח\"ת תיש\"א; ש\"פ נשא תשמ\"א)</span>",[["561","71","בסגנון אחר — שהוא שייך לקדושת ישראל שהם העושים את השבת, \"לעשות את השבת\" (ראה ד\"ה את שבתותי תשמרו ה'ש\"ת)."],["562","72","פרשתנו יז, כו. וראה תו\"א סוף פרשתנו."]]],[1301670123,"<h3>שיחה א</h3>\nא. בחיוב דחינוך הקטנים, איתא בכ\"מ ד\"חינוך מדרבנן\"<sup data-n=\"563\">1</sup>, אבל מן התורה ליכא חיוב חינוך — ודרוש ביאור:\nכיון שמן התורה ברגע שהקטן נעשה גדול חייב מיד בקיום כל מצוות התורה, א\"כ באם אין חיוב מן התורה להכינו לזמן גדלותו, יעבור על מצות התורה מחמת חסרון ידיעה וחוסר הכנה?\nבפשטות יש לומר, שזה נכלל במצוה הכללית דתלמוד תורה, \"מצות עשה מן התורה על האב ללמד את בנו הקטן תורה. . שנאמר<sup data-n=\"564\">2</sup> ולמדתם אותם את בניכם לדבר בם\"<sup data-n=\"565\">3</sup>, וכמו שפי' הרמב\"ן בפסוק<sup data-n=\"566\">4</sup> \"ושננתם לבניך\", \"מאחר שציוה במצות חוקת עולם לדורותיכם<sup data-n=\"567\">5</sup>. . הנה אנחנו מצווים שידעו בנינו המצוות<sup data-n=\"568\">6</sup>, ואיך ידעו אותם אם לא נלמדם\"<sup data-n=\"569\">7</sup>. ולפ\"ז ישנו מן התורה חיוב של חינוך בתור הכנה לקיום המצות בגדלותו, ואדרבה, זהו יסוד ה­מצוה הכללית דת\"ת לבנים, כנ\"ל.\nאלא שמן התורה המצוה היא \"שידעו בנינו המצות\", ואתו רבנן ותיקנו שגם מצוה לחנך את הבן בקיום המצות, וכמ\"ש ראשונים, שהוא כדי \"להרגיל את הקטן למצוה. . כדי שיהא מחונך ורגיל ל­מצוות\"<sup data-n=\"570\">8</sup>, \"להנהיגו שיהא סרוך אחר מנהגו לכשיגדיל\"<sup data-n=\"571\">9</sup>, כענין שנאמר<sup data-n=\"572\">10</sup> \"חנוך לנער על פי דרכו גם כי יזקין לא יסור ממנה\"<sup data-n=\"573\">11</sup>.\nאבל לכאורה אין זה מספיק<sup data-n=\"574\">12</sup>: כיון",[["563","1","נזיר כט, א. חגיגה ד, א. וש\"נ. ובכ\"מ. וראה ברמב\"ם בכ\"מ לענין מצות פרטיות: הל' ציצית פ\"ג ה\"ט. הל' ברכות פ\"ה ה\"א. הל' שביתת עשור פ\"ב ה\"י. הל' סוכה פ\"ו ה\"א. ועוד. וראה אנציקלופדי' תלמודית ערך חנוך בתחלתו. וש\"נ."],["564","2","עקב יא, יט."],["565","3","הל' ת\"ת (להרמב\"ם ו)לאדה\"ז בתחלתן."],["566","4","ואתחנן ו, ז."],["567","5","ויקרא ג, יז. וראה גם תשא (לא, יז), לך (יז, י) — הובא ברמב\"ן שם."],["568","6","וראה בה\"ג בהקדמתו — מנין המצוות (קום עשה עא) \"למד בנך תורה ומצות\", וכ\"ה בסמ\"ג (מ\"ע יב וברמזי המצות בראש הספר) וביראים (הש­לם סי' רכה)."],["569","7","ובפי' רבינו מיוחס עה\"ת (ירושלים תשכ\"ח) עקב יא, יט: ולמדתם אותם. תרגילו את בניכם להיות עסוקים תמיד בתורה. . כדי שירגיל בכך ואף בכל המצוות, וכן שלמה אומר חנוך לנער כו'<sup data-n=\"e13\">*</sup> [וברמב\"ן עקב שם, יח: הוסיף בכאן ולמדתם אותם כי ושננתם שיספר להם המצות וכאן עד שילמדו אותם וידעום ויבינו אותם וטעמיהם]. ובמאירי (קידושין ל, א) \"האב חייב בלימוד תורת הבן. . עד שידע ענין המצוות ויקיים אותם כראוי\". ובבמדב\"ר פי\"ז, א (וראה תנחומא שלח יד ובעץ יוסף שם) \"שנו רבותינו ה' דברים האב חייב לעשות לבן כו' ללמדו תורה כו' ללמדו מצות כו'\" (וראה מפרשים שם)."],["570","8","רש\"י סוכה ב, סע\"ב ד\"ה מדרבנן."],["571","9","רש\"י חגיגה ו, א ד\"ה קטן."],["572","10","משלי כב, ו."],["573","11","וכן ברשב\"א (מגילה יט, ב) ובריטב\"א (סוכה שם) הזכירו הכתוב ד\"חנוך לנער\" לענין חובת חינוך דרבנן. אבל בגמ' קידושין ל, רע\"א מבואר דקאי בבן גדול, וכמ\"ש אדמו\"ר הזקן בהל' ת\"ת פ\"א ס\"ו. ובפשטות זהו הטעם שלא הביאו אדה\"ז בשו\"ע הל' שבת סשמ\"ג לענין חובת חינוך. וצע\"ק בלשונו בשו\"ת (סי' מא — נדפס בסוף השו\"ע, וכן בספר בפ\"ע) \"דהתם (בחגיגה) מיירי במ\"ע המוטלת על האב לחנך בה בנו כדי שיקיים מעצמו כשיגדיל שזו היא מצות חינוך כדכתיב חנוך לנער כו'\"."],["574","12","נוסף ע\"ז שלא מצינו כן דעת רוב ה­ראשונים והפוסקים שמצות ת\"ת היא כעין חינוך שידע המצות וכו', כ\"א שמצות ת\"ת היא א' ממצות הבן המוטלת על האב לעשות לבנו, שבנו ילמד\nתורה, וע\"ד מצות מילה ופדיון הבן, כפשטות הסוגיא בקידושין (כט, א)."],["e13","*","להעיר גם מלשון אדה\"ז בקו\"א בהל' ת\"ת (פ\"א סק\"א [תתכח, א]) \"חינוך לתורה דאורייתא על האב\"."]]],[1301670124,"שידיעת המצות עצמה אינה די' שיקיימן בפועל כשיגדיל, וכדמוכח מזה גופא שחכמים חייבו לחנכו בקיום המצות ב­פועל שיתרגל בהן, הרי, שמן התורה, כשיגדל הקטן ויגיע לגיל י\"ג שנה ויום אחד, חסר בהכנתו והכשרתו השלימה כדי שיוכל לקיים בפועל כל המצוות כדבעי כשיגדל. דאם נתרגל הקטן להתנהג ללא שמירת התורה והמצוות, הרי גם אם יודע (בשכלו ומחשבתו) הלכות כל המצוות, אי אפשר שבן רגע יתחיל לקיימן כולן בפו­על כדבעי (היפך טבעו ומנהגו הקודם).\nב. לכאורה יש לומר, שאכן ישנה חובת חינוך<sup data-n=\"575\">13</sup> מדאורייתא<sup data-n=\"576\">14</sup> [ולא רק ב­ידיעת המצות] — ובהקדם:\nכשהתורה מחייבת לקיים איזו מצוה, ולדוגמא הנחת תפלין, פשוט שאין החיוב רק למי שיש לפניו זוג תפלין שמחוייב להניחן, אלא המצוה מחייבתו לעשות כל הדרוש כדי להשיג תפלין, ואם לא הש­תדל ומשו\"ז לא הניחן ביטל מ\"ע. ועד\"ז בכמה מצוות, שמחוייב מה\"ת לעשות כל הדרוש כדי שיוכל לקיים המצוה, ובל' הרמב\"ם<sup data-n=\"577\">15</sup> \"יש מצות עשה שאדם חייב להשתדל ולרדוף עד שיעשה אותה כגון תפלין וסוכה ולולב ושופר\". ואף שגוף החיוב אינו אלא פעולה מסויימת כהנחת תפלין ונטילת לולב מ\"מ חיוב זה עצמו מחייבו בכל ההכנות הדרושות כדי שיוכל לקיים (פעולת) המצוה. ועוד זאת, שאם לא השתדל ללמוד ולידע איך לקיים המצוה, ולכן לא קיימה כהלכתה, הרי גם זה חשוב מבטל מ\"ע.\nוא\"כ, בקטן שנעשה גדול, שאז מתחייב מיד מדאורייתא בקיום כל התורה כולה, הרי כיון שא\"א שיקיים כל המוטל עליו בלי הכנה קודמת, הן לימוד וידיעת ה­מצות, והן הכנתו והכשרתו שיתרגל לקיי­מם בפועל (שזהו ע\"ד ההשתדלות להשיג תפילין או לולב וכיו\"ב), א\"כ הכנה זו היא ג\"כ, לכאורה, חובה מה\"ת<sup data-n=\"578\">16</sup>. ומאחר שישנו חיוב על הקטן להכין עצמו לגדלותו אלא שקטן אינו בר­חיובא, לכן יש מקום לומר שחיוב זה עובר אל האב [וע\"ד מ\"ש הריב\"ש<sup data-n=\"579\">17</sup> לגבי פדיון הבן, ש\"עיקר ה­מצוה בעצמו אלא שבקטנותו אי אפשר\"<sup data-n=\"580\">18</sup>, ולכן הוטל על האב].\nאלא שאעפ\"כ אין חובה זו בגדר מצוה, כי אם רק הכשר והכנה בלבד, ע\"ד וב­דוגמת כריתת עצים לעשות פחמים לע­שות ברזל (איזמל למילה)<sup data-n=\"581\">19</sup>. וזהו שנתוסף במצות חינוך שמד\"ס, שיש בזה גדר חיוב",[["575","13","להעיר שיש אחרונים (נסמן באנציקלופדי' תלמודית שם ע' קסב) דס\"ל שמהפסוק \"חנוך לנער גו'\" יש להוכיח שחיוב החינוך הוא מצות עשה מדברי קבלה. וי\"א (נסמן שם) שמקורו בתורה — כמ\"ש (פרשתנו יח, יט) \"כי ידעתיו למען אשר יצוה את בניו גו' ושמרו דרך ה' גו'\"."],["576","14","ולהעיר ממ\"ש הרמב\"ן גבי מצות הקהל (וילך לא, יג) \"ובניהם אשר לא ידעו ישמעו ולמדו. הם הטף כי ישמעו וישאלו והאבות ירגילום ויחנכו אותם, כי אין הטף הזה יונקי שדים אבל הם קטני השנים הקרובים להתחנך כו'\", אלא שסיים \"אבל רבותינו אמרו (חגיגה ג, א) האנשים ללמוד. . והטף למה בא ליתן שכר למביאיהם\", והיינו דמזה מוכח דאינו משום חינוך. וראה מהרש\"א חגיגה שם ד\"ה נשים. ובארוכה לקו\"ש חי\"ט ע' 364 ואילך."],["577","15","הל' ברכות פי\"א ה\"ב."],["578","16","ראה לקו\"ש חי\"ז ע' 70. חכ\"ו ע' 75 ואילך. וש\"נ."],["579","17","בתשובותיו סקל\"א."],["580","18","ובאו\"ז ח\"ב סי' קד משמע דכן הוא נמי לענין מילה. אבל ראה שו\"ת הר\"ן סי' נב. וראה בארוכה לקו\"ש חי\"א ע' 44 ואילך ובהערות שם. וש\"נ."],["581","19","שבת קל, א (ובפרש\"י ד\"ה לעשות) וש\"נ — שלדעת ר\"א כ\"ז בגדר מכשירי מצוה שדוחין את השבת."]]],[1301670125,"המצוה. ויש לומר, שמצד החיוב מן התורה אין עשיית הקטן עצמה בגדר קיום מצוה, כ\"א עשי' כדי שיתרגל, ואילו מדרבנן עשיית הקטן היא בגדר מצוה, ולכן מן התורה קיום המצוה שעושה הקטן אינו צריך להיות בכל הפרטים, בהכשר גמור, כי מצד ההכנה אין נפק\"מ כ\"כ אופן עשייתו, משא\"כ מצד מצות חינוך דרבנן צריך שהקטן יקיים המצות בכל הפרטים כגדול<sup data-n=\"582\">20</sup>.\nג. ואת\"ל מצינו כעין זה בפירוש רבי­נו מנוח במ\"ש הרמב\"ם בהל' שביתת עשור<sup data-n=\"583\">21</sup>, \"קטן בן תשע שנים ובן עשר שנים מחנכין אותן לשעות כיצד הי' רגיל לאכול בשתי שעות ביום מאכילין אותו בשלש הי' רגיל בשלש מאכילין אותו בארבע לפי כח הבן מוסיפין לענות אותו בשעות בן אחת עשרה שנה בין זכר בין נקבה מתענה ומשלים מדברי סופרים כדי לחנכו במצות\".\nוכתב ע\"ז רבינו מנוח: \"ומה שכתב הרב כאן כדי לחנכו במצות ולעיל נמי כתוב מחנכין אותו לשעות בא להודיענו דתרי חנוכי הוו כדאמרינן בגמרא<sup data-n=\"584\">22</sup> אמר רבה תרי חנוכי הוו חד לעינוי וחד להשלמה, וחנוך השעות אינו חובה מדרבנן אלא חובה המוטלת על כל אדם מעצמו ללמד ולהרגיל בניו ללכת בדרכי יושר כדכתיב חנוך לנער על פי דרכו וגומר וכדי להכניסם תחת כנפי השכינה. . אבל בחינוך שני דהיינו כשהם בני י\"א שנה שחייבין להשלים מדרבנן שוין בו תינוק ותינוקת. . וז\"ש הרב כאן מתענה ומשלים מדברי סופרים ולמעלה כתב מחנכין אותו ולא כתב מחנכין אותו לשעות מד\"ס לפי שאין חנוך שעות מדרבנן כלל שאין מדרבנן חיוב חנוך בלא השלמה כלומר שיעשה המצוה כתקנה וכמשפטה בשל­מות\", עכ\"ל.\nומדבריו נראה דישנו חיוב כללי (ד­ילפינן מקרא ד\"חנוך לנער\") לחנך בניו שילכו בדרך התורה והמצוות<sup data-n=\"585\">23</sup>, וחיוב זה מאחר שאינו אלא להרגילם במצוות אינו מחייב שיתקיימו המצוות כתקונן וכהל­כתן. ונוסף על זה חייבו חכמים שהקטן יעשה כל מצוה ומצוה כמשפטה ובכל פרטי' כעשיית הגדול.",[["582","20","כמו שהוכיח הריטב\"א (סוכה ב, ב) מהא דמבואר שם בגמ' דאין לחנך קטן בסוכה פסולה (למעלה מעשרים). וכ\"כ הר\"ן ליומא פב, א. וראה לקמן בפנים מרבינו מנוח."],["583","21","פ\"ב ה\"י."],["584","22","יומא פב, א."],["585","23","ע\"פ דבריו יש לבאר לכאו' דברי הרמב\"ם בהל' מאכא\"ס פי\"ז הכ\"ז: קטן שאכל אחד ממאכלות אסורות או שעשה מלאכה בשבת אין בית דין מצווין עליו להפרישו לפי שאינו בן דעת כו'. ובהל' כח: אע\"פ שאין בית דין מצווין להפריש את הקטן, מצוה על אביו לגעור בו ולהפרישו כדי לחנכו בקדושה שנא' חנוך לנער על פי דרכו וגו'. [ועד\"ז כתב בהל' אבל פ\"ג הי\"ב: כהן קטן הרי הגדולים מוזהרים שלא יטמאוהו. ואם בא להטמא מעצמו אין בית דין מצווין עליו להפרישו, אבל אביו צריך לחנכו בקדושה] —\nדלכאורה: דין חובת חינוך במצוות מובא ב­רמב\"ם כמה פעמים לפנ\"ז לענין כו\"כ מצות (כנ\"ל הערה 1), ואינו מביא שם הכתוב ד\"חנוך לנער\", ואמאי הביאו דוקא כאן. גם מהו הל' \"לחנכו בקדושה\", ולא כמ\"ש לפנ\"ז כמה פעמים \"לחנכן במצות\".\nוי\"ל דס\"ל להרמב\"ם דהחובה להפרישו מ­איסורא באה מהחיוב הכללי לחנכו בדרך התורה מקרא ד\"חנוך לנער\"<sup data-n=\"e14\">*</sup> ואין זה חינוך פרטי בכל האיסורים (כדרך שתיקנו חכמים חיוב פרטי בכל מ\"ע) כ\"א חיוב כללי לחנכו בקדושה. וראה בהערה שלאחרי הערה הבאה הדיעה דחינוך במל\"ת הוא דאורייתא."],["e14","*","שהוא מדברי קבלה (ראה לעיל הערה 13), ויותר מחיוב חינוך סתם שהוא מד\"ס. או יתרה מזה, דהוי מדאורייתא והכתוב גילוי מילתא בעלמא, כדלקמן בפנים."]]],[1301670126,"ויש לומר, שמ\"ש רבינו מנוח שם ד\"חינוך השעות אינו חובה מדרבנן אלא חובה המוטלת על כל אדם מעצמו כו'\", ר\"ל דהאחריות של האב לחנך בנו (באופן כללי) מוכחת מסברא, והאדם מחוייב בה מעצמו מבלי שיהי' ע\"ז ציווי וחיוב מפורש.\nכלומר: מכיון שמן התורה מחוייב כל אחד מעת שהגיע לגיל י\"ג שנה ויום א' לקיים כל התורה והמצות, הרי מובן ופשוט שכל איש ישראל יחנך וירגיל את בניו \"ללכת בדרכי יושר\", דרך התורה והמצוה, כשם שפשוט שכל אדם ישר הולך מדריך ומחנך את בניו בדרך הטוב והישר מבלי שיהי' לו ציווי ע\"ז, כי זהו טבעו של אב, ובלשון הכתוב<sup data-n=\"586\">24</sup> גבי אבר­הם \"יצוה את בניו ואת ביתו אחריו לעשות צדקה ומשפט\".\nועפ\"ז י\"ל שיש בזה גדר דאורייתא<sup data-n=\"587\">25</sup>, וכמבואר בכ\"מ בש\"ס דדבר המוכח מס­ברא הוא מה\"ת<sup data-n=\"588\">26</sup> [והכתוב בדברי קבלה \"חנוך לנער וגו'\" הוא גילוי מילתא ב­עלמא].\nד. אולם לכאורה חידוש גדול הוא לומר שישנה חובת חינוך מדאורייתא<sup data-n=\"589\">27</sup>, ולא הוזכר זה בפוסקים, אלא כולם נקטו דחובת החינוך אינו אלא מד\"ס, וכמפורש בלשון אדמו\"ר הזקן בשלחנו ריש הל' ת\"ת הנ\"ל \"שהקטן פטור מכל המצות וגם אביו אינו חייב לחנכו במצות מן התורה אלא מד\"ס כו'\"<sup data-n=\"590\">28</sup>.\nועפ\"ז כיון שמה\"ת ברגע שקטן נעשה גדול מחוייב מיד בקיום כה\"ת כולה, ואם לא נתחנך ונתרגל במצוות לפנ\"ז מן הנמנע שיוכל להזהר כדבעי בכל מ\"ע ומל\"ת מיד כשיגדל, א\"כ איך אפשר לומר דאין חיוב מה\"ת להכינו ולהכשירו לזמן גדלותו לבל יעבור על מצוות התורה מחמת (חסרון ידיעה ו)חוסר הכנה<sup data-n=\"591\">29</sup>. ועוד, ע\"פ משנת\"ל דמצד חיוב המצות שיחולו תיכף כשיגדל איכא חובת הכנה שברגע שית­",[["586","24","פרשתנו יח, יט. וראה לעיל הערה 13."],["587","25","יש להעיר דמצינו דיעה מפורשת דישנו גדר של חינוך מדאורייתא, והוא בתרומת הדשן (פסקים סי' סב) שכ' דקטן העובר עבירה בקטנותו א\"צ לעשות תשובה ע\"ז כשיגדיל דקטן אינו בר אזהרה כלל כדמוכח מהא דקטן אוכל נבילות אין ב\"ד מצווין להפרישו (יבמות קיד, א) — \"והא דאייתי קרא (יבמות שם) דאסרה תורה דלא ליספו לי' בידים יש לומר הטעם דקפיד רחמנא שלא ירגיל אותו לעבור עבירות וכשיגדל יבקש לימודו\". אבל בשו\"ת חת\"ס (או\"ח ספ\"ג) כ' ד\"זה אינו עיקר דלא דרשינן טעמי' דקרא\", ע\"ש. ובשו\"ת אדמו\"ר הזקן הנ\"ל סי' מא \"אבל למספי איסור בידים לקטן דאסור לכ\"ע לאו משום חינוך אתינן עלה אלא מדכתיב לא תאכלום כו', דחינוך אינו מוטל אלא על האב בלבד. . ע' א\"ח סי' שמג\". וכן מוכח לכאורה ממה שפסק בהל' שבת (שם) ס\"ה \"לספות לו איסור בידים אסור לכל אדם מן התורה אפילו אינו בר הבנה כלל שנא' לא תאכלום כו'\"."],["588","26","בכתובות כב, א (ועוד) \"למה לי קרא סברא הוא\". וראה פנ\"י ברכות לה, סע\"א. בית האוצר מערכת א כלל קלא. ושם (בסופו) מביא מחזקוני (נח ז, כא) \"יש כמה מצות שחייבים בני אדם לשמרן מכח סברת הדעת אע\"פ שלא נצטוו\"."],["589","27","בכללות המצות. וגם במצות פרטיות כמו הקהל (הנ\"ל הערה 14), הרי נוסף ע\"ז שבכמה מקו­מות משמע שאין זה בגדר חינוך, הרי מלשון הרמב\"ן עצמו \"קטנים הקרובים להתחנך\" מובן שאין זו מצות חינוך באופן הרגיל. וכן ב\"ליספו לי' בידים\" לדעת התרוה\"ד (הנ\"ל הערה 25), הרי פשוט שאינה דומה הקפידה שירגיל עצמו באיסור לשאר עניני חינוך."],["590","28","ובאו\"ח סשמ\"ג ס\"ב וכן במהד\"ת סוף סי' ד כ' (רק) שהוא חיוב \"מד\"ס\", \"שחייבו חכמים\"."],["591","29","יש לדון אם אפשר לחייב האב (או כל מי שיש בידו) לחנך הבן מחמת \"לפני עור\", דכיון דקטן אינו יכול לחנך את עצמו, והוא נמצא ברשותו של האב, א\"כ בזה שאינו מחנכו ה\"ה מכשילו, והוי כתרי עברי נהרא."]]],[1301670127,"גדל יוכל לקיימן, והרי חובה זו קיימת ועומדת אלא שא\"א שתחול על הקטן שאינו בר דיעה, ולמה לא העבירה התורה החיוב על האב או הב\"ד, וכנ\"ל.\nה. ונראה, דמה שנת\"ל (סעיף ב), דכיון שמיד כשהגדיל הקטן ה\"ה מתחייב בכל המצוות כולן, לכן אם לא קיימן או עבר עליהן מחמת חסרון ידיעה והכנה קודמת נחשב כמבטל מ\"ע וכעובר על מל\"ת — אינו מוכרח. ובהקדים:\nכשהתורה מחייבת באיזו מצוה, פשוט שהחיוב חל רק באופן שתוכל להתקיים בדרך הטבע, דלא ניתנה תורה למלאכי השרת<sup data-n=\"592\">30</sup>, ואם קיומה דורש שהיית זמן אינו עובר על החיוב כל משך אותו הזמן. ולדוגמא, במצות ביעור חמץ, הרי כל זמן שעוסק בביעורו עד שנתבער בפועל אינו עובר על מצות תשביתו. דזהו גדר המצוה — לעשות מה שביכולתו לבער החמץ, ואם מתעסק בזה ה\"ה עוסק בקיום המצוה. ובלשון אדמו\"ר הזקן<sup data-n=\"593\">31</sup> \"מתחילת שעה ז'. . כל רגע ורגע שנמצא חמץ ברשותו ואינו מתעסק לבערו הוא עובר על מ\"ע של תורה\", משא\"כ כשמתעסק בביעורו הרי ההתעסקות היא חלק מקיום המצוה (היינו ההתעסקות בהכנת הביעור, ולא רק העסק בעצם הביעור). ואין זה שייך לדין אונס רחמנא פטרי' (שנאמר, שמאותו רגע של מציאת החמץ ה\"ה עובר על מצות השבתה, אלא שכל הזמן הנדרש כדי לבערו נחשב כאנוס, ורחמנא פטרי'), דזה שייך רק אם כבר חל החיוב ונאנס ע\"י דבר צדדי שמעכב קיומו, אבל אם מעצם טבע הדברים אי אפשר לקיים החיוב מבלי שהיית זמן או הכנה והכשרה מוק­דמת הרי זהו חלק מהחיוב.\nוהנה במצות שקיומן בזמנים מיוחדים, אם קיום המצוה דורש הכנה והכשרה, כגון תקיעת שופר שצריך להתאמן ולהת­רגל כדי שיוכל לתקוע, או אם צריך השתדלות מוקדמת כדי להשיג חפצי המצוה כמו ד' מינים וכדומה, מובן לכ­אורה שחיוב ההכנה מתחיל לפני זמן קיום המצוה כדי שבבוא זמנה יוכל לקיימה כתיקונה<sup data-n=\"594\">32</sup>. ולהעיר דהחיוב לקיים כל ה­תורה כולה הוא חיוב תמידי, וגם מצוות",[["592","30","ברכות כה, ב. וש\"נ. ולהעיר מבכורות (יז, ב) \"ת\"ש (דאפשר לצמצם בידי אדם) ממדת כלים. . דרחמנא אמר עביד ובכל היכי דמצית למיעבד ניחא לי'\". וראה ע\"ז (ג, א) \"אין הקב\"ה בא בטרוניא עם בריותיו\". ובשמו\"ר (פל\"ד, א) \"לא בא על האדם אלא לפי כוחו\"."],["593","31","או\"ח ר\"ס תמה."],["594","32","על דרך זה מצינו לענין מ\"ע דתשביתו — בפסחים ו, א: א\"ר הא דאמרת (המפרש והיוצא בשיירא) קודם שלשים יום אין זקוק לבער לא אמרן אלא שאין דעתו לחזור אבל דעתו לחזור אפילו מראש השנה זקוק לבער (דכי הדר בי' בימי הפסח עבר עלי' וההיא שעתא לאו ברשותי' היא דלבטלי' כו' — רש\"י). ובשו\"ע אדמו\"ר הזקן או\"ח סתל\"ו ס\"ו: \"וזה שיוצא מביתו ולא יחזור קודם הפסח שכשיגיע חצות יום י\"ד לא יוכל לבדוק ולבער החמץ שבביתו הרי בשעה זו שהוא מפליג מביתו חל עליו מצות תשביתו מן התורה<sup data-n=\"e15\">*</sup>, שמן התורה אין חילוק בין תוך ל' יום לקודם ל'\" (וראה קו\"א סתל\"ב סק\"א ומה שהביא שם מהרא\"ש פ\"ק דפסחים ס\"י).\nובמנ\"ח (מצוה ה אות ז) מביא מ\"ש הצל\"ח (פסחים ג, ב) ש\"לא מצינו (במי שהוא בדרך רחוקה) שיהי' מחוייב לעלות ולהתקרב קודם זמן הפסח\" כדי שיוכל להקריבו, וכתב ע\"ז המנ\"ח \"ודבריו אינם מובנים לי כלל, דודאי מצות עשה על כל ישראל לעשות הפסח ככל מ\"ע שבעולם, ומחוייב לילך מקצה הארץ להתקרב עצמו כדי לקיים מ\"ע. . אטו לולב ושופר כי לא יהי' מחוייב לקנות קודם החג, ובחג אינו בנמצא, וכי אינו מבטל בזה המ\"ע, אתמהה\". ובפשטות גם הצל\"ח יודה דבשאר המצוות מחוייב להכין א\"ע קודם הזמן, ודבריו אמורים רק לענין דרך רחוקה שהוא פטור מיוחד<sup data-n=\"e16\">**</sup>. ובשאילת יעב\"ץ סקכ\"ז \"בודאי א\"א לומר ג\"כ שהרחוקים מאד יתחייבו לעלות לרגל מתחילת השנה לעשות הפסח. . ונלע\"ד שכך הוא הענין, ששלשים יום לפני הפסח חל חובת עשייתו על הרחוקים שיעתיקו מבתיהם. . מזמן שחל חובת ביעור חמץ כו'\", ע\"ש."],["e15","*","וכן משמע בחינוך מצוה ט שכ' \"ומאימת מוטל עליו המצוה אם יוצא לדרך כו'\" וקאי במ\"ע דתשביתו מה\"ת."],["e16","**","אבל ראה לקח טוב שבהערה הבאה \"המקום הי\"א\"."]]],[1301670128,"שעצם קיומן צ\"ל בזמן מסויים, מ\"מ החיוב שיתקיימו בזמנן הוא תמידי. ולכן מי שנתעצל להשיג ד' מינים קודם החג, ולכן לא הי' יכול לקיים מצות נטילתם בזמנה, נחשב כמבטל מ\"ע<sup data-n=\"595\">33</sup>.\nאמנם בקטן שנתגדל, כיון שקטן פטור מכל התורה כולה, ולא שייך בי' (בהיותו קטן) שום סרך של חיוב מה\"ת<sup data-n=\"596\">34</sup>, והתחלת",[["595","33","ובלקח טוב (להר\"י ענגיל) כלל ו אות ג (ד\"ה ואמנם נלע\"ד ואילך) האריך בענין זה (אם יש חיוב גם קודם זמן המצוה), ומביא מבעה\"מ ספ\"ק דשבת שכ' בטעמא דאין מפליגין בספינה פחות משלשה ימים קודם לשבת ד\"מקום סכנה הוא וכל שלשה ימים קודם לשבת קמי שבתא מקרי ונראה כמתנה לדחות את השבת מפני שאין דבר שעומד בפני פקוח נפש\", הרי דלפני ג' ימים קודם שבת אינו מחוייב לדאוג על שמירת השבת. אבל יש לחלק, דהתם הרי מה שיעשה בשבת הוא בהיתר כיון שפקו\"נ דוחה שבת, ואין האיסור בפחות מג' ימים רק מפני שנראה כמתכוון לדחות את השבת (ועד\"ז הוא בעוד דוגמאות שמביא שם). וראה גם שו\"ת צ\"צ יו\"ד סצ\"ב. שו\"ת אבני נזר או\"ח סשכ\"א. שד\"ח כללים מערכת המ\"ם כלל קלד.\nבצפע\"נ הל' שבועות פ\"ה הט\"ו \"והנה באמת יש נ\"מ בין מ\"ע. שיש מ\"ע שהחיוב חל עליו רק בזמנו אבל קודם לכן אין עליו חיוב כלל שיעשה המצוה בזמנו ויש שאף קודם לזה מחויב לראות שכשיבוא הזמן יקיים המצוה. . וס\"ל לרבינו דגבי סוכה כיון דצריך שלא יהא מן העשוי והוה העשי' ג\"כ מן ההכשר שפיר י\"ל דיש עליו חיוב כל השנה שיהא לו סוכה בזמנה. . משא\"כ במצה דאין עליו חיוב כלל קודם הזמן שיאכל בזמנו\" [ועפ\"ז מבאר שם החילוק בלשון הרמב\"ם שם הי\"ח \"שלא יאכל מצה שנה או שנתיים\" וגבי סוכה כ' \"שלא ישב בצל סוכה לעולם\". ע\"ש]. אבל לכאורה מובן דמ\"ש שאין עליו חיוב כלל קודם הזמן, היינו שאין עליו חיוב עשי', אבל החיוב (דאכילת מצה בליל פסח) אקר­קפתא דגברא הוא חיוב תמידי גם קודם הפסח. ואולי י\"ל כוונתו, דגבי סוכה המצוה עצמה מתחלת קודם זמן חובת הישיבה כיון שבהכרח שתהי' עשי' קודם החג, משא\"כ גבי מצה דיכול לאפותה בליל פסח, לכן עצם המצוה חל רק בזמן חובת אכילתה, אבל היכא שבפועל לא תהי' בידו מצה בליל הפסח אם לא ישתדל לפנ\"ז, לכאורה פשוט שמצות אכילה בליל פסח מחייבתו להשתדל בזה גם קודם הפסח<sup data-n=\"e17\">*</sup>. וראה לקח טוב שם, שגם את\"ל שהחיוב הוא רק בזמן המצוה, נראה פשוט דמי שאין לו אלא לולב אחד לפני סוכות ויודע שגם בסוכות לא יהי' לו רק לולב זה וישרפנו לפני סוכות אזי חשוב מה\"ת מבטל עשה כיון שיודע שעי\"ז לא יוכל לקיים חיוב התורה בעת אשר יבוא עליו. וצ\"ע."],["596","34","הראשונים נחלקו בקטן שהגיע לחינוך אם הוא כמחוייב בדבר מדרבנן, דלדעת רש\"י (ברכות מח, א) והרמב\"ן (הובא בר\"ן ספ\"ב דמגילה) מצוות שעושה הקטן משום חינוך \"לאו מצוה דידי' אלא דאבוה, דאיהו לא מיחייב במצות כל עיקר\", ולדעת התוס' (ברכות שם) והר\"ן (הנ\"ל) מיקרי מחוייב בדבר מדרבנן ויכול להוציא את הגדול שאכל שיעורא דרבנן<sup data-n=\"e18\">*</sup>. ובמ\"א נת' שיש לתמוה על שיטת תוס' ודעימי', דכיון שמה\"ת אין הקטן בר דיעה ולא שייך בי' שום גדר של חיוב, איך יחולו עליו חיובים מדרבנן (וגם אין סיבה שיטילו עליו חכמים חיובים כיון דמצד חינוך די אם כל החובה מוטלת על האב). ונתבאר דגם לשי' תוס' תחילת חלות החיוב היא רק על האב, אלא דכיון דגוף החיוב הוא שהאב ישפיע ויכריח שהבן עצמו יעשה המצוה, הרי למעשה איכא\nחיוב בעשי' זו, ולכן מקרי מחוייב בדבר, דאף שאין החובה בעשי' זו על הבן עצמו כ\"א על אביו, סו\"ס עשיית הקטן היא עשי' של חיוב. — ראה בארוכה לקו\"ש חי\"ז ע' 234 ואילך."],["e17","*","ולהעיר שמיישב שם (ע\"פ חידושו דיש נפק\"מ בין המ\"ע) דברי התוס' בקידושין (כט, א) דאמאי מילה לא הוי מ\"ע שהזמ\"ג דהא אינו נימול בלילה. ויל\"ע אם מתאים עם המבואר בפנים ה­הערה."],["e18","*","וכ\"מ דעת הרמב\"ם שפסק בהל' ברכות פ\"ה הט\"ו­טז \"בן מברך לאביו\", וכן הוא לשונו בכ\"מ (מצויין לעיל הערה 1) דקטן חייב בציצית, בסוכה וכו' — ראה בארוכה בלקו\"ש הנסמן בפנים ההערה."]]],[1301670129,"כל המציאות של חיוב אינו אלא משנת­גדל, לכן אם מצד טבע הדברים נחוץ זמן של לימוד והכנה עד שיוכל לקיים כל המצות, הרי זמן הכנה זו (מה\"ת) מתחיל רק אחרי שנתגדל, ושוב אא\"ל שעובר על שום מצוה עד שחולף הזמן של ההכנה הדרושה לקיום אותה מצוה.\nואף כי זהו חידוש גדול בהלכה, מ\"מ נראה דמסברא מוכרח הוא, דאיך יחול איזה חיוב באופן שמעצם טבעו א\"א לקיימו, ומכיון שהאפשריות של קיום ה­מצוה כדבעי אינה אלא ע\"י הקדמה של לימוד וחינוך הדורש זמן מסויים, לכן צ\"ל דכל זה נכלל בעצם החיוב. ולכן אין סברא שהתורה תחייב לחנכו בעודו בקט­נותו כדי שיוכל לקיים כל המצוות כשיג­דיל, ואדרבה, התחלת חלות החיוב אינה אלא ברגע שנתגדל, ואם צריך זמן של חינוך והכשרה, הרי זה כלול בעצם חלות החיובים שחלים אחרי שנתגדל<sup data-n=\"597\">35</sup>.\nו. והוכחה לסברא זו יש להביא מגר הבא להתגייר, דקי\"ל דמודיעין אותו (רק) מקצת מצות קלות ומקצת מצות חמורות [וגם זה רק כדי שיפרוש, כדאיתא בגמ']<sup data-n=\"598\">36</sup>. והרמב\"ם<sup data-n=\"599\">37</sup> הוסיף \"ומודיעין אותו עיקרי הדת שהוא ייחוד השם ואיסור עכו\"ם ומאריכין בדבר הזה ומודיעין אותו מקצת מצות. . ואין מאריכין בדבר זה\". והנה פשוט דאם לא נתלמד ונתחנך בעשיית כל המצוות קודם גירותו, לא יוכל לקיימן מיד אחר הגירות<sup data-n=\"600\">38</sup>, וא\"כ למה אין מלמדין אותו כל המצוות ובכל פרטיהם, ואדרבה — \"אין מאריכין בדבר זה\". וע\"כ צ\"ל כנ\"ל בנוגע לקטן, דכיון שכל עיקר החיוב בתומ\"צ חל רק אחרי הגירות, לכן גם החיוב של הכנה והלימוד מתחיל רק אז, ואם ידרוש זמן של הכנה ורגילות עד שיוכל לקיים מצוות מסויימות כהלכתן, הרי כל משך אותו הזמן אינו עובר על מצוות אלו.\nובדוגמת קטן שנתגדל (וגר שנתגייר) אירע לאבותינו בשעת מ\"ת שאז נתחייבו לראשונה בתורה ובמצוות<sup data-n=\"601\">39</sup>, ובודאי נד­רש זמן של לימוד והכנה עד שהיו יכולים לקיים המצוות<sup data-n=\"602\">40</sup>, וכן עד שהיו יכולים להכין חפצי המצוות כמו ציצית ותפלין<sup data-n=\"603\">41</sup>,",[["597","35","ובסגנון אחר, החיוב דהכשר מצוה שייך רק כשישנו חיוב מצוה על הגברא, שאז חל עליו גם החיוב להכין ולהכשיר כל הדרוש לקיום המצוה, משא\"כ בקטן שאינו בר חיובא, לא שייך שמהחיוב שבגדלותו יסתעף חלות חיוב של הכשר והכנה בקטנותו, וגם בזה קיימא התמי' שבש\"ס (פסחים קטז, א) \"חיובי לדרדקי\", שלא שייך שום גדר חיוב ביחס לקטנים."],["598","36","יבמות מז, א­ב. וראה דק\"ס השלם (ירו­שלים, תשמ\"ו). וש\"נ."],["599","37","הל' איסו\"ב פי\"ד ה\"ב."],["600","38","ואין לומר דכיון שאינו מוכרח להתגייר א\"א שיחולו עליו שום דינים, דהרי הותר ללמדו מקצת מצות כו' גם קודם הגירות אף שעכו\"ם שלמד תורה חייב מיתה (סנהדרין נט, א). ולהעיר ממהרש\"א בחדא\"ג שבת לא, א. שו\"ת רעק\"א סי' מא. טו\"א חגיגה יג, א."],["601","39","פיה\"מ להרמב\"ם חולין ספ\"ז. — וכבר העירו (ראה בית האוצר להר\"י ענגיל כלל א אות ז) מל' הרמב\"ם הל' מלכים רפ\"ט \"ונשלמה תורה על ידו\". ולהעיר ממדרש ויק\"ר פ\"א, יו\"ד \"אע\"פ שניתנה תורה סייג לישראל מסיני לא נענשו עלי' עד שנשנית באוה\"מ, משל לדיוטגמא שהיא כתובה ומחותמת ונכנסה למדינה אין בני המדינה נענשים עלי' עד שתתפרש להן בדימוסי' של מדינה כו'\"."],["602","40","דרק במצות מתי מספר נאמר \"כאשר צוך\" (ואתחנן ה, יב ובפרש\"י. שם, טז ובפרש\"י. וראה פרש\"י בשלח טו, כה)."],["603","41","בבית אלקים (להמבי\"ט) שער היסודות פל\"ז כ' דבנ\"י לא הניחו תפלין במדבר. אבל ביל\"ש שלח טו, לד (מובא ברבותינו בעה\"ת שם, לב) מפורש דהניחו. וכן משמע בקידושין לז, ב."]]],[1301670130,"ופשוט דאין לומר שכל אותו הזמן שהיו עסוקים בהכנה היו מבטלים מ\"ע (ונפטרו רק משום דאונס רחמנא פטרי'), אלא ש­כיון שאז הותחל כל עיקר החיוב, לפיכך חל באופן שיוכלו לקיימן, דהיינו בהק­דמת כל ההכנות הדרושות, כולל גם החינוך והרגילות.\nוכן הוא אצל כל קטן שנתגדל (ועד\"ז גר שנתגייר), שכל החיוב שלו בתורה ומצוות מתחיל רק בהגיעו לגדלות, לכן כל הזמן שהוא צריך להתעסק בלימוד והכנה וחינוך עד שיוכל לקיים איזו מצוה כהלכתה או להזהר מאיזו עבירה, אינו מבטל אותה מ\"ע ואינו עובר על אותה מל\"ת, ואדרבה ה\"ה עסוק בקיומם<sup data-n=\"604\">42</sup>, ו­להכי ליכא חובת חינוך בעודו קטן מן התורה<sup data-n=\"605\">43</sup>.\nז. ע\"פ הנ\"ל יש לבאר ענין תמוה בשייכות לאברהם אבינו:\nבפסוק<sup data-n=\"606\">44</sup> \"ואברהם זקן בא בימים\" ארז\"ל<sup data-n=\"607\">45</sup> שאברהם אבינו עבד עבודתו במשך כל ימי חייו, עד שכל ימיו היו \"יומין שלימין\"<sup data-n=\"608\">46</sup>. ולכאורה צריך ביאור: איך אפשר לומר שכל ימיו של אברהם היו בשלימות, והרי חסרו בעבודתו ג' שנותיו הראשונות, כמחז\"ל<sup data-n=\"609\">47</sup> \"בן ג' שנים הכיר אברהם את בוראו שנאמר<sup data-n=\"610\">48</sup> עקב אשר שמע אברהם בקולי, חושבני' מאה ושבעין ותרין שנין\". וכ\"ש וק\"ו לפי ה­דיעות דבן ארבעים שנה הכיר את בוראו, או בן מ\"ח<sup data-n=\"611\">49</sup>, שצריך ביאור איך אפשר לומר עליו \"בא בימים\", שלא הי' חסר אצלו אפילו יום אחד, ועד שאמרו רז\"ל<sup data-n=\"612\">50</sup> (בנוגע לשרה, שלכאורה מזה מובן שכן הוא באברהם) \"כולן שוין לטובה\"?\nוע\"פ הנ\"ל, דענין ההכנה והכשרה ל­מצוה הוי תוצאה ופרט בעצם החיוב, יש לומר עד\"ז גם בנוגע לאברהם אבינו:\nזה שאברהם הכיר את בוראו בהיותו בן ג' שנה בא ע\"י הכנתו והכשרתו בזמן שלפנ\"ז, לחקור ולדרוש את האלקים, וב­לשון הרמב\"ם<sup data-n=\"613\">51</sup> \"התחיל לשוטט בדעתו. .",[["604","42","וי\"ל דע\"ד זה הוא בהציווי דהקמת המשכן — \"ועשו לי מקדש ושכנתי בתוכם\" (תרומה כה, ח) שמזמן הציווי (למחרת יוה\"כ — פרש\"י תשא ל, טז) עד ההקמה והתחלת העבודה בו (ר\"ח ניסן — פקודי מ, יז) עברו כמעט ששה חדשים, ובינתיים היו עסוקים בנדבת המשכן, בעשייתו ובעשיית כליו ע\"י חכמי לב. ופשוט שכל משך אותו הזמן שבין הציווי והקיום, קיימו המ\"ע ד\"ועשו לי מקדש\", דכיון שהכנות אלו היו נחוצות בשביל הקמת המשכן, הרי ההתעסקות בהם היא (התחלת) קיום המצוה<sup data-n=\"e19\">*</sup>."],["605","43","היינו חובת חינוך פרטי בכל מצוה ומצוה, אבל עדיין יתכן דאיכא חובה כללית \"לחנכו ב­קדושה\", כנ\"ל הערה 23. וראה לקו\"ש ח\"ז ע' 151 בהערות."],["606","44","ח\"ש כד, א."],["607","45","ראה זח\"א קכט, א. רכד, א. ועוד."],["608","46","ראה ד\"ה ואברהם זקן תשל\"ח, תשמ\"ו (סה\"מ מלוקט ח\"א ע' רפט. תנא). וש\"נ."],["609","47","נדרים לב, סע\"א."],["610","48","תולדות כו, ה."],["611","49","ב\"ר פ\"ל, ח. וש\"נ. וראה כס\"מ לרמב\"ם שבהערה 51."],["612","50","פרש\"י ר\"פ ח\"ש."],["613","51","הל' ע\"ז פ\"א ה\"ג.\nברמב\"ם שם \"משנגמל איתן זה. . והוא קטן\". ולהעיר, שהרמב\"ם ס\"ל כמ\"ד בן מ' שנה הכיר את בוראו (וברמב\"ם שם \"וכל העם עובדי ע\"ז והוא עובד עמהם\". וראה ב\"ר פל\"ט, ח). אבל מזה מובן להדיעה דבן ג' שנה הכיר את בוראו, שהתחיל \"לשוטט בדעתו\" לפני שהגיע לגיל שלש שנים. וראה הערה הבאה."],["e19","*","וגם לפמ\"ש בצפע\"נ מהדו\"ת (להל' ת\"ת פ\"ג ה\"ג) — \"נ\"מ בין משכן למקדש, דבמשכן הוי המצוה הבנין. . אבל הבנין של מקדש הוא רק כדי שיהי' כו'\" (ע\"ש), הרי לכאורה זהו רק העסק בהבני' שהוא גוף המצוה אבל לא הנדבה וההבאה להמשכן, ומ\"מ גם התעסקות זו נחשבת (כהתחלת) קיום המצוה. ואכ\"מ."]]],[1301670131,"והי' תמה האיך אפשר שיהי' הגלגל הזה נוהג תמיד ולא יהי' לו מנהיג, ומי יסבב אותו, ולבו משוטט ומבין עד שהשיג דרך האמת כו'\". וכיון שבמשך כל ג' השנים<sup data-n=\"614\">52</sup> הי' עסוק בהכשר והכנה להכרת בוראו, שייך לומר שהיו \"יומין שלימין\", גם ב­שנים לפני שהכיר את בוראו, וגם בנוגע לג' שנים הראשונות.\nאלא שאעפ\"כ אין זה בכלל \"שמע אברהם בקולי\" כל זמן שלא הכיר את בוראו בפועל, ומ\"מ אין שום חסרון בכך שעדיין לא הכיר אז את בוראו, כי כך מוכרח בטבע הדברים, שהי' דורש זמן של הכנה והכשרה.\n[ע\"ד הנ\"ל, דזה שבן י\"ג שנה ויום א' אינו יכול להתחיל מיד בקיום המצוה בשלימותה, אין הפירוש בזה שיש חסרון אצלו בקיום המצוה ורק שאינו נענש כי הוא בגדר \"אונס\" דרחמנא פטרי', אלא שמלכתחילה כך מותנה בעצם החיוב, ש­בתחלה עוסק בהכנה והכשרה כו' ואח\"כ מקיים בפועל ובשלימות כו'].\nח. והנה כל הנ\"ל הוא מן התורה, אבל מדברי סופרים ישנו ציווי וחיוב גמור בחינוך קטן, ואדרבה — חמורים וערבים דברי סופרים יותר מדברי תורה<sup data-n=\"615\">53</sup>.\nויש להוסיף, שכללות הענין דקיום המצות בזמן הגלות הוא ענין של \"חינוך\" לגבי קיום המצות אחרי הגאולה, כדאיתא בספרי<sup data-n=\"616\">54</sup> \"אע\"פ שאני מגלה אתכם מן הארץ לחוצה לארץ, היו מצויינין במצוות, שכשאתם חוזרים לא יהיו עליכם חדשים. . הציבי<sup data-n=\"617\">55</sup> לך ציונים\", שכן, \"עיקר כל ה­מצוות ליושבים בארץ ה'\"<sup data-n=\"618\">56</sup>.\nוע\"י קיום המצוות בזמן הגלות, מ­מהרים ומזרזים את הזמן דקיום המצוות בתכלית השלימות, כמצות רצונך<sup data-n=\"619\">57</sup>, ב­גאולה האמיתית והשלימה ע\"י משיח צדקנו, במהרה בימינו ממש.\n<span data-k=\"q\">(משיחות אחש\"פ וש\"פ שמיני תשמ\"ז; ש\"פ וירא תשמ\"ח) </span>",[["614","52","וי\"ל שהתחיל מיד בצאתו לאויר העולם, ע\"ד שמצינו (ב\"ר פל\"ו, ה. ויק\"ר פ\"ה, א) שלפני המבול \"כשהיתה אחת מהם יולדת. . היתה אומרת לבנה (הנולד) צא והבא לי צור לחתוך טבורא\". ומזה מובן גם לאחרי המבול אצל יחידי סגולה כמו האבות, ולכן יתכן שמיד בצאתו לאויר העולם הי' שייך כבר לשוטט בדעתו כו'."],["615","53","סנהדרין פח, ב (במשנה). ע\"ז לה, א ובפרש\"י. ירושלמי ברכות פ\"א ה\"ד."],["616","54","עקב יא, יז — הובא בפרש\"י שם, יח."],["617","55","ירמי' לא, כ."],["618","56","רמב\"ן אחרי יח, כה."],["619","57","תו\"ח ר\"פ ויחי. המשך וככה תרל\"ז פי\"ז ואילך. ועוד."]]],[1301670132,"<h3>שיחה ב</h3>\nא. וה' המטיר על סדום ועל עמורה גפרית ואש גו' ויהפוך את הערים האל ואת כל הככר ואת כל יושבי הערים גו'<sup data-n=\"620\">1</sup>.\nובפרש\"י עה\"פ<sup data-n=\"621\">2</sup>, דמ\"ש \"ויהפוך את הערים האל\" קאי לא רק על סדום וע­מורה שנזכרו בפסוק שלפניו, אלא על כל ארבע הערים שבככר<sup data-n=\"622\">3</sup>, וכמפורש בפ' נצבים<sup data-n=\"623\">4</sup> \"כמהפכת סדום ועמורה אדמה וצבוים\" [ואף שלעיל<sup data-n=\"624\">5</sup> פרש\"י שחמשה כרכים היו בככר (והם חמשת המלכים שנזכרו בפ' לך<sup data-n=\"625\">6</sup>, סדום ועמורה אדמה צבוים וצוער), רק ארבע מהם נהפכו, כי המלאך הסכים לבקשת לוט \"לבלתי הפכי את העיר (צוער)\"<sup data-n=\"626\">7</sup>, כמבו­אר במפרשים<sup data-n=\"627\">8</sup>].\nומבאר בצפנת פענח (להרגצובי) עה\"ת<sup data-n=\"628\">9</sup> טעם החילוק בין עונשן של סדום ועמורה לאדמה וצבוים, שהראשונות נשרפו באש מן השמים, ואילו אדמה וצבוים רק נהפכו — כי סדום ועמורה נענשו מדין עיר הנדחת<sup data-n=\"629\">10</sup> (כמובן מירו­שלמי<sup data-n=\"630\">11</sup> ותוספתא<sup data-n=\"631\">12</sup>), ולכך נשרפו (כדין עיר הנדחת<sup data-n=\"632\">13</sup>), משא\"כ אדמה וצבוים לא היו יכולות להיות נידונות מדין עיר הנדחת, כפסק המשנה<sup data-n=\"633\">14</sup> שאין עושין ג' עיירות עיר הנדחת, ולכן רק נהפכו.\nוהנה חילוק זה בין עונשן של סדום ועמורה לאדמה וצבוים מוכרח גם ב­פשוטם של כתובים, דעונש שריפה (גפ­רית ואש מן השמים) נזכר רק בסדום ועמורה, ובהפיכת הערים נאמר \"ויהפוך את הערים האל\" (וקאי על ד' הערים, וכנ\"ל מפרש\"י)<sup data-n=\"634\">15</sup> — וא\"כ יש לעיין, מהו הטעם ע\"פ פשוטו של מקרא לחילוק זה?\nומובן, שביאור הנ\"ל של הצפע\"נ אינו ענין לפשוטו של מקרא, כי ע\"ד הפשט — (א) עיקר העונש של סדום ועמורה לא הי' מחמת חטא עבודה זרה<sup data-n=\"635\">16</sup>, אלא (ב­לשון הכתוב<sup data-n=\"636\">17</sup>) לפי ש\"יד עני ואביון לא",[["620","1","פרשתנו יט, כד­כה."],["621","2","שם, כה."],["622","3","ומקורו בב\"ר (פנ\"א, ד), אלא דשם \"חמשת כרכים הללו\". וראה מפרשי ב\"ר שם. מפרשי רש\"י שצויינו בהערה 8. ועוד."],["623","4","כט, כב."],["624","5","פרשתנו יח, יז. שם, כד. וראה רש\"י שם, כט."],["625","6","יד, ב. שם, ח. וראה נח י, יט (הובא בפרש\"י פרשתנו שם, יז. אלא שבנח שם לא נזכר בלע (צוער), רק \"לשע\". ואכ\"מ)."],["626","7","פרשתנו יט, כא."],["627","8","ראה רא\"ם, ס' זכרון, נחלת יעקב, דברי דוד (להט\"ז), דבק טוב ועוד."],["628","9","פרשתנו כאן (ולעיל יח, כד). נצבים שם."],["629","10","ראה גם אלשיך פרשתנו כאן."],["630","11","סנהדרין פ\"י ה\"ח."],["631","12","סנהדרין פי\"ד, א."],["632","13","פ' ראה יג, יז."],["633","14","ריש סנהדרין. ובגמ' שם טז, ב."],["634","15","דעכצ\"ל (בפשש\"מ) שגם \"אדמה וצבוים\" בכלל (ולא רק סדום ועמורה שנזכרו בפסוק של­פנ\"ז), שהרי מפורש בנצבים (כנ\"ל) \"כמהפכת סדום ועמורה אדמה וצבוים\". אלא שרש\"י לא הביאו כאן, ומשמע שמוכרח גם מלשון הכתוב כאן. וראה בחיי כאן. באר בשדה על פרש\"י. ואכ\"מ."],["635","16","אף שגם חטא זה הי' אצלם, כפרש\"י פר­שתנו (יט, כד ד\"ה המטיר על סדום). וראה סנהדרין קט, א. רד\"ק לך יג, יג (ובפרש\"י לך שם \"יודעים רבונם ומתכוונים למרוד בו\")."],["636","17","יחזקאל טז, מט. הובא בראב\"ע לך שם. רמב\"ן פרשתנו יט, ה (ע\"ש). — וראה לקו\"ש ח\"ה ע' 156 הערה 45 ובשוה\"ג שם. וש\"נ."]]],[1301670133,"החזיקה\" (וכדלקמן סעיף ג), (ב) כל דין עיר הנדחת אינו שייך בב\"נ וקודם מ\"ת, (ג) בפשוטו של מקרא לא נזכר הדין דאין עושין עיר הנדחת שלש עיירות, (ד) ואם מצד הסברא (כמ\"ד בגמ'<sup data-n=\"637\">18</sup> שהוא \"משום קרחה\"<sup data-n=\"638\">19</sup>) — הרי אין חילוק בזה בין שריפה או הפיכה, דאותה הסברא שאין לשרוף (ולהחריב) ג' עיירות, מ­חייבת ג\"כ שלא להחריבן באופן של הפיכה.\nב. ויובן זה בהקדם דיוק לשון ה­כתוב<sup data-n=\"639\">20</sup> (בתחילת הענין), \"ויאמר ה' זעקת סדום ועמורה כי רבה וחטאתם כי כבדה מאד\", דיש לעיין אמאי נזכרו (בפירוש) בכתוב רק סדום ועמורה ולא שאר ה­ערים שבככר (ורק בפרש\"י<sup data-n=\"624\">5</sup> הובא שהיו חמשה כרכים).\n[ברד\"ק<sup data-n=\"639\">20</sup> תי' \"כי הם ראשי הממל­כות\" (וג' הערים האחרות היו טפלות להן). אבל לכאורה אינו ביאור מספיק, כי א\"כ הול\"ל רק סדום, שהרי (בל' ה­רד\"ק שם) \"סדום היתה אם לכולם\", וכהובא בפרש\"י<sup data-n=\"642\">21</sup> (בטעם שאמר ה'<sup data-n=\"642\">21</sup> \"אם אמצא בסדום (דוקא) חמשים צדי­קים גו' ונשאתי לכל המקום בעבורם\") \"לפי שסדום היתה מטרפולין וחשובה מכולם תלה בה הכתוב\", וכן מצינו ש­המלאך<sup data-n=\"644\">22</sup> הלך רק לסדום — וא\"כ גם בנדו\"ד, אם כוונת הכתוב רק להזכיר העיקר, הו\"ל להסתפק גם כאן בהזכרת סדום<sup data-n=\"645\">23</sup> (וע\"ד לשון רש\"י כמ\"פ<sup data-n=\"646\">24</sup> גבי שליחות המלאכים \"להפוך (להשחית) את סדום\"), ולמה הזכיר גם עמורה<sup data-n=\"647\">25</sup>?].\nומשמע מזה, שעיקר החוטאים היו אנשי סדום ועמורה<sup data-n=\"648\">26</sup>.\nוזהו גם הטעם שרק בסדום ועמורה המטיר ה' גפרית ואש, וכפרש\"י עה\"פ<sup data-n=\"649\">27</sup> ד\"כשבא ליסר הבריות מביא עליהם אש מן השמים\", היינו שאנשי סדום ועמורה שגדל חטאם מתו ונאבדו מתוך יסורים של \"אש מן השמים\", משא\"כ אנשי שאר הערים רק נאבדו ע\"י הפיכתן.\nאבל אין זה ביאור מספיק, כי מ­פרש\"י גבי בקשת לוט \"הנה<sup data-n=\"650\">28</sup> נא העיר הזאת קרובה לנוס שמה גו'\" — \"קרובה ישיבתה נתיישבה מקרוב לפיכך לא נת­מלאה סאתה עדיין\", \"הלא מצער היא — והלא עונותי' מועטין\"<sup data-n=\"651\">29</sup>, מוכח, ששני הערים האחרות (אדמה וצבוים) נתמלאה",[["637","18","סנהדרין שם."],["638","19","ובר\"ח סנהדרין שם משמע, שגם זה הוא מטעם \"שמא ישמעו נכרים ויחריבו את א\"י\" (סנ­הדרין שם, בטעם שאין עושין עיר הנדחת סמוכה לספר)."],["639","20","יח, כ."],["624","5","פרשתנו יח, יז. שם, כד. וראה רש\"י שם, כט."],["639","20","יח, כ."],["642","21","יח, כו."],["642","21","יח, כו."],["644","22","היינו, לא רק המלאך שהלך להציל את לוט שהי' גר בסדום, אלא גם המלאך המשחית כו' (ראה רש\"י יח, ב) הלך לסדום דוקא. וראה גם לעיל (יח, טז) \"וישקיפו על פני סדום\" (דוקא)."],["645","23","אבל מ\"ש לעיל (לך שם) \"ואנשי סדום (דוקא) רעים וחטאים גו'\" אינו מטעם חשיבות, אלא לפי שרק זה נוגע שם, ד\"אעפ\"כ לא נמנע לוט מלשכון עמהם\" (רש\"י שם)."],["646","24","פרשתנו יח, ב. שם, לג. יט, טז."],["647","25","ומ\"ש (לך יג, י) \"לפני שחת ה' את סדום ואת עמורה\", אינו מפני חשיבותם, אלא לפי שעיקר ההשחתה היתה בהם, שנשרפו (כדלקמן הערה 48).\nועד\"ז מ\"ש שם (יד, יא) \"ויקחו את כל רכוש סדום ועמורה\", לכאורה י\"ל כי כן הי' בפועל, שלקחו רק רכושם ולא דשאר העיירות (ואולי מפני שהיו עיירות קטנות כו'). ואכ\"מ."],["648","26","להעיר מהאזינו לב, לב ובפרש\"י (\"מעשה סדום ועמורה\"). ישעי' א, י ובפרש\"י שם. ועוד."],["649","27","יט, כה ד\"ה מן השמים."],["650","28","יט, כ."],["651","29","וראה משכיל לדוד לך (יד, ב), שמטעם זה לא נזכר בכתוב שם שם מלך בלע (צוער), כי שמות מלכי שאר ד' הערים רומזים על רשעתם, כפרש\"י שם (הובא לקמן ריש ס\"ג), משא\"כ צוער שעונותי' מועטין."]]],[1301670134,"סאתן. וא\"כ אמאי לא נענשו גם הם ע\"י \"אש מן השמים\"?\nג. ויש לומר הביאור בזה, ע\"פ פרש\"י לעיל בפ' לך<sup data-n=\"652\">30</sup>, בפירוש שמות המלכים, \"ברע מלך סדום. . ברשע מלך עמורה שנאב מלך אדמה ושמאבר מלך צבוים\", וז\"ל<sup data-n=\"653\">31</sup>: \"ברע — רע לשמים ורע לבריות; ברשע — שנתעלה ב­רשעו<sup data-n=\"654\">32</sup>; שנאב — שונא אביו שבשמים; שמאבר — שם אבר לעוף ולקפוץ ו­למרוד בהקב\"ה\".\nהרי בשני האחרונים מודגשת בשמם רק מרידתם נגד הקב\"ה (בין אדם ל­מקום), ואילו אצל \"ברע\" הי' רע כפול — רע לשמים ורע לבריות. ובפשטות זהו הפירוש ד\"ברע\" — \"ב' (סוגי) רע\". ועפ\"ז נ\"ל, דמ\"ש רש\"י אח\"כ בפירוש \"ברשע\" — \"שנתעלה ברשעו\", היינו הוספה על \"ברע\", היינו שגם אצל \"ברשע\" היו ב' סוגי רשע (\"ב' רשע\"), לשמים ולבריות, ונקרא \"ברשע\" (לא \"ברע\") לפי \"שנת­עלה ברשעו\".\nויש לומר, שזהו גם החילוק בין רשעת אנשי ערים אלה בשנים הבאות<sup data-n=\"655\">33</sup> (כשנענשו על חטאם), דרשעת אדמה וצבוים היתה בעיקר בחטאים שבין אדם למקום, רע לשמים, משא\"כ בסדום ו­עמורה הי' רע כפול, הן לשמים (שמרדו בה'<sup data-n=\"656\">34</sup> והיו עובדי ע\"ז<sup data-n=\"657\">35</sup>) והן לבריות, ואדרבה, עיקר הרשעה של סדום ועמו­רה אשר בגללה נענשו בעונש חמור כזה הי' (כמפורש בקרא<sup data-n=\"636\">17</sup>) \"יד עני ואביון לא החזיקה\", וכמובא גם בפרש\"י פרשתנו<sup data-n=\"659\">36</sup> \"הכצעקתה, צעקת ריבה אחת שהרגוה מיתה משונה על שנתנה מזון לעני\" (וכמובן ג\"כ מהנהגת אנשי סדום כשבאו המלאכים אל לוט<sup data-n=\"660\">37</sup>).\nד. וע\"פ זה מובן גם החילוק בין עונשם של הערים, עד שאין רש\"י צריך לפרשו, כי מובן הוא מפרש\"י לעיל:\nבס\"פ נח<sup data-n=\"661\">38</sup> מבאר רש\"י ההבדל בין עונשם של דור המבול ושל דור הפלגה, וז\"ל: \"וכי איזו קשה של דור המבול או של דור הפלגה, אלו לא פשטו יד בעיקר ואלו פשטו יד בעיקר להלחם בו, ואלו נשטפו ואלו לא נאבדו מן העולם, אלא שדור המבול היו גזלנים והיתה מריבה ביניהם לכך נאבדו, ואלו היו נוהגים אהבה וריעות ביניהם כו' למדת ששנאוי המחלוקת וגדול השלום\".",[["652","30","שם."],["653","31","ומקורו בתנחומא שם (ח)<sup data-n=\"e20\">*</sup>. — ובב\"ר (פמ\"ב, ה) נדרש באו\"א. ואכ\"מ."],["654","32","בדפוס ראשון ורוב כת\"י רש\"י שתח\"י ליתא ד\"ה ברע וד\"ה ברשע. אבל ישנם בדפוסי רש\"י הנפוצים (ובדפוס שני (וא' מכת\"י רש\"י שתח\"י): ברע שהי' רע. ברשע שהי' רשע)."],["655","33","לשיטת רש\"י בפירושו עה\"ת בפ' בא (יב, מ) — שברית בין הבתרים היתה שלשים שנה לפני לידת יצחק — מלחמת ד' מלכים עם החמשה בפ' לך (שקדמה לברית בין הבתרים, כסדרם בקרא. וכמפורש ברש\"י לך טו, א)<sup data-n=\"e21\">*</sup>, היתה בערך כט שנה לפני הפיכת סדום ועמורה (שקדמה ללידת יצחק בשנה אחת — ראה פרשתנו יח, י וברש\"י שם)."],["656","34","רש\"י לך לך יג, יג. וראה רד\"ק שם."],["657","35","נסמן לעיל הערה 16."],["636","17","יחזקאל טז, מט. הובא בראב\"ע לך שם. רמב\"ן פרשתנו יט, ה (ע\"ש). — וראה לקו\"ש ח\"ה ע' 156 הערה 45 ובשוה\"ג שם. וש\"נ."],["659","36","יח, כא. — אלא שרש\"י הביאו רק כפירוש שני (ועוד מקדים \"ורבותינו דרשו\"), דאינו פשוטו ממש, כי כיצד יתכן לומר שהריגת \"ריבה אחת\" היתה ע\"י תושבי ב' ערים (סדום ועמורה)."],["660","37","פרשתנו יט, ד ואילך. וראה רש\"י שם, ב ד\"ה ולינו."],["661","38","יא, ט."],["e20","*","אלא ש\"ברשע\" מפרש \"שנעשה רשע\", ואילו בפרש\"י \"שנתעלה ברשעו\"."],["e21","*","כ\"כ ברבותינו בעה\"ת לך יב, ד (בשיטת רש\"י). אבל ראה תוד\"ה לא ברכות ז, ב. רש\"י פרשתנו יט, כ. ואכ\"מ."]]],[1301670135,"הרי מפורש, שעונש דור המבול, ש­נשטפו ונאבדו, הי' בעיקר מפני ש\"היו גזלנים והיתה מריבה ביניהם\". וכן מובן מפרש\"י בריש פ' נח, עה\"פ<sup data-n=\"662\">39</sup> \"כי מלאה הארץ חמס\" — \"לא נחתם גזר דינם אלא על הגזל\", היינו, דאע\"פ שחטאו גם בעריות וע\"א, כפרש\"י שם גופא<sup data-n=\"663\">40</sup>, \"ותשחת — לשון ערוה וע\"א\", ועד שזו היתה סיבת העונש באופן של \"קץ כל בשר\"<sup data-n=\"662\">39</sup>, כפרש\"י שם \"כל מקום שאתה מוצא זנות וע\"א אנדרלמוסיא באה ל­עולם והורגת טובים ורעים\", מ\"מ, \"לא נחתם גזר דינם אלא על הגזל\".\nומבואר במפרשים<sup data-n=\"665\">41</sup> בטעם הדבר, כי גזל ומריבה הם היפך יישובו של עולם ומחזירים את העולם לתהו. ונ\"ל בכוונת הדברים, דאין המבול רק עונש חמור על חטאים חמורים, אלא ענינו כעין חרטה על כללות בריאת האדם והעולם<sup data-n=\"666\">42</sup>, שהנ­הגת הנבראים הביאה לידי כך שהקב\"ה התחרט כביכול על עצם הבריאה, וב­מילא החריב עולמו אשר ברא, באופן של \"וימח<sup data-n=\"667\">43</sup> את כל היקום גו'\", איבוד מוחלט<sup data-n=\"668\">44</sup>. וזהו שהסיבה העיקרית לגזירה זו היא עון גזל ומריבה, כי רק הנהגה באופן שמחזיר את העולם לתהו, היפך יישוב העולם, היא המנגדת לעצם ה­בריאה<sup data-n=\"669\">45</sup>.\nועפ\"ז יש לבאר כפל הענין בכתוב<sup data-n=\"662\">39</sup> \"קץ כל בשר בא לפני כי מלאה הארץ חמס גו' והנני משחיתם את הארץ\": \"קץ כל בשר\" ענינו עונש החוטאים על גודל חטאם, ולפי שמדובר בעון זנות וע\"א הרי העונש באופן של \"קץ כל בשר\", \"אנדרלמוסיא כו' והורגת טובים ורעים\" (ועונש כזה אינו מוגבל לזמן המבול, וכדיוק לשון רש\"י \"כל מקום שאתה מוצא זנות וע\"א כו'\"); משא\"כ על ידי ש\"מלאה הארץ חמס (עון גזל). . הנני משחיתם את הארץ\", וכפרש\"י \"עם ה­ארץ, שאף ג' טפחים של עומק המחרי­שה נמוחו ונטשטשו\"<sup data-n=\"671\">46</sup>, שעצם הארץ נשחתה, שדבר זה הוא לפי שהמבול לא הי' רק עונש על החוטאים אלא ענין של איבוד עצם הארץ (היפך בריאת העולם).\nוע\"פ כל זה מובן גם לעניננו — עונש סדום ועמורה כו':\nהחילוק בין המטרת \"גפרית ואש. . מן השמים\" להפיכת הערים הוא, דב­הפיכת הערים נהרגו יושבי הערים וגם נחרב כל צמח האדמה<sup data-n=\"672\">47</sup>, אבל אין בזה השחתת האדמה עצמה, וזוהי ההוספה בזה ש\"וה' המטיר גו' גפרית ואש\", ד­נוסף על יסורי הבריות, הרי עוד ועיקר, שבזה נשרפו הערים ונשחתו כליל<sup data-n=\"673\">48</sup>",[["662","39","ו, יג."],["663","40","שם, יא."],["662","39","ו, יג."],["665","41","ראה גו\"א. אמרי שפר על פרש\"י בשם תולדות יצחק. דברי דוד (להט\"ז). צידה לדרך. דבק טוב בהגהה. הואיל משה (באר היטב). ועוד."],["666","42","ראה בכ\"ז בארוכה לעיל ע' 35 ואילך."],["667","43","נח ז, כג."],["668","44","וי\"ל שזהו דיוק ל' רש\"י הנ\"ל \"ואלו נשטפו\" (ולא \"נאבדו\", כלשון רש\"י עצמו שם אח\"כ, וגם בנוגע לדור המבול) — כי \"נשטפו\" מורה על העדר וביטול המציאות לגמרי, משא\"כ \"נאבדו\" שאינו מכריח שנתבטלה מציאותם (דיתכן שמצי­אותם קיימת אלא שאין יודעים היכן נמצאות)."],["669","45","ראה תולדות יצחק (שהובא באמרי שפר שם) \"היפך הכוונה הראשונה בבריאת העולם\"."],["662","39","ו, יג."],["671","46","בפרש\"י הוא פירוש שני, אבל י\"ל שה­חילוק בין שני הפירושים הוא רק בפירש התיבות \"את הארץ\", אבל לכו\"ע חלק מהארץ נמחה במי המבול. ולהעיר מרש\"י נח ח, יג­יד."],["672","47","כלשון הכתוב כאן (יט, כה)."],["673","48","ועפ\"ז יובן ל' הכתוב לעיל (לך לך יג, י) \"שחת ה' את סדום ואת עמורה\", כי עיקר ענין ה­השחתה הוא בשריפת סדום ועמורה ולא (כ\"כ) בהפיכת הערים. וראה ל' הכתוב יט, כח­כט. ישעי' א, ט (וראה שם, ז). שם יג, ט. ירמי' מט, יח; נ, מ (\"ושכני'\"). עמוס ד, יא (\"מוצל משרפה\"). ואכ\"מ."]]],[1301670136,"(ע\"ד<sup data-n=\"674\">49</sup> \"הנני משחיתם את הארץ\" ע\"י ה­מבול<sup data-n=\"675\">*49</sup>).\nולכן הוטל עונש זה רק על סדום ועמורה, שעיקר חטאם הי' בין אדם לחבירו (ע\"ד עונש דור המבול לפי ש\"היו גזלנים והיתה מריבה ביניהם\"), משא\"כ אדמה וצבוים שעיקר חטאם הי' בין אדם למקום נענשו רק בהפיכה.\nה. ובפנימיות הענינים יש לומר:\nמבואר בחסידות<sup data-n=\"676\">50</sup> בטעם עונש סדום, שנאבד ונחרב לגמרי, כי הנהגת סדום, היפך השלום ואחדות, היא ע\"ד עולם התהו, שבתהו \"כל א' בפני עצמו, ענפין מתפרדין\", וזהו טעם המ\"ד<sup data-n=\"677\">51</sup> ד\"האומר שלי שלי ושלך שלך. . זו מדת סדום\", כי עצם ענין הפירוד וההתחלקות זמ\"ז ה\"ז כענין עולם התהו, ענפין מתפרדין. וזהו\"ע איבוד סדום ועמורה כו', שהוא ע\"ד ה\"שבירה\" דעולם התוהו (כמחז\"ל<sup data-n=\"678\">52</sup> \"שהי' בורא עולמות ומחריבן\"), שמטרתו הוא \"סותר ע\"מ לבנות\", בשביל בריאת עולם התיקון שענינו עולם של התכללות ואחדות כו'.\nאמנם, תכלית הכוונה היא, שב\"כלים\" דתיקון יומשכו ויתגלו גם ה\"אורות דתהו\" שהם למעלה ממדידה והגבלה, אלא כיון שיהי' ב\"כלים דתיקון\", אין בזה ענין של פירוד ושבירה, אלא אד­רבה, תכלית האחדות כו'.\nועפ\"ז יש לפרש מ\"ש ביחזקאל<sup data-n=\"679\">53</sup> ש­לעתיד ישובו ערי סדום, \"ושבתי את שביתהן את שבית סדום ובנותי'\", דיש לומר, שהתוכן הפנימי דשיבת ובנין ערים אלו הוא, שבזמן הגאולה יתגלו למטה אורות דתהו, אלא שאז יומשכו אורות אלה בכלים דתיקון דוקא (בנין, היפך השבירה).\nוזהו גם מה שאמרו במדרש<sup data-n=\"680\">54</sup> \"מ­צאתי<sup data-n=\"681\">55</sup> דוד עבדי, היכן מצאתי אותו בסדום\", דלכאורה תמוה, כיצד יתכן שדוד מלכא משיחא יהי' שייך לסדום דוקא? אלא זהו מצד המעלה הפנימית שבה, גילוי אורות דתהו, ולכן \"מצאתי אותו בסדום\" דוקא, כי זהו ענינו של דוד מלכא משיחא, שעל ידו יהי' גילוי אורות דתהו (שלמעלה ממדידה והג­בלה), אלא שיומשכו בכלים דתיקון דוקא.\nועפ\"ז אולי יש לומר, שזהו התוכן הפנימי למעליותא שבשני סוגי הערים דסדום ובנותי' שישובו לעתיד לבוא: סדום ועמורה (שנשרפו) רומזות על אורות דתהו שלמעלה ממדידה והגבלה, ושתי הערים אדמה וצבוים (שהם ע\"ד דור הפלגה<sup data-n=\"682\">56</sup> כנ\"ל, שלא הי' שם (כ\"כ)",[["674","49","ולא ממש (ראה לעיל שם)<sup data-n=\"e22\">*</sup>."],["675","*49","ראה תוספתא תענית פ\"ב, יא. יל\"ש נח רמז סא. וראה ב\"ר פרשתנו פמ\"ט, ט<sup data-n=\"e23\">*</sup>."],["676","50","אוה\"ת פרשתנו צט, ב ואילך. וראה תו\"ח נח (עז, א). פרשתנו (קח, ג). ובכ\"מ."],["677","51","אבות פ\"ה מ\"י."],["678","52","ב\"ר פ\"ג, ז."],["679","53","טז, נג. וראה של\"ה חלק תושב\"כ פ' לך (רעט, א), וע\"ש שזהו הטעם שאברהם השתדל כ\"כ בהצלת סדום."],["680","54","ב\"ר פרשתנו (פ\"נ, י. הובא בשל\"ה שם). וראה יבמות עז, א. מאמרי אדה\"ז תקס\"ו ריש ע' תג."],["681","55","תהלים פט, כא."],["682","56","ראה דרושי הפלגה בתו\"א, תו\"ח ואוה\"ת (כרך ו) פ' נח — ע\"ד השייכות דדור ההפלגה לההתכללות דעולם התיקון (נזכר באוה\"ת פרשתנו שם (ק, א))."],["e22","*","וראה \"רשימות\" חוברת ג' (קה\"ת תשנ\"ה) ע' 39. המו\"ל."],["e23","*","וראה \"רשימות\" שם (ע' 9­38). המו\"ל."]]],[1301670137,"ענין הגזל ומריבה) הוא ע\"ד ענין ההתכללות דכלים דתיקון<sup data-n=\"683\">57</sup> — ושיבת כל ד' הערים יחד מורה על חיבור והתאחדות אורות דתהו וכלים דתיקון.\n<span data-k=\"q\">(משיחות ש\"פ וירא וח\"ש תשמ\"ג, ש\"פ נח תשמ\"ב) </span>",[["683","57","אלא שבאוה\"ת פרשתנו שם, שעונש סדום הוא \"כמו שבה\"כ ויהפוך את הערים וכו'\" — שזה הי' גם בשני ערים הנ\"ל."]]],[1301670138,"<h3>שיחה ג</h3>\nא. \"ויאמר אל תשלח ידך אל הנער ואל תעש לו מאומה כי עתה ידעתי כי ירא אלקים אתה גו'\"<sup data-n=\"684\">1</sup>, ובפרש\"י על \"כי עתה ידעתי\" (ד\"ה הא') מביא מאמרו של ר' אבא<sup data-n=\"685\">2</sup> \"א\"ל אברהם אפרש לפניך את שיחתי אתמול אמרת לי<sup data-n=\"686\">3</sup> כי ביצחק יקרא לך זרע וחזרת ואמרת<sup data-n=\"687\">4</sup> קח נא את בנך עכשיו אתה אומר לי אל תשלח ידך אל הנער א\"ל הקב\"ה לא אחלל בריתי ומוצא שפתי לא אשנה<sup data-n=\"688\">5</sup> כשאמרתי לך קח מוצא שפתי לא אשנה לא אמרתי לך שחטהו אלא העלהו אסקתי' אחתי' [ה­עלית אותו — הורידו]\".\nוכבר תמהו מפרשים<sup data-n=\"689\">6</sup>:\nא) מנ\"ל לרש\"י כ\"ז בפשוטו של מקרא<sup data-n=\"690\">7</sup>? איפה מרומז ב\"כי עתה ידעתי\" שאברהם תמה \"אתמול אמרת לי כו' וח­זרת ואמרת כו'\", והקב\"ה השיבו ד\"מוצא שפתי לא אשנה, לא אמרתי לך שחטהו כו'\".\nב) למה תמה אברהם רק כאשר נצ­טווה \"אל תשלח ידך גו'\", ולא לפנ\"ז — תיכף כשנצטווה \"קח נא את בנך\" (שזהו בסתירה להבטחת הקב\"ה \"כי ביצחק יקרא לך זרע\")?\nגם יש לדייק:\nמקורו של מאמר זה הוא בבראשית רבה<sup data-n=\"691\">8</sup>, אבל שם לפנינו, נוסף לזה שהובא בשם ר' אחא<sup data-n=\"692\">9</sup> (ולא ר' אבא), עם עוד שינויי לשון<sup data-n=\"693\">10</sup> — יש גם שינוי עיקרי בתוכן:\nבמדרש איתא \"א\"ר אחא התחיל אברהם תמי', אין הדברים הללו אלא דברים של תימה, אתמול אמרת כו'\", היינו שאברהם תמה על הנהגת הקב\"ה. וגם לפי הגירסא<sup data-n=\"694\">11</sup> (שקרובה ללשון רש\"י) \"אף את לפניך שיחות (בתמי')\", הרי הכוונה בזה היא, כמ\"ש בפירוש המד\"ר המיוחס לרש\"י (ועד\"ז הוא בילקוט<sup data-n=\"695\">12</sup>) \"אמר אברהם כביכול יש לפניך שיחות כבני אדם שמחליפין דיבורן\";\nמשא\"כ בפרש\"י הגירסא \"א\"ל אברהם אפרש לפניך את שיחתי\" — שלשון זו אינה ביטוי של תמי' כלפי מעלה, ואינה מוסבת על \"שיחות\" (דברי) הקב\"ה, אלא על דברי אברהם (\"שיחתי\").\nויש להבין (א) למה בחר רש\"י בגירסא זו דוקא. (ב) מהו תוכן הקדמה",[["684","1","פרשתנו כב, יב."],["685","2","ראה לקמן בפנים בהמשך הסעיף ובהנסמן שם."],["686","3","פרשתנו כא, יב. וראה לקמן הערה 17 ב­שוה\"ג הב'."],["687","4","כב, ב."],["688","5","תהלים פט, לה."],["689","6","ראה יפה תואר (השלם) לב\"ר פנ\"ו, ח (יב). נזר הקדש (השלם) לפנ\"ז (שם, ב). וכן במפרשי רש\"י — דברי דוד כאן. ס' חלקי אבנים על פרש\"י (פירדא, תג\"ן. וכמ\"פ לאח\"ז). באר יצחק. באר בשדה. מלאכת הקודש. ועוד."],["690","7","ולהעיר שבדפוס א' וב' דפרש\"י, וכן ברוב כת\"י רש\"י שתח\"י — ד\"ה זה ליתא. וראה הערה 18."],["691","8","שם."],["692","9","וכ\"ה בתנחומא באבער פרשתנו מ. וראה ב\"ר הוצאת תיאודור­אלבק שם בחילופי נוסחאות."],["693","10","וראה בפרטיות בב\"ר הוצאה הנ\"ל ובחי­לופי נוסחאות שם."],["694","11","כ\"ה בב\"ר הוצאה הנ\"ל. וראה חילופי נוסחאות שם."],["695","12","שמעוני — פרשתנו רמז קא."]]],[1301670139,"זו, שלכאורה היא שפת יתר, ולמה לא התחיל תיכף בגוף הענין \"אתמול אמרת כו'\"? (ג) איזו \"שיחה\" שלו בא אברהם לפרש<sup data-n=\"696\">13</sup>?\nב. ונ\"ל שאכן זוהי כוונת רש\"י בהע­תקת לשון זו (\"אפרש לפניך את שיחתי\"), להבהיר, שכוונת אברהם אבינו בדבריו אלה לא היתה לתמוה על דברי הקב\"ה\n[כי ע\"פ פשוטו של מקרא אין לומר שאברהם אבינו הרהר אחרי מדותיו של הקב\"ה. וכמפורש בפרש\"י לעיל<sup data-n=\"697\">14</sup> ש­הקב\"ה ניסה את אברהם \"אם יהרהר אחר דבריו של הקב\"ה שאמר לו ללכת אל ארץ כנען ועכשיו משיאו לצאת ממנה\" — דאף שהם דברים סותרים, מ\"מ לא הרהר (אפילו) \"אחר דבריו של הקב\"ה\". וכן מצינו בפרש\"י להלן (ס\"פ שמות<sup data-n=\"698\">15</sup>) בנוגע לנדו\"ד, שזו היתה מעלת אברהם על משה רבינו, שא\"ל הקב\"ה למשה \"הרהרת על מדותי, לא כאברהם שאמרתי לו כי ביצחק יקרא לך זרע<sup data-n=\"686\">3</sup> ואח\"כ אמרתי לו העלהו לעולה<sup data-n=\"687\">4</sup> ולא הרהר אחר מדותי\" (והיינו, שלא רק שלא היתה אצל אברהם חלישות בקיום הציווי בפועל, אלא שאף במחשבתו לא עלה שום הרהור<sup data-n=\"701\">16</sup> \"אחר מדותי\")<sup data-n=\"702\">17</sup>. וא\"כ ודאי, דגם בסוף הענין, כאשר גדלה הסתירה ש\"עכשיו אתה אומר לי אל תשלח ידך\" — לא הרהר אברהם אחר מדותיו של הקב\"ה (ומה גם להביע תמיהתו בדיבור)],\nאלא לפרש לפני הקב\"ה את כוונתו (של אברהם) בדבריו הקודמים לזה<sup data-n=\"703\">18</sup>.",[["696","13","בדברי דוד פי' \"כלומר עד הנה הי' לי קושיא בלבי אבל עכשיו אני מקשה בפירוש\". אבל ראה לקמן סעיף ב."],["697","14","לך יב, י."],["698","15","ו, א. — וראה לקו\"ש חט\"ז (ע' 47 ואילך) טעם השינוי בפרש\"י וארא (ו, ט)."],["686","3","פרשתנו כא, יב. וראה לקמן הערה 17 ב­שוה\"ג הב'."],["687","4","כב, ב."],["701","16","וגם לה\"מדרש אגדה\" בפרש\"י לעיל (כב, ה) שאברהם אמר \"אראה היכן הוא מה שאמר לי המקום (לך טו, ה) כה יהי' זרעך\" — אין זה ענין של הרהור אחר מדותיו ח\"ו, אלא אדרבה, מצד הוודאות שהבטחה זו תתקיים (ורוצה לראות \"היכן\" תתקיים). וראה משכיל לדוד ובאר בשדה על פרש\"י שם."],["702","17","ומזה גופא מובן, שאין לומר שהטעם שלא שאל אברהם \"אתמול אמרת כו'\" תיכף כשנצטווה \"קח נא גו'\" הוא לפי שידע שאפשר שהבטחת הקב\"ה תתבטל ע\"י חטא (ע\"ד פרש\"י וישלח לב, יא) — ראה ראב\"ע פרשתנו (כב, א), ובארוכה ביפה תואר ונזר הקודש הנ\"ל (הערה 6) — כי לפ\"ז מהו החידוש שלא הרהר אחרי מדותיו.\nויש לומר, שרש\"י מרמז כאן הטעם שבנדו\"ד לא שייך זה, בהעתיקו תחילת הכתוב \"לא אחלל בריתי\" [אף שאח\"כ בהמשך פירושו מפרט רק זה ש\"מוצא שפתי לא אשנה\", דקאי על הציווי ד\"קח נא\"] — כי \"לא אחלל בריתי\" קאי על ההבטחה \"כי ביצחק יקרא לך זרע\"<sup data-n=\"e24\">*</sup>, שהיתה באופן של \"ברית\" [לך יז, יט (אבל ברש\"י שם דקאי על ברית מילה). שם, כא. וכן בברית בין הבתרים — שם טו, ה. שם, יח. רש\"י פרשתנו כא, א]<sup data-n=\"e25\">**</sup>, ו\"ברית\" מורה על דבר נצחי, שלא שייך בו שינוי ואא\"פ לו להתבטל."],["703","18","אבל להעיר, שבכמה כת\"י רש\"י שתח\"י הגירסא \"אשפוך לפניך (את) שיחותי\". וכ\"ה בדפוס רומא (הנ\"ל). אבל בדפוסים הנפוצים הוא כבפנים."],["e24","*","וכמ\"ש בתנחומא פרשתנו שם. אגדת ברא­שית פל\"א. וכן מפורש בב\"ר שם להגירסא שבב\"ר הוצאת תיאודור­אלבק (וראה חילופי נוסחאות שם. וראה ב\"ר שם, ה: הפר ברית).\nולהעיר, שכ\"ה הגירסא בפרש\"י בדפוס רומא (א' מדפוסים הראשונים דפרש\"י), וכן בא' כת\"י רש\"י שתח\"י — \"כשאמרתי לך כי ביצחק. . לא אחלל בריתי ואת בריתי אקים את יצחק, כשאמרתי לך קח נא ומוצא כו'\" [ואולי נשמט זה בדפוסים שלפנינו מפני תיבות דומות (\"כשאמרתי לך. . כשאמרתי לך\")]."],["e25","**","וראה השקו\"ט ביפ\"ת ונזר הקודש שם (פנ\"ו, טו), בטעם שהביא אברהם \"כי ביצחק יקרא לך זרע\", ולא הכתוב \"ואת בריתי אקים את יצחק\" (שמפורש בו הלשון \"ברית\"). ובפשטות י\"ל כי בפסוק זה מודגשת יותר השייכות לאברהם, \"יקרא לך זרע\". ואכ\"מ."]]],[1301670140,"דהנה בד\"ה שלפנ\"ז מפרש רש\"י \"אל תשלח — לשחוט, א\"ל אם כן לחנם באתי לכאן, אעשה בו חבלה ואוציא ממנו מעט דם, א\"ל אל תעש לו מאומה, אל תעש בו מום\", היינו, שהיו כאן חילופי דברים בין אברהם והמלאך, שאברהם רצה לע­שות חבלה ביצחק (דאל\"כ נמצא ש\"לחנם באתי לכאן\"), וע\"ז ענה המלאך \"אל תעש לו מאומה, אל תעש בו מום\",\nולאחרי זה פירש אברהם את שיחתו זו, דזה שרצה לעשות חבלה ביצחק היינו מפני ש\"אתמול אמרת כו' וחזרת ואמרת כו'\", וע\"ז בא שוב מענה (הקב\"ה, ע\"י) המלאך \"כי עתה ידעתי גו'\" (ואין צורך אפילו בחבלה), כדלקמן.\nג. הסברת הענין:\nלאחרי שאברהם אמר \"א\"כ לחנם באתי לכאן אעשה בו חבלה כו'\", ונענה בשלילה (\"אל תעש לו מאומה\"), חשב אברהם, שאולי הטעם שנצטווה \"אל תש­לח ידך גו'\" (היפך הציווי ד\"קח נא גו'\") הוא לפי שאינו ראוי לזה ולא עמד ב­נסיון כדבעי, כי לבו אינו שלם עמו (דאף שמוכן לקיים ציווי זה בפועל, מ\"מ, ה\"ה מהרהר אחרי מדותיו כו'), ולפיכך אין מניחים אותו לקיים הציווי ד\"קח נא גו'\".\nוחשב אברהם שזהו ג\"כ הטעם שלא נתקבלה בקשתו ד\"אעשה בו חבלה כו'\", כי בזה \"הודה\" שבאמת אינו מוכן לקיים הציווי ד\"קח נא את בנך\" ולפיכך מבקש שעכ\"פ יוכל לקיימו במקצת (ע\"י חבלה והוצאת דם), כדי שלא תהי' ביאתו לכאן \"חנם\" — ולכן נענה בשלילה;\nוכדי לשלול קס\"ד זו המשיך אברהם לטעון — \"אפרש לפניך את שיחתי\", שבקשתו \"אעשה בו חבלה כו'\" לאחרי שנצטווה \"אל תשלח ידך לשחוט\", היתה (לא לגרוע מקיום ציווי ה', בקשה שיוכל לקיים עכ\"פ ב\"מקצת\" ה\"קח נא גו'\", אלא) לפי שלדעתו נתברר אז שזו היתה מעיקרא כוונת הציווי \"קח נא\" — לא שישחוט את בנו, אלא שיוציא דם כדי לזרקו על המזבח.\nוהטעם שחשב שזה הי' הציווי מעי­קרא — הסביר באמרו \"אתמול אמרת לי כי ביצחק יקרא לך זרע וחזרת ואמרת קח נא את בנך עכשיו אתה אומר לי אל תשלח ידך אל הנער\", כלומר: לכתחילה אכן לא הבין אברהם כיצד יכולים ל­התקיים שני דיבורי ה' (כי ביצחק גו' וקח נא גו') הסותרים (אלא שכיון ש­נצטווה בפירוש \"קח גו' והעלהו גו'\" קיים זה מבלי להרהר אחרי מדותיו של הקב\"ה); אבל עכשיו שנצטווה \"אל תשלח ידך לשחוט\", הרי אפשר להכריע בין שני הכתובים ולקיים שניהם<sup data-n=\"704\">19</sup> — ע\"י עשיית חבלה והוצאת דם (וזריקתו על המזבח).\nוזו היתה טענת אברהם \"אעשה בו חבלה כו'\", שעי\"ז יוכל לקיים ציווי ה' בשלימותו, ויתקיימו כל ג' דיבורי ה' — \"(אתמול אמרת לי) כי ביצחק גו'\"; \"קח נא גו'\"; \"(עכשיו אתה אומר לי) אל תש­לח גו'\".\nוע\"ז נענה ש\"עתה ידעתי כי ירא אלקים אתה גו'\", ואין בו שום חסרון — כי לא נמנע ממנו מלקיים ציווי השם, שהרי מלכתחלה \"לא אמרתי לך שחטהו אלא העלהו, אסקתי' אחתי'\" (וזהו הטעם שאין סתירה בין שני הענינים ד\"כי ביצ­חק גו'\" ו\"קח נא גו'\") — ונמצא שאברהם קיים ציווי השם (\"העלהו\") בשלימותו.",[["704","19","ראה גם נזר הקודש שבהערה 6. באר בשדה על פרש\"י."]]],[1301670141,"ד. עפ\"ז מתורץ בפשטות הכרחו של רש\"י על פירוש זה, שהיו כאן עוד חילו­פי דברים בין אברהם והקב\"ה (\"אתמול אמרת כו' א\"ל הקב\"ה לא אחלל בריתי כו'\") — שההכרח הוא מדברי הקב\"ה לאברהם \"כי עתה ידעתי\" (שעל זה כתב את פירושו).\nוהביאור בזה:\nלכאורה צריך ביאור, לשם מה הוצ­רך הקב\"ה לומר לאברהם שעמד בנסיון (גם בלי שחיטת יצחק) ו\"עתה ידעתי כי ירא אלקים אתה\"? הרי כשם שאברהם אבינו לא הרהר אחרי מדותיו של הקב\"ה כאשר נצטווה \"קח נא את בנך\" אלא מיהר לקיים הציווי מבלי לחפש הסברה ותירוץ על ציווי זה, הרי ודאי כאשר ציווהו הקב\"ה שוב \"אל תשלח ידך\", לא הי' צורך לבאר לאברהם הטעם על כך (שגם בלי שחיטת יצחק כבר עמד בנסיון ו\"ידעתי כי ירא אלקים אתה גו'\"), כי אברהם לא הרהר אחרי מדותיו של הקב\"ה [ובפרט שבודאי הי' יכול להבין מעצמו<sup data-n=\"705\">20</sup> שכ\"ז הי' רק נסיון<sup data-n=\"706\">21</sup> ואין צורך שהקב\"ה יאמר לו בפירוש \"כי עתה ידעתי גו'\"].\nועכצ\"ל שדברי הקב\"ה \"כי עתה ידעתי גו'\" לא באו (רק) לבאר לאברהם מטרת נסיון העקידה, אלא שזה הי' גם מענה על דברי אברהם, שאל יטעה לומר שאינו ירא אלקים ולא נתקיימה מטרת הנסיון, אלא אדרבא \"עתה ידעתי כי ירא אלקים אתה\".\nוהיינו, כנ\"ל, דכאשר אברהם שמע את הציווי \"אל תשלח גו' ואל תעש לו מאומה\", אע\"פ שהקב\"ה ציווהו \"קח נא את בנך גו' והעלהו שם לעולה\" — הסיק מזה, שאולי הטעם שהקב\"ה אינו מניחו לקיים הציווי ד\"קח נא גו'\" הוא מפני שאינו ראוי לזה — וע\"ז ענה לו הקב\"ה \"(אל תשלח גו') כי עתה ידעתי כי ירא אלקים אתה גו'\", דזה שציווהו \"אל תש­לח גו'\" אינו בגלל חסרון ח\"ו באברהם, דאדרבה, \"עתה ידעתי כי ירא אלקים אתה\", אלא זהו לפי ש\"לא אמרתי לך שחטהו אלא העלהו\".\nה. והנה בדרך זו יתיישב ג\"כ מה שהעתיק רש\"י שם בעל המאמר<sup data-n=\"707\">22</sup>, ובזה גופא נקט דוקא הגירסא ר' אבא (ולא ר' אחא — כבבראשית רבה לפנינו<sup data-n=\"708\">23</sup>).\nדע\"פ הנ\"ל יש לומר, שכוונת רש\"י בהעתיקו שמו של ר' אבא היא לרמז, שזה שר' אבא נקט שדברי אברהם \"אתמול אמרת לי כו'\" לא נאמרו כמתמי' על דברי ה' (אלא רק לפרש את שיחתו, שרוצה לקיים ציווי השם בשלימות) — כי לשיטתו אזיל:\nבמסכת חגיגה<sup data-n=\"709\">24</sup> שנינו \"כל שלא חס על כבוד קונו כו'\", ובגמרא שם<sup data-n=\"710\">25</sup> — \"מאי היא, ר' אבא<sup data-n=\"711\">26</sup> אמר זה המסתכל",[["705","20","ראה יפ\"ת ונזר הקודש הנ\"ל (פנ\"ו, יב)."],["706","21","ובפרט ע\"פ פרש\"י לעיל (כב, ב) \"א\"ל בבקשה ממך עמוד לי בזה הנסיון כו'\"."],["707","22","ובפרט שלעיל על הפסוק (כב, ב) \"והעלהו שם לעולה\" כבר הביא רש\"י את הפירוש \"לא אמר לו שחטהו. . אלא להעלהו\" — ושם לא העתיק שם בעל המאמר (אף שג\"ז מקורו במאמר זה של ר' אבא)."],["708","23","וכן במדרש תנחומא, כנ\"ל הערה 9."],["709","24","משנה שם רפ\"ב (יא, ב)."],["710","25","טז, א."],["711","26","בקידושין (מ, סע\"א) הובא מאמר זה בשם רבה<sup data-n=\"e26\">*</sup>. אבל ע\"פ הידוע שסוגיא במקומה ראוי לסמוך עלי' יותר מסוגיא שאינה במקומה (דרכי שלום (בשד\"ח הוצאת קה\"ת כרך י') כללי הש\"ס אות ס' סתי\"ז. וש\"נ) — נ\"ל שהגירסא העיקרית היא ר' אבא, כבחגיגה שם, שהרי שם עיקר מקומה של הסוגיא ע\"ד \"כבוד קונו\"."],["e26","*","וכ\"ה גירסת הר\"ח בחגיגה שם. ובנוסח הכ\"י בדק\"ס חגיגה שם — \"רבא\", ובהמשך הגמ' שם \"רבה\". וראה בהגהות שם."]]],[1301670142,"בקשת. . דכתיב<sup data-n=\"712\">27</sup> כמראה הקשת אשר יהי' בענן ביום הגשם כן מראה הנוגה סביב הוא מראה דמות כבוד ה'\".\nוהנה, אף שבפשטות כוונת ר' אבא היא, שההסתכלות בקשת היא כעין הסתכלות במראה השכינה (כיון ש\"מראה הקשת. . כן מראה הנוגה סביב גו'\")<sup data-n=\"713\">28</sup>, מ\"מ מצינו<sup data-n=\"714\">29</sup>, שאיסור הסתכלות בקשת שייך ג\"כ לאות הקשת שלא יהי' עוד מבול (שלכן מברכים על ראיית הקשת \"ברוך זוכר הברית\"<sup data-n=\"715\">30</sup>, כמובא בהמשך הסוגיא שם<sup data-n=\"716\">31</sup>).\nו. ויובן זה בהקדים דיוק הלשון \"המסתכל בקשת\", שהכוונה בזה אינה לראי' סתם — שהרי אדרבה, חכמים תקנו ברכה מיוחדת על ראיית הקשת — אלא הסתכלות באופן של עיון<sup data-n=\"717\">32</sup> והת­בוננות<sup data-n=\"718\">33</sup>.\nויש לבאר הדיוק בזה: השייכות בין קשת לכבוד קונו הוא מפני \"מראה ה­קשת\" שראה יחזקאל במרכבה (\"כמראה הקשת גו' כן מראה הנוגה סביב\"), ובפרט ע\"פ המסופר בגמ' שם לפנ\"ז<sup data-n=\"719\">34</sup> דכאשר דרש ר' יהושע במעשה מרכבה \"נתקשרו שמים בעבים ונראה כמין קשת בענן\", שמזה מובן עוד יותר, שמראה הקשת שייך למעשה מרכבה. וזהו תוכן האיסור להסתכל בקשת, לפי שזה מרמז על ההסתכלות וההתבוננות בעניני מעשה מרכבה, שזהו היפך כבוד קונו, לפי שענינים אלו צ\"ל בהסתר דוקא<sup data-n=\"720\">35</sup> (בלשון הכתוב<sup data-n=\"721\">36</sup> \"כבוד אלקים הסתר דבר\"), כיון שהם למעלה מהשגת השכל האנושי וההתבוננות בהם תביא לידי שאלות וספיקות כו' [ועפ\"ז שני הענינים שבמשנה<sup data-n=\"722\">37</sup> — (א) האיסור לדרוש במעשה מרכבה אפילו ביחיד \"אא\"כ הי' חכם כו'\", (ב) \"כל שלא חס על כבוד קונו\" (שלפי ר' אבא קאי על המסתכל בקשת) — תוכנם חד].\nועפ\"ז יש לומר, שתוכן איסור זה שייך גם לאות הקשת, כי מצד \"כבוד קונו\" אין ראוי להסתכל ולהתבונן בתוכן ענין הקשת, כיון שיכולה להתעורר עי\"ז שאלה<sup data-n=\"723\">38</sup> וקושיא על הנהגתו של הקב\"ה, שבהמשך אלי' ניתנה אות הקשת.\nדהנה הטעם שלא יהי' עוד מבול על הארץ (שע\"ז בא אות הקשת) מפורש בקרא<sup data-n=\"724\">39</sup> \"לא אוסיף לקלל עוד את האד­מה בעבור האדם כי יצר לב האדם רע",[["712","27","יחזקאל א, כח."],["713","28","וראה ר\"ח חגיגה שם: זה המסתכל בקשת ואומר כגון זה דמות ה'."],["714","29","ראה רמב\"ן נח (ט, יב). אברבנאל שם. ולהעיר גם מכלי יקר (שם, יד). ועוד."],["715","30","ברכות נט, א."],["716","31","לפי גירסת הע\"י חגיגה שם. וראה גם הגהות הב\"ח שם."],["717","32","ב\"י לטאו\"ח סרכ\"ט בשם הרא\"ש. וראה פרישה שם. וראה ערוך מע' קשת. — וראה ערכי הכינויים (לבעל סה\"ד) מע' ראי'. יד מלאכי (כלל ה\"א אות קעט). שד\"ח כללים מע' הה\"א (כרך א' קטו, ב. כרך ח א'תרפא, ב ואילך). וש\"נ."],["718","33","ע\"ד \"הסתכל בשלשה דברים כו'\" (אבות רפ\"ב ורפ\"ג) — אוה\"ת שה\"ש (ע' שלא). וראה סה\"מ תש\"א ע' 113 ואילך. ועוד."],["719","34","חגיגה יד, ב. ועד\"ז בכ\"מ בזהר. — וראה לקו\"ש חי\"ז ע' 362 ואילך."],["720","35","כאריכות הסוגיא בחגיגה שם רפ\"ב (יג, א ואילך)."],["721","36","משלי כה, ב. וראה ירושלמי חגיגה שם (פ\"ב ה\"א)."],["722","37","חגיגה שם רפ\"ב."],["723","38","ראה גם אברבנאל נח שם."],["724","39","נח ח, כא."]]],[1301670143,"מנעוריו\", והרי סברא זו עצמה שימשה כטעם להבאת המבול, כמ\"ש<sup data-n=\"725\">40</sup> \"וירא ה' כי רבה רעת האדם בארץ וכל יצר מחשבות לבו רק רע כל היום\". ומה נש­תנה שבתחילה סברא זו חייבה להביא המבול, ואח\"כ נהפך שסברא זו עצמה תחייב שלא להביא עוד מבול על ה­ארץ<sup data-n=\"726\">41</sup>?!\nועוד זאת: כיון שהקב\"ה ברא את האדם מלכתחילה באופן ש\"יצר לב האדם רע מנעוריו\", הרי ודאי שהי' ידוע לפניו ית' שסו\"ס יבוא לידי מצב ש\"יצר מחשבות לבו רק רע כל היום\", ואעפ\"כ ברא הקב\"ה את עולמו, ומה נתחדש אח\"כ שבגלל זה \"וינחם<sup data-n=\"727\">42</sup> ה' כי עשה את האדם\"?\nוזהו שאומר ר' אבא שהמסתכל ב­קשת — היינו המעיין ומתבונן בתוכן אות הקשת — ה\"ז בגדר \"לא חס על כבוד קונו\"<sup data-n=\"728\">43</sup>, כי התבוננות זו יכולה לגרום אצלו לספיקות אודות הנהגת הקב\"ה.\nור' אבא לשיטתו, שודאי שאברהם לא כיוון לתמוה על הסתירה בדברי הקב\"ה — \"אתמול אמרת כו' וחזרת ואמרת כו'\" — היפך הנהגה של \"חס על כבוד קונו\", אלא כוונתו היתה אך ורק לפרש לפני הקב\"ה \"את שיחתי\", כנ\"ל באורך.\n<span data-k=\"q\">(משיחת ש\"פ וירא תשמ\"ח)</span>",[["725","40","ס\"פ בראשית (ו, ה)."],["726","41","כמו שהקשה באברבנאל (ועוד) נח שם. וראה ע\"ד החסידות — תו\"א פרשתנו (טו, סע\"ב). תו\"ח שם (ד\"ה ארדה נא פ\"כ ואילך). המשך באתי לגני השי\"ת פי\"ח. ועוד."],["727","42","בראשית שם, ו. — וראה רש\"י שם \"וזה כתבתי לתשובת אפיקורוס א'. . אין אתם מודים שהקב\"ה רואה את הנולד כו' א\"ל כך מעשה הקב\"ה כו'\"."],["728","43","וכמשנ\"ת במ\"א (שיחת ש\"פ בראשית תשל\"ו. וראה סה\"ש תנש\"א ח\"א ע' 70 ואילך) בדיוק ל' רש\"י הנ\"ל \"וזה כתבתי לתשובת אפיקורוס א'\", שאין השקו\"ט בשאלה זו דבר הראוי כו'. וראה גם לקו\"ש חל\"ד ע' 15­14."]]],[1301670144,"<h3>שיחה א</h3>\nא. עה\"פ<sup data-n=\"729\">1</sup> \"ויקם שדה עפרון\" פרש\"י \"תקומה היתה לו שיצא מיד הדיוט ליד מלך. ופשוטו של מקרא ויקם השדה והמערה אשר בו וכל העץ לאברהם<sup data-n=\"730\">2</sup> למקנה וגו'\".\nובפשטות כותב כאן רש\"י ב' פירו­שים בתיבת \"ויקם\": א) מלשון תקומה, ב) מלשון \"קנין\", והוא פשוטו של מקרא, \"דומיא<sup data-n=\"731\">3</sup> דוקם<sup data-n=\"732\">4</sup> הבית אשר בעיר אשר לו חומה לצמיתות לקונה שפרש\"י<sup data-n=\"732\">4</sup> יצא מ­כחו של מוכר ועמד בכחו של קונה\"<sup data-n=\"734\">5</sup>.\nוזה שלא הסתפק רש\"י בפירוש ויקם מלשון קנין, כפשוטו של מקרא, כתבו מפרשים<sup data-n=\"735\">6</sup>, שהוא משום \"שאין הקונה כתוב אחר הקימה (כמו בכתוב דוקם הבית כו' לצמיתות לקונה) כי לאברהם למקנה אינו דבק עם הפסוק הקודם לו מפני פיסוק הטעמים, [ו]עכ\"ל שאין פי­רוש ויקם אלא מלשון תקומה. . אבל לפי פשוטו של מקרא דלא חייש לפיסוק הטעמים פירשוהו כמשמעו מלשון קנין דומיא דויקם<sup data-n=\"736\">7</sup> השדה והמערה וזהו ש­אמר ופשוטו של מקרא ויקם השדה וה­מערה וכל העץ לאברהם למקנה הדביק לאברהם למקנה עם מלת ויקם שבפסוק הקודם לאפוקי מבעלי הדרש שלא הדביקום\".\nולכאורה ביאור זה דחוק הוא, שהרי כבר קבע רש\"י כלל גדול<sup data-n=\"737\">8</sup> בנוגע לפי­רושו \"אני לא באתי אלא לפשוטו של מקרא ולאגדה המיישבת דברי המקרא\", היינו, שרק כשיש קושי בכתוב שאינו מתורץ ע\"ד הפשט אזי מביא דברי אגדה ליישב הפשט. ומאחר שעל פי \"פשוטו של מקרא (ד)לא חייש (רש\"י) לפיסוק הטעמים\"<sup data-n=\"738\">9</sup>, הרי שבפשוטו של מקרא אין זו קושיא (וכפי שמצינו כמה פעמים ב­כמה כתובים שהם בהמשך זל\"ז אף שהם ב' פסוקים<sup data-n=\"739\">10</sup>), וא\"כ למה הוצרך רש\"י להביא עוד פי' מבעלי הדרש<sup data-n=\"740\">11</sup>, ויתירה מזו, מקדימו כפירוש ראשון ועיקרי ב­פשוטו של מקרא.\nב. יש מבארים<sup data-n=\"741\">12</sup>, דלפי הפירוש ב­פשוטו של מקרא הרי התיבות \"שדה עפרון אשר במכפלה אשר לפני ממרא\" מיותרות, דהול\"ל \"ויקם השדה והמערה וגו' לאברהם למקנה גו'\", דאטו עד השתא לא ידענא שהי' שדה עפרון. ולכן מפרש שהיתה תקומה לשדה עפרון, שכלל השדה היתה לו תקומה, ולכך אמר שדה עפרון, כלומר שהשדה שהי' מתייחס לעפרון ושבמכפלה ושעל פני ממרא תקומה היתה לו שנכנס לרשות אברהם, אבל לאידך — לפי' המדרש \"תקומה היתה לו\" קשה, כיון דכבר אמר \"",[["729","1","פרשתנו כג, יז."],["730","2","שם, יח."],["731","3","לשון הרא\"ם כאן."],["732","4","בהר כה, ל."],["732","4","בהר כה, ל."],["734","5","וראה שפ\"ח כאן בסופו."],["735","6","רא\"ם. וראה גם גו\"א ולבוש כאן."],["736","7","פרשתנו כג, כ."],["737","8","בראשית ג, ח. ובכ\"מ."],["738","9","וכ\"ה בלבוש שם."],["739","10","כן הקשה ביפ\"ת השלם לב\"ר כאן (פנ\"ח, יוד (ח)) \"כמה פסוקים דבוקים כו' רבו מספר\". ע\"ש."],["740","11","בגו\"א שם: ופשוטו של מקרא כו' ואין להקפיד על שהפסיק בשני כתובים לפי שרמז לך ג\"כ המדרש הנזכר. ועדיין צ\"ע למה הקדים רש\"י הדרש, כבפנים."],["741","12","שפ\"ח כאן ויפ\"ת השלם לב\"ר שם."]]],[1301670145,"ויקם שדה עפרון\" למה הזכיר פעם ב' \"השדה והמערה כו'\", הול\"ל \"ויקם שדה עפרון וגו' והמערה וכל העץ\", וגם דלפי פי' תקומה היתה לו אין לו חיבור עם כתוב שלאח\"ז לאברהם למקנה — לכך צריך גם הפירוש לפי \"פשוטו\" שקם ה­שדה והמערה וכל העץ לאברהם למקנה.\nולפי פירוש זה, כוונת רש\"י היא, שהפסוק עצמו מכריח ב' פירושים, דבזה שמתחלה אמר שדה עפרון ואח\"כ כפל השדה והמערה מוכח, דתרתי קמ\"ל, שהיתה תקומה לשדה עפרון ושקם השדה והמערה לאברהם למקנה.\nאך עדיין אינו מובן, מדוע מקדים רש\"י הפירוש שע\"ד הדרש לפשוטו של מקרא?\n[בפשטות י\"ל דסדר הפירושים שב­פרש\"י הוא לפי סדרם בפירוש הכתוב (\"ויקם שדה עפרון — תקומה היתה לו\", והמשך הכתוב \"השדה והמערה גו'\" פי­רושו ד\"ויקם. . לאברהם למקנה\"). אבל לכאורה אין זה טעם מספיק להקדים דרש לפני הפירוש ע\"פ \"פשוטו של מק­רא\"].\nולכן צ\"ל דס\"ל לרש\"י, שפירוש \"ויקם\" מלשון \"תקומה\" אינו דרש בלבד, וכדמוכח גם מזה שרש\"י אינו מקדים \"ארז\"ל\" או \"רבותינו פירשו\" וכיו\"ב.\nוזה שמדגיש בפירוש השני \"ופשוטו של מקרא ויקם השדה כו' לאברהם ל­מקנה\" הוא ללמדנו, שהיתרון בפירוש \"תקומה היתה לו\", שבגללו מקדימו לפירוש השני, הוא [לא מצד הפשט של מקרא זה — שהרי \"פשוטו של מקרא\" זה, הן פירוש תיבת \"ויקם\" והן פשטות המשך ב' המקראות, הוא כפירוש השני<sup data-n=\"742\">13</sup>, ד\"ויקם כו' לאברהם למקנה\" היינו ש­נקנה לאברהם — אלא] משום שעל ידו מתורץ קושי בכללות הפרשה כאן [אף שפשוטו של מקרא זה הוא כפירוש השני].\nג. והביאור בזה: בתחלה, כשדבר אברהם עם בני חת, בקש מהם \"תנו<sup data-n=\"743\">14</sup> לי אחוזת קבר עמכם ואקברה מתי מלפני\", וכן לאח\"ז<sup data-n=\"744\">15</sup> כשבקש \"אם יש את נפשכם לקבור את מתי מלפני שמעוני ופגעו לי בעפרון בן צוחר\" בקש \"ויתן לי את מערת המכפלה. . אשר בקצה שדהו. . לאחוזת קבר\", כלומר, כל השקו\"ט היתה אודות המערה בלבד; אמנם לאחר ש­אמר עפרון לאברהם<sup data-n=\"745\">16</sup> \"לא אדני שמעני השדה נתתי לך והמערה אשר בו לך נתתי'\", ענה אברהם<sup data-n=\"746\">17</sup> \"נתתי כסף השדה קח ממני ואקברה את מתי שמה\", שקיבל הצעת עפרון על השדה, ואפילו לא הזכיר את המערה.\nוצריך ביאור: זה שעפרון הציע \"לא אדני שמעני השדה נתתי לך\" יל\"פ גם לפי פשוטו של מקרא, שכוונת עפרון היתה רק להראות ישרותו וטוב לבו, כתוכן דיבורו בכלל \"לא<sup data-n=\"747\">18</sup> אדוני לא תקנה אותה בדמים\", \"נתתי לך\", אבל באמת רצה להוציא עוד כסף מאברהם (וכפי שמביא רש\"י בהפרשה<sup data-n=\"748\">19</sup> שאמר הרבה ואפילו מעט לא עשה)<sup data-n=\"749\">20</sup>, אבל למה קיבל אברהם הצעה זו מעפרון",[["742","13","להעיר, שגם בתיב\"ע כאן פסוק יז \"וקם זבין כו'\"."],["743","14","כג, ד."],["744","15","כג, ח­ט."],["745","16","כג, יא."],["746","17","כג, יג."],["747","18","רש\"י שם, יא."],["748","19","כג, טז."],["749","20","ראה רמב\"ן כאן (כג, ט): אמר לו דרך מוסר או מרמה."]]],[1301670146,"[במפרשי התורה<sup data-n=\"750\">21</sup> ביארו הדבר, אבל לכאורה זוהי שאלה גם בפשוטו של מקרא, והו\"ל לרש\"י לתרצה, ולכאורה לא מצינו ביאור בזה בפרש\"י].\nגם צלה\"ב (כדיוק המפרשים<sup data-n=\"751\">22</sup>) בה­פסוקים כאן \"ויקם שדה עפרון אשר במכפלה גו' השדה והמערה. . לאברהם למקנה גו' ואחר כן קבר אברהם את שרה אשתו גו' ויקם השדה והמערה אשר בו לאברהם לאחוזת קבר מאת בני חת\", למה הוצרך לומר ב' פעמים \"ויקם\"?\n[באור החיים האריך בזה<sup data-n=\"752\">23</sup>, ומבאר, שזהו להודיע ד\"היתה הקני' כאן ככל משפטי הקנין\", ד\"לאחר ששקל אברהם לעפרון דמי המערה בזה סלק עפרון זכותו מעל הקרקע כמ\"ש רמב\"ם<sup data-n=\"753\">24</sup>. . שהגוי מעת שלקח הדמים סילק זכותו וישראל לא קנה עד שיגיע שטר לידו, ונמצאו נכסים אלו כנכסי מדבר\", וגמר הקנין הי' אח\"כ \"באמצעות החזקה ש­הוחזק בה במה שקבר בה את שרה\"<sup data-n=\"754\">25</sup>. וזהו ה\"ויקם\" השני שרק אז אחרי שקבר את שרה נקנה לאברהם. אבל ביאור זה הוא ע\"פ הלכה, כי בפשש\"מ אין שום רמז לכל זה, ובפשטות נקנה השדה לאברהם על ידי הכסף גופא, כפשוטו של מקרא].\nוכדי לתרץ כל זה מקדים רש\"י עה\"פ \"ויקם שדה עפרון — תקומה היתה לו שיצא מיד הדיוט ליד מלך\", כדלקמן.\nד. ויובן זה ע\"פ ביאור דיוק ל' רש\"י \"מיד הדיוט ליד מלך\", דלכאורה<sup data-n=\"755\">26</sup> הרי עפרון נעשה שר<sup data-n=\"756\">27</sup> קודם המכירה, כמו שהביא רש\"י לפנ\"ז<sup data-n=\"757\">28</sup> \"אותו היום מנוהו שוטר<sup data-n=\"758\">29</sup> עליהם מפני חשיבותו של אבר­הם\", והול\"ל ל' רשע וצדיק וכיו\"ב ולא \"הדיוט\" ו\"מלך\" (ובמדרש<sup data-n=\"759\">30</sup> אכן איתא \"דהות דבר איניש זעיר ואיתעבידת לבר נש רב\").\nוהביאור בזה: החילוק בגדר הקנין כשהדיוט קונה מהדיוט, גם כשאחד חשוב מהשני, לקנין של מלך הוא, דקנין הדיוט מהדיוט תוכנו שינוי רשות, והיינו דשם הקנין הוא, יציאה מבעלות א' לבעלות שני, ובמילא אף שיש בזה שי­נויים באופני הקנין דכסף שטר וחזקה<sup data-n=\"760\">31</sup>, הרי בכל האופנים שם הקנין הוא יציאה מרשות א' לשני.",[["750","21","ראה רמב\"ן שם. ר\"י בכור שור (שם, יא­יב). חזקוני (שם, יא). אברבנאל כאן. אוה\"ח שם (סוף פסוק ט)."],["751","22","ראה רשב\"ם. חזקוני (פסוק יז; כ). ריב\"א. ר\"י בכור שור. רבינו בחיי פסוק כ. ועוד. וראה גם אברבנאל כאן."],["752","23","פסוק יט. וראה בהנסמן בהערה שלפנ\"ז."],["753","24","הל' זכי' ומתנה פ\"א הי\"ד."],["754","25","ל' האוה\"ח (וראה גם ר\"י בכור שור, חזקוני ורבינו בחיי). וראה בהנסמן לקמן הערה 37."],["755","26","כן הקשה במשכיל לדוד על פרש\"י כאן."],["756","27","כן הוא במשכיל לדוד \"קודם המכירה נעשה שר על העיר\". אבל לשון רש\"י היא (כדלקמן בפנים) \"שוטר\", ולא \"שופט\"<sup data-n=\"e27\">*</sup> כלשון רש\"י בלוט (לעיל וירא יט, א), וכבמדרש כאן (ב\"ר פנ\"ח, ז) ארכוסטרטיגוס (פירוש הערוך גדול שבנציבים. מ\"כ לב\"ר). ולהעיר גם מהשינוי בהמשך רש\"י \"מפני חשיבותו של אברהם שהי' צריך לו עלה לגדולה\", ובמדרש \"דלא יהא בר נש רב זבין מן בר נש זעיר\". אבל במושב זקנים עה\"ת מעתיק מ\"פי' ר\"ש\" \"אותו היום מינוהו שר ושופט עליהם על שנצטרך לו אברהם\". ואולי תיבת \"שוטר\" בפרש\"י כאן פירושה \"שופט\". ודוחק גדול הוא כפשוט. ואכ\"מ."],["757","28","כג, יוד."],["758","29","ראה לעיל הערה 27."],["759","30","ב\"ר פנ\"ח, ח. וראה יפ\"ת השלם שם."],["760","31","ראה הערה הבאה."],["e27","*","אבל להעיר שבדפוס שני דרש\"י כאן: שופט."]]],[1301670147,"אבל כאשר מלך קונה מיד הדיוט, הרי זה באופן דהפקעת רשות לגמרי, ואין לייחסו כאן לשם הפרטי של האיש שהוא זה שמכר השדה להמלך.\nבסגנון אחר: כאשר א' קונה מהשני, מכיון שגדרו של קנין הוא מעשה משו­תף דהמוכר (הנותן) והקונה (המקבל), אם במעשה הקנין או בסמיכת דעת — הק­נאת המוכר, הרי כשם שבמעשה הקנין ישנו שם המוכר<sup data-n=\"761\">32</sup>, נשאר השם גם על גוף השדה, ששדה זו לקח פלוני מפלוני.\nמשא\"כ בקניית מלך, עיקר גדר קנין הוא לא מצד הנותן והמוכר, אלא מצד המלך (והרי בידו של המלך ליקח הכל מאנשי המדינה בפועל<sup data-n=\"762\">33</sup>), ולכן לא נשאר שם בעלות שלפנ\"ז על השדה<sup data-n=\"763\">34</sup>.\nוזהו שמדייק רש\"י \"תקומה היתה לו שיצא מיד הדיוט ליד מלך\", שאין זה רק גדר קנין סתם ממוכר ללוקח, דשדה עפרון נקנה לאברהם, אלא \"תקומה הי­תה לו\", יציאה משם הדיוט לשם מלך, ובמילא אין כאן שייכות לשם פרטי ואין נפק\"מ בזה בין הדיוט ממש לשר — כי בזה שווים הם.\nה. ויש לומר, שענין זה הוא בהתאם לתוכן הכללי בהנהגת אברהם, שלא רצה לקבל המערה במתנה אלא קנאה, ובזה גופא הדגיש שקנייתו תהי' \"בכסף מלא\", \"אשלם כל שווי'\"<sup data-n=\"764\">35</sup> — שכוונת אברהם בזה היתה כדי לסלק (שם) עפ­רון לגמרי מן השדה, היינו לא רק שלא יהי' לעפרון שום בעלות וזכות (או אף שייכות) ממוני בהשדה [שעי\"ז אין שום סרך של \"צדיק<sup data-n=\"765\">36</sup> קבור בקבר שאינו שלו\"<sup data-n=\"766\">37</sup>], אלא עוד זאת, שגם נסתלק שמו של עפרון מהשדה<sup data-n=\"767\">38</sup>, אפילו בתור \"נותן\" או \"מוכר\" מקום קבר לקבורת שרה.\nומטעם זה הדגיש \"בכסף מלא\", היינו שהכסף שנותן אינו בגדר קנין כסף, אלא שנותן כל שוויות השדה<sup data-n=\"768\">39</sup>, כי בקנין כסף יש השתתפות דנתינת וסמיכת דעת המקנה (כנ\"ל), משא\"כ כשמשלם בכסף שוויות הדבר, באופן שלא חסר כלום אצל המוכר, הרי עיקר הקנין הוא מצד (נתינת שוויות הדבר ד)הקונה ולא הק­נאת המקנה (המוכר).\nועפ\"ז מובן עוד יותר הדגשת הכתוב אחרי הסיפור ש\"וישקול אברהם לעפרון את הכסף גו'\"<sup data-n=\"748\">19</sup> — \"ויקם שדה עפרון\". דלכאורה, לפי פשוטו של מקרא שה­",[["761","32","אלא שבזה חילוקי קנינים, אם הוי עיקרו מצד הקונה (כבחזקה) או מצד המקנה­המוכר (בשטר), ולפי מדה זו תלוי תוקף שם המקנה על הקרקע (אבל בכללות בכל קנין ישנה השתתפות שניהם). וראה סוגיית הגמ' והלימודים בקידושין כו, א. ואכ\"מ."],["762","33","ראה רמב\"ם הל' מלכים פ\"ד."],["763","34","ויש להוסיף בזה: מכיון שכל אנשי המדינה וכל אשר להם הם ברשות ובעלות המלך, דרכוש העיר והמדינה הוא בבעלותו הכללית תמיד, הרי נמצא, דכאשר הוא בבעלות הפרטית של א' מאנשי המדינה, הוא ע\"ד נתינת רשות מהמלך להשתמשות, ובמילא, כשעובר בחזרה לבעלות המלך בטל לגמרי שם ההדיוט."],["764","35","כג, ט ובפרש\"י."],["765","36","ב\"ב קיב, א."],["766","37","אברבנאל כאן. וראה נחלת יעקב לפרש\"י כאן שבא ללמד שלא רצה אברהם לקוברה עד שקנה השדה והמערה בכל דיני הקנאות כו' לפיכך קנאה אברהם בתחלה בכסף ואח\"כ בשטר כו' ואח\"כ כו' החזקה. עיי\"ש. וראה פדר\"א פל\"ו וברד\"ל שם. ש\"ך עה\"ת פרשתנו עה\"פ (יז). וראה שו\"ת חת\"ס יו\"ד סי' שלא — בפירוש דברי הרמב\"ן פרשתנו כג, יא. צפע\"נ עה\"ת כאן פסוק יט. ועוד."],["767","38","ראה לקו\"ש ח\"י ע' 62 ואילך.\nודברי יעקב (ויחי מט, כט­לב) היו כדי שלא יערערו כו' כמ\"ש במפרשי התורה שם. וראה סוף פרשתנו (כה, ט­י). ואכ\"מ."],["768","39","ראה ש\"ך עה\"ת שם."],["748","19","כג, טז."]]],[1301670148,"כוונה היא שנקנה לאברהם, מאי קמ\"ל כאן, ולכאורה כל הפסוק מיותר הוא? וזהו שמפרש רש\"י דתוכן הכתוב כאן — \"תקומה היתה לו, שיצא מיד הדיוט ליד מלך\", שהכתוב בא לומר, דנוסף לסילוק שם עפרון מן השדה ע\"י עצם קניית השדה \"בכסף מלא\", הנה עוד זאת, ש\"ויקם גו' — תקומה היתה לו שיצא מיד הדיוט ליד מלך\", שנפקע שם עפרון לגמרי מן השדה, כיון \"שיצא מיד הדיוט ליד מלך\", כנ\"ל.\nוזהו גם דיוק הלשון בכתוב שלאח\"ז — \"ואחרי כן קבר אברהם את שרה אשתו אל מערת שדה המכפלה\" (דלכ­אורה פשיטא שקבר את שרה רק לאחרי שקנה השדה) — כי רק לאחרי ש\"תקומה היתה לו\", שנפקע לגמרי שם הדיוט ממנה, היינו שלא רק שלא נשאר שום בעלות לעפרון<sup data-n=\"770\">40</sup>, אלא עוד זאת, דאין כאן שום ענין של הדיוט (אפילו שהוא מכר את השדה לאברהם), כי הוא שדה של \"מלך\" בלי שום שייכות גם בשם (שהי' למפרע) לשם עפרון — אז קבר אברהם את שרה אשתו.\nו. בדרך זו יש ליישב עוד דיוק בהמשך השקו\"ט דאברהם ובני חת<sup data-n=\"771\">41</sup>:\nאברהם ביקש תחילה \"תנו<sup data-n=\"743\">14</sup> לי אחוזת קבר עמכם\", ובפרש\"י \"אחוזת קבר לבית הקברות\", היינו, שאברהם ביקש לא רק מקום לקבורת שרה בלבד (או אפילו לקברים אחדים), אלא \"אחוזת קרקע לבית הקברות\", ואילו בני חת ענו<sup data-n=\"773\">42</sup> \"במבחר קברנו (קבר שלנו) קבור את מתך, איש ממנו את קברו לא יכלה ממך מקבור מתך\", שמזה מובן שלא רצו לתת לאברהם \"אחוזת קרקע לבית הקברות\";\nועד\"ז מצינו אח\"כ, כשביקש מעפרון מערת המכפלה \"אשר בקצה שדהו\", אמר אברהם \"בכסף מלא יתננה לי גו' לאחוזת קבר\"<sup data-n=\"774\">43</sup>, אמנם לאחרי שעפרון הציע לו את כל השדה עם \"המערה אשר בו לך נתתי'. . קבור מתך\"<sup data-n=\"745\">16</sup>, הסכים אברהם ואמר \"ואקברה את מתי שמה\"<sup data-n=\"746\">17</sup> (ושוב לא הדגיש הענין ד\"אחוזת קבר\");\nולאידך, בסיום הענין, אחרי סיפור קבורת שרה בפועל, נאמר שוב<sup data-n=\"736\">7</sup>: \"ויקם השדה והמערה גו' לאחוזת קבר\"!\nוע\"פ הנ\"ל י\"ל הביאור בזה:\nכוונת אברהם בזה שבקש \"אחוזת קבר — אחוזת קרקע לבית הקברות\", היתה שהוא יעשה את אחוזת הקרקע ל­בית הקברות, היינו שקודם כל הוא יקנה אחוזת קרקע, ורק אחרי שהיא בבעלותו של אברהם יעשנה \"בית הקברות\", כי עי\"ז מודגש יותר שאין שמו של עפרון על \"בית הקברות\" זה.\nאבל לאחרי שעפרון הציע לתת לו את כל השדה (לא רק המערה המיוחדת לקבורה), שוב לא הי' צורך להדגיש שקונה \"אחוזת קבר\", כיון שכל השדה (לא רק המערה) הוא בבעלותו של אבר­הם, באופן שפעולתו ומעשהו בהשדה אינו שייך כלל לנותן ומוכר השדה, ואז \"ואקברה את מתי שמה\", כי אין בתוכן קבורת שרה בשדה שום שייכות לעפרון, אלא אדם עושה בתוך שלו וא\"צ שימכרו לו.\nועפ\"ז מובן גם הטעם שבסיום הענין מוסיף הכתוב עוד פעם \"ויקם השדה והמערה אשר בו לאברהם (ומדייק) ל­",[["770","40","ראה הערה 37."],["771","41","ראה גם מלבי\"ם כאן, ומבאר כל השקו\"ט בהכתובים ע\"פ הרמב\"ן שהי' חוק ונימוס לבני חת שלא ליתן אחוזת קבר לגר כו'."],["743","14","כג, ד."],["773","42","כג, ו."],["774","43","כג, ט."],["745","16","כג, יא."],["746","17","כג, יג."],["736","7","פרשתנו כג, כ."]]],[1301670149,"אחוזת קבר\", להדגיש, דסו\"ס נתקיימה בקשת אברהם שיותן לו \"אחוזת קבר\", וזהו \"ויקם\" (\"תקומה\") השני, כי בזה שהשדה נעשה \"אחוזת קבר\" של אברהם, נתחזקה בעלותו על השדה, ובמילא מובן שהוספה זו בשייכותו של השדה לאבר­הם הוסיפה ג\"כ במעלת השדה (\"תקומה היתה לו\"); אלא שתקומה זו היתה צ\"ל רק לאחרי ש\"ויקם שדה עפרון — תקומה היתה לו שיצא מיד הדיוט ליד מלך\", וכבר נפקע שם עפרון לגמרי מן השדה [ומ\"ש גם ב\"ויקם\" השני \"מאת בני חת\", ה\"ז רק משום שבתחילה הי' השדה ב­בעלות כללית שלהם<sup data-n=\"778\">44</sup>].\nז. והנה ידוע דחברון<sup data-n=\"779\">45</sup> ובפרט מקום מערת המכפלה הוא המקום הראשון בא\"י שנקנה לעם ישראל בפועל לצמי­תות, וכדאיתא במדרש<sup data-n=\"780\">46</sup> שהוא \"אחד משלשה מקומות שאין אומות העולם יכולין להונות את ישראל לומר גזולים הן בידכם ואלו הן מערת המכפלה<sup data-n=\"781\">47</sup> ובית המקדש וקבורתו של יוסף\".\nוי\"ל שמזה מובן, שיש הוראה בעבו­דה הרוחנית של כאו\"א מישראל ד\"מאַך דאָ ארץ ישראל\"<sup data-n=\"782\">48</sup> (\"עשה כאן א\"י\"), שבכל מקום המצאו צריך יהודי לעשות ארץ ישראל — שעשיית ארץ ישראל היא באופן ש\"תקומה היתה לו, שיצא מיד הדיוט ליד מלך\".\nוביאור הענין:\nכשם שתקומת השדה היתה עוד קודם קבורת שרה, אלא ע\"י זה שנכנס לרשותו של אברהם, הנה עד\"ז בעבודה רוחנית, שכאשר יהודי בא לאיזה מקום או שיש לו שייכות לענין שבעולם שפשוט ש\"מה' מצעדי גבר כוננו ודרכו יחפץ\"<sup data-n=\"783\">49</sup>, לקיים שליחותו לעשות ממנו א\"י, עליו להכיר ולדעת, שע\"י עצם המצאו במקום ההוא הרי \"תקומה היתה לו\", שעוד בטרם גישתו לקיים בו מצוה כו', כבר נעשה במקום ענין של עלי' ותקומה<sup data-n=\"784\">50</sup>, יציאה מיד הדיוט, ע\"י עצם הענין שהוא ברשות ישראל.\nומזה מובן עוד ענין, שאי אפשר שיהי' שום מונע מעבודתו ומעכב לעשות \"כאן ארץ ישראל\", כי מאחר ש\"תקומה היתה לו\", כי כבר יצא מיד הדיוט ליד מלך, ועד למלכו של עולם, ע\"י שנכנס לרשות ישראל, שכל ישראל בני מלכים הם<sup data-n=\"785\">51</sup>, ויתירה מזו, מלכים הם<sup data-n=\"786\">52</sup>, והיינו שגם כאשר הדבר שבעולם הוא לא סתם דבר גשמי אלא ענין ודבר חשוב בעולם (כמו עפרון שלא הי' הדיוט, שהרי עלה לגדולה, מנוהו שוטר עליהם), מ\"מ לגבי",[["778","44","להעיר מריב\"א, פענח רזא ומושב זקנים כאן. וראה בארוכה לקו\"ש חלק ל' (ע' 84, 86)."],["779","45","ראה הערה 47."],["780","46","ב\"ר פע\"ט, ז."],["781","47","בבחיי כאן סוף פסוק כ' חשיב \"שלשה מקומות שהיו מעולים מכל שאר המקומות אשר באו לידם על ידי קניית כסף ואלו הן חברון והר גריזים והר עיבל והר המורי'\", ומביא בנוגע לחברון פסוק שונה מבמדרש — \"לאברהם למקנה וכתיב השדה אשר קנה אברהם\". ואכ\"מ."],["782","48","ראה אגרות קודש אדמו\"ר מהוריי\"ץ נ\"ע כרך א' ע' תפה. וראה לקו\"ש ח\"י בתחלתו ע' 3 ואילך."],["783","49","תהלים לז, כג. וראה \"היום יום\" יו\"ד תמוז. י\"ד מרחשון. ועוד."],["784","50","להעיר גם מהמבואר בכ\"מ שדברים שב­עולם שבהם יכולים לקיים מצוה הם נעלים יותר מדברים שבעולם שאא\"פ לקיים בהם מצוה, ובזה גופא — עילוי בהזמנת הדבר למצוה בפועל (גם קודם הקיום בפועל) — ראה בכ\"ז תו\"א מג\"א צ, סע\"ב ואילך. שערי אורה ד\"ה יביאו לבוש מלכות פ\"ה ואילך, ופע\"ג ובקיצורים לשם. וראה תו\"ש ע' 4. המשך תער\"ב פקע\"ט. סה\"מ תש\"ט ע' 148 בהערה. וראה לקו\"ש חי\"ט ע' 357 ואילך."],["785","51","שבת סז, א."],["786","52","זח\"ב כו, ריש ע\"ב. הקדמת תקו\"ז בתחלתה."]]],[1301670150,"איש ישראל ה\"ז הדיוט, שאינו תופס מקום לגבי איש ישראל, ולגבי כחו ועבודתו לעשות כאן א\"י.\nואופן עשייתו הוא כמו \"מלך\", אמר מלכא עקר טורא<sup data-n=\"787\">53</sup>, שגם כשנראה כאן טורא, יצר הרע שנדמה כהר<sup data-n=\"788\">54</sup>, הרי הוא עוקרו ממקומו ומכניסו לרשות הקדו­שה<sup data-n=\"789\">55</sup>.\nואח\"כ הוא הולך לקיים מצותו להמשיך קדושה בעניני העולם לעשות א\"י בפועל.\nח. ומכל זה הוראה ברורה גם בנוגע לארץ ישראל כפשוטה, שהרי היתרון דמקום השדה ומערת המכפלה שבחברון הוא בכך שהוא אחד משלשה מקומות שאין אומות העולם יכולין להונות את ישראל (כנ\"ל):\nאף שגם בנוגע לכל ארץ ישראל אין מקום לטענת גזילה, כמו שהאריך רש\"י בריש פירושו על התורה, \"כל הארץ של הקב\"ה היא, הוא בראה ונתנה לאשר ישר בעיניו, ברצונו נתנה להם וברצונו נטלה מהם ונתנה לנו\", מ\"מ ה\"ז מענה לאומות העולם שטוענים לישראל \"לסטים אתם\", אבל<sup data-n=\"790\">56</sup> בג' מקומות אלו אין שם אפילו קס\"ד לטענה שיצטרכו לענות להם, מאחר שג' מקומות אלו באו לידם ע\"י תשלום כסף.\nוטעם הדבר מובן ע\"פ מ\"ש במפר­שים<sup data-n=\"791\">57</sup> שהיחוד בג' מקומות אלו הוא בזה שמקומות אלו מיוחדים בקדושתם תמיד, גם בזמן הגלות: מקום המקדש, דתמיד בקדושתו עומד כמו שארז\"ל ופסק ה­רמב\"ם<sup data-n=\"792\">58</sup> להלכה דקדושת המקדש מפני השכינה ושכינה אינה בטילה לעולם, \"לא זזה השכינה מתוך ההיכל. . אין השכינה זזה מכותל מערבי\"<sup data-n=\"793\">59</sup>. וכן מערת המכפלה מקום קבורת האבות שעל ידה עוברת התפלה דכל ישראל<sup data-n=\"794\">60</sup>, ומעין זה לגבי מקום קבורתו של יוסף<sup data-n=\"795\">61</sup>.\nועפ\"ז י\"ל, דמג' מקומות אלו גופא, הרי מקום מערת המכפלה מיוחד בזה, שנוסף ע\"ז שנקנה לאברהם לפני כיבוש הארץ, הי' זה המקום הראשון בארץ ישראל שנקנה לאברהם שקנהו עבור קבורת שרה, אמו של יצחק בלי כל שייכות לישמעאל, דשייכותה של שרה היא רק לעם ישראל<sup data-n=\"796\">62</sup>, ומאז הי' שם מקום קבורת אבות דבנ\"י אברהם ושרה יצחק ורבקה יעקב ולאה.\nועל ידי חברון ומערת המכפלה ניתן תוקף וחיזוק, תוקף דמלך, שארץ ישראל תשאר לבנ\"י גם ברגעים האחרונים דגלות, ובקרוב ממש נזכה לביאת משיח צדקנו, שאז תהי' כל ארץ ישראל ב­שלימותה, ירחיב ה\"א את גבולך, גם ארץ קיני קניזי וקדמוני<sup data-n=\"797\">63</sup>, שניתנו בברית בין הבתרים לאברהם אבינו, באופן ד­\"לזרעך<sup data-n=\"798\">64</sup> נתתי את הארץ הזאת מנהר מצרים עד הנהר הגדול נהר פרת את הקיני ואת הקניזי ואת הקדמוני\", ביחד עם ארץ ז' האומות, במהרה בימינו ממש.\n<span data-k=\"q\">(משיחות כ\"ף מ\"ח וש\"פ ח\"ש תשמ\"ו)</span>",[["787","53","ראה ב\"ב ג, ב."],["788","54","סוכה נב, א."],["789","55","ראה לקו\"ש ח\"ט ע' 349 בשוה\"ג."],["790","56","ראה יפ\"ת השלם לב\"ר שם."],["791","57","נזר הקודש לב\"ר שם."],["792","58","הל' ביהב\"ח ספ\"ו."],["793","59","שמו\"ר פ\"ב, ב."],["794","60","ראה לקו\"ש חכ\"ה ע' 98. וש\"נ."],["795","61","ראה נזר הקודש שם."],["796","62","ראה לקו\"ש חט\"ו ע' 147 ואילך."],["797","63","פ' ראה יב, כ. ספרי שם. שופטים יט, ח. רש\"י שם."],["798","64","לך טו, יח­יט."]]],[1301670151,"<h3>שיחה ב</h3>\nא. \"ואברהם זקן בא בימים\"<sup data-n=\"799\">1</sup>. וכתב הכלי יקר, \"הרבה מפרשים תמהו והלא כבר נאמר [לעיל בפ' וירא<sup data-n=\"800\">2</sup>] ואברהם ושרה זקנים באים בימים והי' כמו ל\"ז<sup data-n=\"801\">3</sup> שנים בין שני זמנים אלו\" — ומהו שנאמר כאן \"ואברהם זקן בא בימים\", שרק עתה נזדקן כו'?\nוהנה תמי' זו היא (גם) לפי פשוטו של מקרא, וצ\"ע למה לא מצינו יישוב עלי' בפירוש רש\"י על התורה [וכמשנ\"ת כמ\"פ, שבפירושו על התורה מיישב רש\"י כל דבר הקשה בפשוטו של מקרא, ובמקום שלא מצא רש\"י פירוש (מספיק) ליישב המקראות ע\"פ פשוטם, כ' רש\"י<sup data-n=\"802\">4</sup> \"איני יו­דע\" וכיו\"ב].\nוהנה במדרש<sup data-n=\"803\">5</sup> איתא \"כבר כתיב ואבר­הם ושרה זקנים, מה ת\"ל ואברהם זקן, אלא שהחזירו הקב\"ה לימי נערותיו צריך לכתוב פעם שני' ואברהם זקן\". ולכאורה אפשר לומר שתירוץ זה יש לו מקום גם לפי פשוטו של מקרא<sup data-n=\"804\">6</sup>, וכמפורש ב­פרש\"י<sup data-n=\"805\">7</sup> בנוגע לשרה שהקב\"ה בירכה \"ש­חזרה לנערותה\" [וכפשטות הכתובים דפ' וירא, דאע\"פ ש\"(ואברהם ושרה זקנים גו') חדל להיות לשרה אורח גו' אחרי בלותי היתה לי עדנה ואדוני זקן\"<sup data-n=\"806\">8</sup>, מ\"מ נולד לשרה בן ו\"היניקה בנים שרה\"<sup data-n=\"807\">9</sup>], ומזה מובן, לכאורה, גם בנוגע לאברהם, דאע\"פ שמלכתחילה \"ואברהם ושרה זקנים באים בימים\" (וכדברי שרה \"אחרי בלותי גו' ואדוני זקן\", שגם אצל אברהם כבר עבר הזמן שיוכל להוליד בנים<sup data-n=\"808\">10</sup>), מ\"מ חזר לנערותו. ולכן הוצרך הכתוב להודיע, שאחרי שעברו (כמו) ל\"ז<sup data-n=\"801\">3</sup> שנה מלידת יצחק, שוב \"ואברהם זקן בא בימים\".\nאבל, אי אפשר לתרץ כן בדרך הפשט, כי מצינו אח\"כ (בסוף הפרשה<sup data-n=\"810\">11</sup>) שאברהם נשא אשה אחרת והוליד ממנה כמה בנים (בני קטורה)<sup data-n=\"811\">12</sup>.\nב. עוד תירוץ מצינו במדרש<sup data-n=\"803\">5</sup>, \"כאן [בפ' וירא] זקנה שיש בה לחלוחית ולהלן [בפרשתנו] בזקנה שאין בה לחלוחית\", היינו, שבפ' וירא מדובר בתחילת ימי ה­זקנה כשעדיין יש באדם \"לחלוחית\", משא\"כ \"ואברהם זקן\" בפרשתנו פירושו זקנה ש\"אין בו לחלוחית\"<sup data-n=\"813\">13</sup>.",[["799","1","פרשתנו כד, א."],["800","2","יח, יא."],["801","3","כ\"ה בכלי יקר. ולכאורה צ\"ע, שהרי הי' בערך מ\"א שנה, כי \"ואברהם ושרה זקנים גו'\" הי' שנה לפני לידת יצחק, ו\"אברהם זקן גו'\" דפרשתנו הי' קצת קודם נישואי יצחק ורבקה, ו\"יצחק בן ארבעים שנה בקחתו את רבקה\" (תולדות כה, כ). — וראה אברבנאל (השאלה הא') ועוד פרשתנו."],["802","4","ראה לדוגמא פרש\"י תולדות כח, ה. ועוד (נסמנו בלקו\"ש ח\"ה ע' 1 בהערה)."],["803","5","ב\"ר וירא שם (פמ\"ח, טז)."],["804","6","וצע\"ק בכלי יקר שם, שכ' שפירוש זה \"אין לו סמך מן המקרא\"."],["805","7","לך לך יז, טז."],["806","8","יח, יא­יב וכפרש\"י שם."],["807","9","וירא כא, ז. וראה רש\"י שם."],["808","10","ראה גם לקמן ע' 94. — ובלקו\"ש ח\"כ ע' 80 ואילך נת' באו\"א, שאצל אברהם לא היתה מלכת­חילה תשות כח בנוגע ללידה. ע\"ש. ואכ\"מ."],["801","3","כ\"ה בכלי יקר. ולכאורה צ\"ע, שהרי הי' בערך מ\"א שנה, כי \"ואברהם ושרה זקנים גו'\" הי' שנה לפני לידת יצחק, ו\"אברהם זקן גו'\" דפרשתנו הי' קצת קודם נישואי יצחק ורבקה, ו\"יצחק בן ארבעים שנה בקחתו את רבקה\" (תולדות כה, כ). — וראה אברבנאל (השאלה הא') ועוד פרשתנו."],["810","11","כה, א ואילך."],["811","12","וראה לקמן שם ואילך, שזה הי' נס נוסף, ששוב חזר לנערותו כו'. אבל לכאורה אין זה פשוטו ממש. — וראה לקו\"ש ח\"כ הנ\"ל. ואכ\"מ."],["803","5","ב\"ר וירא שם (פמ\"ח, טז)."],["813","13","ולפירוש זה, תוכן הזקנה כאן אינו בשייכות לענין הלידה (ראה נזר הקודש (השלם) לב\"ר וירא שם)."]]],[1301670152,"אבל לכאורה אין לחילוק זה שייכות לדרך הפשט, שהרי בשני המקומות נאמ­רה אותה הלשון \"זקן בא בימים\" (\"זקנים באים בימים\"), ולמה לא נרמז בלשון הכתוב חילוק זה בין שני שלבי זקנה (כמו \"זקן מאד\" וכיו\"ב)?\nברמב\"ן<sup data-n=\"814\">14</sup> מפרש, שיש חילוק בין \"ב­אים בימים\" דפ' וירא ו\"בא בימים\" דפר­שתנו, כי \"באים בימים\" הוא לשון הווה, \"כמו הבאים<sup data-n=\"815\">15</sup> בשערים האלה\", ולכן פירושו ש\"מתחילים בימי הזקנה\" (כש­עדיין \"יש בה לחלוחית\"), שנכנסים ובאים עתה לימי זקנה; משא\"כ \"בא בימים\" הוא לשון עבר, \"כמו בא<sup data-n=\"816\">16</sup> אחיך במרמה\", ופירושו \"שכבר בא בימים\".\nאבל קשה לומר שגם רש\"י ס\"ל חילוק זה בפירוש כתובים אלה, דא\"כ הו\"ל לכ­תוב כן בפירוש, וע\"ד שמצינו להלן ב­פרש\"י (בפ' ויצא<sup data-n=\"817\">17</sup>), שמפרש החילוק בין ב' הפעמים שנאמר שרחל \"באה\", \"הרא­שון [ש\"הטעם באל\"ף\"] לשון עושה וה­שני<sup data-n=\"818\">18</sup> [ש\"הטעם למעלה בבי\"ת\"] לשון עשתה\"<sup data-n=\"819\">19</sup>.\nג. ויובן זה בהקדים פירוש כפל ה­לשון \"זקנים באים בימים\" (וכן כאן \"זקן בא בימים\") — דלכאורה יש להבין, מהי ההוספה בלשון \"בא(ים) בימים\" על \"זקן\"?\nוגם בזו — לא מצינו שרש\"י בפירושו על התורה יפרש לשון זו. ועכצ\"ל, דס\"ל שהפירוש של \"בא בימים\" הוא פשוט כדי כך עד שאין צורך לפרשו.\nוהנה לפי כמה פשטנים, הלשון \"בא בימים\" מורה על זקנה מופלגת, וכפירוש הראב\"ע<sup data-n=\"820\">20</sup> \"באים בימים\" — \"הגיעו לימים רבים\". אבל צ\"ע, איך נרמז בלשון \"בא בימים\" שהכוונה ל\"ימים רבים\" עוד יותר מסתם \"זקנה\".\n[ברמב\"ן<sup data-n=\"821\">21</sup> כ': \"האדם בימי בחרותיו יקרא עומד בימים, ויקראו ימיו כי הם שלו. . אבל כאשר יזקין ויחי' ימים רבים מרוב בני האדם בדורו יקרא בא בימים מפני שהוא כבא בארץ אחרת כו'\". אבל לכאורה אין זו פשטות משמעות הביטוי \"בא בימים\"<sup data-n=\"822\">22</sup>, ועד כדי לומר שלא הוזקק רש\"י לפרשו בהדיא וסומך על הלומד מקרא (הכולל גם \"בן חמש\"<sup data-n=\"823\">23</sup>) שיבין זה מעצמו!].\nועוד זאת: הגיל של בן מאה שנה לאיש (שני אברהם) ובן צ' לאשה (שני שרה) לא נחשב, לכאורה, לזקנה מופלגת בתקופה ההיא. ויתר על כן: הלשון \"זקן בא בימים\" מצינו גם אצל דוד (בהפטרת פרשתנו<sup data-n=\"824\">24</sup>)",[["814","14","פרשתנו כד, א. וראה גם כלי יקר שם."],["815","15","ירמי' ז, ב."],["816","16","תולדות כז, לה."],["817","17","כט, ו. וכן בפרש\"י לעיל לך (טו, יז). ע\"ש. רש\"י ויגש (מו, כו — הובא ביפה תואר (השלם) לב\"ר שם)."],["818","18","ויצא שם, ט."],["819","19","כלומר: אע\"פ שגם בנדו\"ד, \"הטעם\" ב­תיבת \"באים\" (בכתוב \"ואברהם ושרה זקנים באים בימים\") הוא \"באלף\" (לשון הווה) — מ\"מ, את\"ל שרש\"י ס\"ל שזהו החילוק בין שני הכתובים, הו\"ל לפרש כן להדיא (כבמקומות שבהערה 17). ומדלא פירש כן משמע דס\"ל שגם \"ואברהם זקן בא בימים\" הוא ל' הווה (ולא עבר). וראה גם עקידה פרשתנו, שהקשה על פי' הרמב\"ן."],["820","20","וירא שם (יח, יא). — וראה גם רד\"ק שם: \"מנהג הכתוב לאמר הלשון הזו על האדם שגברה וכבדה עליו הזקנה שהוא בא בימים הידועים שהם דרך כל הארץ\", ועד\"ז פי' בפרשתנו כאן \"בימים שהם השלמת ימי אדם בעולם\"."],["821","21","וירא שם."],["822","22","וכן פי' הרד\"ק הנ\"ל (הערה 20) \"בימים הידועים\", \"השלמת ימי אדם כו'\" — לא מונח בפשטות הל' \"בא בימים\". ועכ\"פ, אם רש\"י ס\"ל כן הו\"ל לפרשו להדיא."],["823","23","כפסק המשנה אבות ספ\"ה."],["824","24","מ\"א בתחלתו."]]],[1301670153,"בהיותו קרוב לבן שבעים שנה<sup data-n=\"825\">25</sup>, שגיל זה בודאי אינו נחשב<sup data-n=\"826\">26</sup> לזקנה מופלגת<sup data-n=\"827\">27</sup>.\nד. ויש לומר הביאור בזה:\nהפירוש ד\"בא בימים\" הוא — כפשטות התיבות — שהגיע ובא (נכנס) בתוך הימים, כמו בא בבית וכיו\"ב. זאת אומרת, שאין זה תיאור מספר שנות האדם (אם רב או מעט), אלא אופן חיי האדם בימים אלו.\nכלומר: הימים שעברו על האדם וה­מאורעות שבהם, אינם כמו דבר העובר וחולף שלא נשאר ממנו רושם, כי אם הם באופן שהאדם \"הכניס\" את מהותו ונפשו בתוך כל יום ויום ומאורעותיו והר­פתקאותיו, שאז כל יום ויום וכל מאורע ומאורע (הן דבר המשמח, והן הפכו ח\"ו) פועל ומשפיע עליו, עד שניכר בגלוי בתווי פניו כו'<sup data-n=\"828\">28</sup>.\n[וכפי שרואים במוחש, שאין כל בני אותו גיל דומים זל\"ז, ולפעמים א' מהם נראה יותר מבוגר מזולתו, כי ניכר עליו רושם המאורעות שעברו עליו, מכיון שכל מאורע כו' נגע לל בו].\nוזהו גם פירוש הלשון \"זקן בא בימים\" אצל דוד, אף שמספר שנות חייו הי' קרוב לשבעים שנה בלבד, כי ריבוי המאורעות שעברו עליו (כמו ריבוי המלחמות, עגמת נפש מבנו כו' וכיו\"ב), הותירו את רישומן עליו, באופן של \"בא בימים\".\nוזהו \"ואברהם ושרה זקנים באים ב­ימים\", שלא רק שהיו \"זקנים\" מפני מספר שנות חייהם, אלא עוד זאת, שימי חייהם לא חלפו ועברו מהם, אלא היו באופן של \"באים בימים\", כנ\"ל.\nה. עפ\"ז יש לבאר גם מ\"ש בפרשתנו עוד פעם \"ואברהם זקן בא בימים\" — דיש לומר, שעיקר החידוש אינו בתיבת \"זקן\" (כי גם לפנ\"ז הי' זקן, כנ\"ל), אלא בכך שהי' \"בא בימים\":\nמטבע הדברים, שככל שהאדם הולך ומתבגר, אין המאורעות מסביבו משפיעים עליו (כל כך) — אם מפני שנעשה מתון יותר (\"כל זמן שהם מזקינים דעתם מתיישבת\"<sup data-n=\"829\">29</sup>), או לפי שטבעו של זקן שכבר עבר הרבה בחייו, שאין הדברים שסביבו תופסים מקום אצלו.\nולכן, אף שכבר נאמר \"ואברהם ושרה זקנים באים בימים\", מצד ריבוי המאו­רעות שעברו עליהם עד הזמן ההוא, מ\"מ יש צורך להודיע ולחדש שגם לאחרי שעברו אצל אברהם עוד ל\"ז<sup data-n=\"801\">3</sup> שנה, הי' \"אברהם [לא רק] זקן [אלא גם] בא בימים\",",[["825","25","משא\"כ מ\"ש ביהושע (יהושע יג, א) \"זקן בא בימים\" — לאחרי ז' שני כיבוש — הי' לכה\"פ קרוב לתשעים שנה (ראה סדר הדורות ב\"א תמח. ועוד).\nולהעיר שגם אצל יהושע נכפל עוד הפעם הלשון \"זקן בא בימים\" (יהושע כג, א). ואכ\"מ."],["826","26","ראה גם יפה תואר (השלם) לב\"ר פרשתנו (שבהערה 28)."],["827","27","להעיר (ע\"ד ההלכה) מטור יו\"ד ר\"ס רמד \"שיבה שהוא מופלג בזקנה דהיינו בן שבעים\". אבל שם עיקר ההדגשה הוא על \"שיבה\" דקאי על בן שבעים (אבות ספ\"ה), וכמ\"ש בב\"י שם. וראה רמב\"ם הל' סנהדרין (פ\"ב ה\"ג), דמוכח שם, ד\"זקן מופלג בשנים\" הוא יותר מ\"בעלי שיבה\" (ראה לח\"מ שם. רמב\"ם שם ה\"ו). וראה גיטין (כח, א) \"כיון דאיפליג כו'\", וקאי על יותר מבן תשעים (ראה רש\"י שם). ואכ\"מ."],["828","28","בב\"ר פרשתנו (פנ\"ט, ו) \"יש לך אדם שהוא בזקנה ואינו בימים [שקפצה עליו זקנה], בימים ואינו בזקנה [שהזקנה אינה ניכרת עליו], אבל כאן זקנה כנגד ימים וימים כנגד זקנה\" (וראה במפרשים שם, המעלה שבזה). ולפ\"ז, \"זקן\" היינו תואר ופעולת הזקנה, ו\"בא בימים\" קאי על כמות הזמן (\"ימים\"). וכן פי' במצו\"ד ליהושע (יג, א).\nאבל פשטות הפירוש דתיבת \"זקן\" אינה תואר על פעולת הזקנה, אלא ריבוי כמות של שנים, כדמצינו בכמה קראי. ולאידך, בלשון \"בא בימים\" אינו מודגש כ\"כ ריבוי הימים."],["829","29","משנה קנים ספ\"ג."],["801","3","כ\"ה בכלי יקר. ולכאורה צ\"ע, שהרי הי' בערך מ\"א שנה, כי \"ואברהם ושרה זקנים גו'\" הי' שנה לפני לידת יצחק, ו\"אברהם זקן גו'\" דפרשתנו הי' קצת קודם נישואי יצחק ורבקה, ו\"יצחק בן ארבעים שנה בקחתו את רבקה\" (תולדות כה, כ). — וראה אברבנאל (השאלה הא') ועוד פרשתנו."]]]]});
